    static let libraryQuotes: [BibleVerse] = [
        BibleVerse(
            textHy: "Երանելի է այն մարդը, որ ամբարիշտների խորհրդի մէջ չէ գնում, եւ մեղաւորների ճանապարհի մէջ չէ կանգնում, եւ ծաղր անողների աթոռի վերայ չէ նստում. Այլ նորա կամքը Տիրոջ օրէնքի մէջ է, եւ ցերեկ ու գիշեր նորա օրէնքի վերայ է մտածում։ Եւ նա ջրերի գնացքումը տնկուած ծառերի պէս է, որ իր պտուղը տալիս է իրան ժամանակին, եւ նորա տերեւը չէ թափվում, եւ ամեն ինչ որ անում է յաջողվում է նորան։",
            textHyArarat: "Երանելի է այն մարդը, որ ամբարիշտների խորհրդի համաձայն չի գնում և մեղավորների ճանապարհի մեջ չի կանգնում և ծաղր անողների աթոռի վրա չի նստում, Այլ նրա հաճույքը Տիրոջ օրենքի մեջ է, և ցերեկ ու գիշեր մտածում է նրա օրենքի մասին։ Նա ջրերի հոսանքի մոտ տնկված ծառի պես է, որ իր պտուղը տալիս է իր ժամանակին, և նրա տերևը թառամելով չի թափվում, և ամեն ինչ, որ անում է, հաջողվում է նրան։",
            textRu: "Блажен муж, который не ходит на совет нечестивых и не стоит на пути грешных и не сидит в собрании развратителей, но в законе Господа воля его, и о законе Его размышляет он день и ночь! И будет он как дерево, посаженное при потоках вод, которое приносит плод свой во время свое, и лист которого не вянет; и во всем, что он ни делает, успеет.",
            textEn: "Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful. But his delight is in the law of the LORD; and in his law doth he meditate day and night. And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper.",
