        BibleVerse(
            textHy: "Տէր, իմ վէմ, եւ իմ բերդ եւ իմ ազատիչ. իմ Աստուած, իմ ամրութիւն, որին ես յուսացած եմ։ Ով իմ ասպար եւ իմ փրկութեան եղջիւր, նա իմ բարձր աշտարակն է.",
            textHyArarat: "Տե՛ր, իմ վե՛մ և իմ ամրո՛ց և իմ ազատարա՛ր. իմ Աստվա՛ծ, իմ վե՛մ, որտեղ ապաստան եմ գտնում։ Ո՛վ իմ վահան և իմ փրկությա՛ն եղջյուր. նա իմ ապավենն է։",
            textRu: "Господь — твердыня моя и прибежище мое, Избавитель мой, Бог мой, — скала моя; на Него я уповаю; щит мой, рог спасения моего и убежище мое.",
