        BibleVerse(
            textHy: "Տիրոջ օրէնքը անարատ է, հանգստացնում է հոգիին. Տիրոջ վկայութիւնը ճշմարիտ է, իմաստուն է անում պարզամիտին։ Տիրոջ պատուիրանքները ուղիղ են, ուրախացնում են սիրտը. Տիրոջ հրամանները մաքուր են, լուսաւորում են աչքերը։",
            textHyArarat: "Տիրոջ օրենքը կատարյալ է և նորոգում է հոգին. Տիրոջ պատվիրանը ճշմարիտ է և իմաստուն է դարձնում պարզամիտին։ Տիրոջ հրահանգներն ուղիղ են, ուրախացնում են սիրտը. Տիրոջ պատվերները մաքուր են, լուսավորում են աչքերը։",
