        BibleVerse(
            textHy: "Դու իմ առաջին սեղան ես պատրաստում իմ թշնամիների դիմաց. դու իմ գլուխն օծում ես իւղով. իմ բաժակը խիստ լիքն է։ Հէնց բարիք եւ ողորմութիւն կգան իմ ետեւիցն իմ կեանքի բոլոր օրերումը. եւ Տիրոջ տանը կբնակուիմ շատ երկար ժամանակ։",
            textHyArarat: "Դու սեղան ես պատրաստում իմ առջև՝ իմ թշնամիների դիմաց. դու իմ գլուխն օծում ես յուղով, իմ բաժակը լեփ-լեցուն է։ Այսպես բարիքը և ողորմությունը կգան իմ հետևից իմ կյանքի բոլոր օրերին, և Տիրոջ տանը կբնակվեմ ամբողջ կյանքիս ընթացքում։",
