        BibleVerse(
            textHy: "Մէկ բան եմ խնդրում Տէրիցը. եւ այն շատ կփափաքէի, որ Տիրոջ տանը բնակուիմ իմ կեանքի բոլոր օրերը, որ Տիրոջ գեղեցիկ փառքը տեսնեմ եւ նորա տաճարին զննելով մտիկ տամ։ Որովհետեւ չար օրումը՝ նա ծածկում է ինձ իր խորանի մէջ. նա թագցնում է ինձ իր խորանի ծածուկ տեղումը, եւ բարձրացնում է ինձ վէմի վերայ։",
            textHyArarat: "Մի բան եմ խնդրում Տիրոջից և շատ պիտի փափագեի այն, որ Տիրոջ տանը բնակվեմ իմ կյանքի բոլոր օրերին, որ Տիրոջ գեղեցիկ վայելչությունը տեսնեմ և նրա տաճարի մեջ խորհրդածեմ։ Որովհետև չար օրը նա ինձ ծածկում է իր բնակարանում, նա թաքցնում է ինձ իր վրանի ծածուկ տեղում և ինձ բարձրացնում է վեմի վրա։",
            textRu: "Одного просил я у Господа, того только ищу, чтобы пребывать мне в доме Господнем во все дни жизни моей, созерцать красоту Господню и посещать храм Его, ибо Он укрыл бы меня в скинии Своей в день бедствия, скрыл бы меня в потаенном месте селения Своего, вознес бы меня на скалу.",
