        BibleVerse(
            textHy: "Տէրն է իմ զօրութիւնը եւ իմ վահանը. իմ սիրտը նորան է յուսացել, եւ նա ինձ օգնութիւն եղաւ. իմ սիրտը ցնծում է եւ ես իմ օրհնութիւնովը փառաբանում եմ նորան։",
            textHyArarat: "Տերն է իմ զորությունը և իմ վահանը. իմ սիրտը նրան է հուսացել, և նա օգնեց ինձ. իմ սիրտը ցնծում է, և ես փառաբանում եմ նրան իմ օրհներգությամբ։",
            textRu: "Господь — крепость моя и щит мой; на Него уповало сердце мое, и Он помог мне, и возрадовалось сердце мое; и я прославлю Его песнью моею.",
            textEn: "The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.",
            refHy: "Սաղմոսներ 28:7",
            refRu: "Псалом 27:7",
            refEn: "Psalm 28:7"
        ),
        BibleVerse(
            textHy: "Տէրը զօրութիւն կտայ իր ժողովրդին. Տէրը կօրհնէ իր ժողովուրդը խաղաղութիւնով։",
            textHyArarat: "Տերը զորություն կտա իր ժողովրդին. Տերը խաղաղությամբ կօրհնի իր ժողովրդին։",
            textRu: "Господь даст силу народу Своему, Господь благословит народ Свой миром.",
            textEn: "The LORD will give strength unto his people; the LORD will bless his people with peace.",
            refHy: "Սաղմոսներ 29:11",
            refRu: "Псалом 28:11",
            refEn: "Psalm 29:11"
        ),
        BibleVerse(
            textHy: "Նորա բարկութիւնը ակնթարթի չափ է, բայց նորա քաղցրութիւնը բոլոր կեանքումը. իրիկունը լաց է գալիս, իսկ առաւօտը ցնծութիւն։",
            textHyArarat: "Նրա բարկությունն ակնթարթի չափ է, իսկ նրա բարեհաճությունը ամբողջ կյանքում է. գիշերը լաց կա, իսկ առավոտյան՝ ցնծություն։",
            textRu: "На мгновение гнев Его, на всю жизнь благоволение Его: вечером водворяется плач, а на утро радость.",
            textEn: "His anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.",
            refHy: "Սաղմոսներ 30:5",
            refRu: "Псалом 29:5",
            refEn: "Psalm 30:5"
