        BibleVerse(
            textHy: "Իմաստուն կանեմ քեզ, եւ կսովորեցնեմ քեզ այն ճանապարհը, որ նորանում պիտի գնաս. կխրատեմ քեզ՝ իմ աչքը քեզ վերայ կլինի։",
            textHyArarat: "«Կուսուցանեմ քեզ և կսովորեցնեմ քեզ այն ճանապարհը, որով պիտի գնաս. կխրատեմ քեզ, իմ աչքը քեզ վրա կլինի։",
            textRu: "«Вразумлю тебя, наставлю тебя на путь, по которому тебе идти; буду руководить тебя, око Мое над тобою».",
            textEn: "I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.",
            refHy: "Սաղմոսներ 32:8",
            refRu: "Псалом 31:8",
            refEn: "Psalm 32:8"
        ),
        BibleVerse(
            textHy: "Ես խնդրեցի Տիրոջը, եւ նա պատասխան տուաւ ինձ, եւ իմ ամեն ահ ու վախիցն ազատեց ինձ։ Նորան են մտիկ տալիս եւ լուսաւորվում. եւ նորանց երեսը չի ամաչիլ։",
            textHyArarat: "Ես դիմեցի Տիրոջը, և նա պատասխան տվեց ինձ և իմ ամեն սարսափից ազատեց ինձ։ Նրան նայեցին և լուսավորվեցին, և նրանց երեսը չպիտի ամաչի։",
            textRu: "Я взыскал Господа, и Он услышал меня, и от всех опасностей моих избавил меня. Кто обращал взор к Нему, те просвещались, и лица их не постыдятся.",
            textEn: "I sought the LORD, and he heard me, and delivered me from all my fears. They looked unto him, and were lightened: and their faces were not ashamed.",
            refHy: "Սաղմոսներ 34:4-5",
            refRu: "Псалом 33:4-5",
            refEn: "Psalm 34:4-5"
        ),
        BibleVerse(
            textHy: "Տէր, քո ողորմութիւնը երկնքումն է, եւ քո ճշմարտութիւնը հասնում է մինչեւ ամպերը։ Քո արդարութիւնը ինչպէս Աստուծոյ սարերն է. եւ քո իրաւունքը ինչպէս մեծ անդունդ. դու ես փրկում մարդկանց եւ անասուններին, Տէր։",
            textHyArarat: "Տե՛ր, քո ճշմարտությունը մինչև երկինք է հասնում, և քո հավատարմությունը՝ մինչև ամպերը։ Քո արդարությունը Աստծու լեռների պես է, և քո իրավունքը՝ մեծ անդունդի պես. դու ես փրկում մարդկանց և անասուններին, Տե՛ր։",
            textRu: "Господи! милость Твоя до небес, истина Твоя до облаков! Правда Твоя, как горы Божии, и судьбы Твои — бездна великая! Человеков и скотов хранишь Ты, Господи!",
            textEn: "Thy mercy, O LORD, is in the heavens; and thy faithfulness reacheth unto the clouds. Thy righteousness is like the great mountains; thy judgments are a great deep: O LORD, thou preservest man and beast.",
            refHy: "Սաղմոսներ 36:5-6",
            refRu: "Псалом 35:5-6",
            refEn: "Psalm 36:5-6"
        ),
        BibleVerse(
            textHy: "Կեանքի աղբիւրը քեզ մօտ է. եւ քո լոյսովն ենք տեսնում լոյս։",
            textHyArarat: "Քեզ մոտ է կյանքի աղբյուրը, և քո լույսով ենք լույսը տեսնում։",
            textRu: "У Тебя источник жизни; во свете Твоем мы видим свет.",
            textEn: "With thee is the fountain of life: in thy light shall we see light.",
            refHy: "Սաղմոսներ 36:9",
            refRu: "Псалом 35:9",
            refEn: "Psalm 36:9"
