        BibleVerse(
            textHy: "Ինչպէս որ եղջերուն փափաքում է ջրերի առուների, այնպէս էլ իմ անձը փափաքում է քեզ, ով Աստուած։ Իմ անձը ծարաւ է Աստուծուն՝ կենդանի Աստուծուն. ե՜րբ կգամ եւ նորա երեսի առաջին կերեւամ։",
            textHyArarat: "Ինչպես եղջերուն է փափագում ջրի առուներին, այնպես էլ իմ անձը փափագում է քեզ, ո՜վ Աստված։ Իմ անձը ծարավ է Աստծուն՝ կենդանի Աստծուն. ե՞րբ պիտի գամ և երևամ նրա առջև։",
            textRu: "Как лань желает к потокам воды, так желает душа моя к Тебе, Боже! Жаждет душа моя к Богу крепкому, живому: когда приду и явлюсь пред лице Божие!",
            textEn: "As the hart panteth after the water brooks, so panteth my soul after thee, O God. My soul thirsteth for God, for the living God: when shall I come and appear before God?",
            refHy: "Սաղմոսներ 42:1-2",
            refRu: "Псалом 41:1-2",
            refEn: "Psalm 42:1-2"
        ),
        BibleVerse(
            textHy: "Ով Աստուած, դու ես իմ Աստուածը. առաւօտանց քեզ եմ ման գալիս. հոգիս ծարաւ է քեզ համար. մարմինս քեզ է ցանկանում ցամաք եւ ծարաւ երկրում, ուր որ ջուր չկայ։ Այնպէս սրբութեան տեղումը նայեցի քեզ, որ քո զօրութիւնն ու փառքը տեսնեմ։ Որովհետեւ քո ողորմութիւնը լաւ է քան թէ կեանքը. իմ շրթունքներս պիտի գովեն քեզ։",
            textHyArarat: "Ո՜վ Աստված, դու ես իմ Աստվածը, քեզ եմ փնտրում առավոտից. հոգիս ծարավի է քեզ, մարմինս քեզ է ցանկանում այս ցամաք ու ծարավ երկրում, որտեղ ջուր չկա։ Այսպես սրբարանում նայեցի քեզ, որ քո զորությունն ու փառքը տեսնեմ, Որովհետև քո ողորմությունն ավելի լավ է, քան կյանքը. իմ շրթունքները պիտի գովեն քեզ։",
            textRu: "Боже! Ты Бог мой, Тебя от ранней зари ищу я; Тебя жаждет душа моя, по Тебе томится плоть моя в земле пустой, иссохшей и безводной, чтобы видеть силу Твою и славу Твою, как я видел Тебя во святилище: ибо милость Твоя лучше, нежели жизнь. Уста мои восхвалят Тебя.",
            textEn: "O God, thou art my God; early will I seek thee: my soul thirsteth for thee, my flesh longeth for thee in a dry and thirsty land, where no water is; To see thy power and thy glory, so as I have seen thee in the sanctuary. Because thy lovingkindness is better than life, my lips shall praise thee.",
            refHy: "Սաղմոսներ 63:1-3",
            refRu: "Псалом 62:1-3",
            refEn: "Psalm 63:1-3"
        ),
        BibleVerse(
            textHy: "Ո՞վ ունիմ ես երկնքումը, եւ քեզանից ջոկ բան չեմ ուզում երկրի վերայ։ Թէեւ մարմինս ու սիրտս մաշուին. Աստուած յաւիտեան իմ սրտի ոյժն ու իմ բաժինն է։",
            textHyArarat: "Ո՞վ ունեմ ես երկնքում, երկրի վրա էլ քեզնից բացի ուրիշ բան չեմ ուզում։ Թեև մաշվում են սիրտս ու մարմինս, սակայն Աստված հավիտյան իմ սրտի ուժն է և իմ բաժինը։",
            textRu: "Кто мне на небе? и с Тобою ничего не хочу на земле. Изнемогает плоть моя и сердце мое: Бог твердыня сердца моего и часть моя вовек.",
