        BibleVerse(
            textHy: "Քանի՜ սիրելի են քո բնակարանները, ով Զօրաց Տէր։ Իմ անձը ցանկանում է եւ փափաքում Տիրոջ սրահներին, իմ սիրտը եւ իմ մարմինը ցնծում են կենդանի Աստուծով։",
            textHyArarat: "Ինչքա՜ն սիրելի են քո բնակարանները, ո՛վ Զորությունների Տեր։ Իմ անձը ցանկանում և փափագում է Տիրոջ սրահները, իմ սիրտը և իմ մարմինը ցնծությամբ աղաղակում են կենդանի Աստծուն։",
            textRu: "Как вожделенны жилища Твои, Господи сил! Истомилась душа моя, желая во дворы Господни; сердце мое и плоть моя восторгаются к Богу живому.",
