        BibleVerse(
            textHy: "Դու, Տէր, բարի ես եւ ներող, եւ ողորմութիւնով հարուստ բոլոր քեզ կանչողներին։",
            textHyArarat: "Դու, Տե՛ր, բարի ես և ներող և ողորմությամբ հարուստ բոլոր քեզ կանչողների համար։",
