        BibleVerse(
            textHy: "Սովորեցրու մեզ, որ այնպէս համարենք մեր օրերը, որ իմաստուն սիրտ ընդունենք։",
            textHyArarat: "Սովորեցրո՛ւ մեզ, որ այնպես հաշվենք մեր օրերը, որ սրտով իմաստուն լինենք։",
            textRu: "Научи нас так счислять дни наши, чтобы нам приобрести сердце мудрое.",
