            textHyArarat: "Տերը պիտի պահպանի քեզ ամեն չարից. նա պիտի պահպանի քո անձը։ Տերը պիտի պահպանի քո երթուդարձը՝ այսուհետև մինչև հավիտյան։",
            textRu: "Господь сохранит тебя от всякого зла; сохранит душу твою. Господь будет охранять выхождение твое и вхождение твое отныне и вовек.",
            textEn: "The LORD shall preserve thee from all evil: he shall preserve thy soul. The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.",
