        BibleVerse(
            textHy: "Երկաթը երկաթով է սրվում, եւ մարդս սրում է իր ընկերի երեսը։",
            textHyArarat: "Երկաթը երկաթով է սրվում, և մարդն էլ սրում է իր ընկերոջ միտքը ։",
            textRu: "Железо железо острит, и человек изощряет взгляд друга своего.",
            textEn: "Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.",
            refHy: "Առակաց 27:17",
