        BibleVerse(
            textHy: "Փառք եւ պատիւ է նորա հանդերձը, եւ ուրախ է ապագայ օրուայ համար։ Նա իր բերանը բանում է իմաստութիւնով, եւ նորա լեզուի վերայ շնորհալի օրէնք կայ։",
            textHyArarat: "Զորությունն ու պատիվն են նրա զգեստը, և ուրախ է հետագա օրերի համար։ Նա իր բերանն իմաստությամբ է բացում, և նրա լեզվի վրա բարության ուսուցում կա։",
            textRu: "Крепость и красота — одежда ее, и весело смотрит она на будущее. Уста свои открывает с мудростью, и кроткое наставление на языке ее.",
            textEn: "Strength and honour are her clothing; and she shall rejoice in time to come. She openeth her mouth with wisdom; and in her tongue is the law of kindness.",
