        BibleVerse(
            textHy: "Նա ամեն բան արել է վայելուչ իր ժամանակին, նաեւ յաւիտենականութիւնը դրել է նորանց սրտումը. Բայց այնպէս որ մարդս չէ կարող ըմբռնել Աստուծոյ արած գործքը գլխիցը մինչեւ ծայրը։",
            textHyArarat: "Նա ամեն բան պատշաճ է արել իր ժամանակին, նաև հավիտենականությունն է դրել մարդկանց սրտում, սակայն մարդը չի կարող սկզբից մինչև վերջը հասկանալ Աստծու արած գործերը։",
            textRu: "Всё соделал Он прекрасным в свое время, и вложил мир в сердце их, хотя человек не может постигнуть дел, которые Бог делает, от начала до конца.",
            textEn: "He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.",
            refHy: "Ժողովող 3:11",
            refRu: "Екклесиаст 3:11",
            refEn: "Ecclesiastes 3:11"
