        BibleVerse(
            textHy: "Երկուսը լաւ է քան թէ մէկը. Որ նորանք վարձք ունին իրանց աշխատանքիցը։ Որովհետեւ եթէ վայր ընկնեն, մէկը միւսին վեր կկացնէ. Բայց վա՜յ մէկին որ ընկնի, եւ մի երկրորդ չկայ որ նորան կանգնեցնէ։",
            textHyArarat: "Երկուսը մեկից լավ է, որովհետև նրանք լավ վարձ ունեն իրենց տանջանքից։ Որովհետև եթե վայր ընկնեն, մեկն իր ընկերոջը կկանգնեցնի. բայց վա՜յ մեկին, որ ընկնում է, և չկա մի երկրորդը, որ կանգնեցնի նրան։",
            textRu: "Двоим лучше, нежели одному; потому что у них есть доброе вознаграждение в труде их: ибо если упадет один, то другой поднимет товарища своего. Но горе одному, когда упадет, а другого нет, который поднял бы его.",
            textEn: "Two are better than one; because they have a good reward for their labour. For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up.",
            refHy: "Ժողովող 4:9-10",
            refRu: "Екклесиаст 4:9-10",
            refEn: "Ecclesiastes 4:9-10"
        ),
        BibleVerse(
            textHy: "Եւ եթէ մէկը նորան բռնութիւն անէ, երկուսը նորա դէմ կկանգնեն. Եւ երեքպատիկ թելը շուտով չի կտրուիլ։",
            textHyArarat: "Եվ եթե մեկը նրան բռնանա, երկուսը նրա դեմ կկանգնեն. եռապատիկ թելը շուտ չի կտրվի։",
            textRu: "И если станет преодолевать кто-либо одного, то двое устоят против него: и нитка, втрое скрученная, не скоро порвется.",
            textEn: "And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken.",
            refHy: "Ժողովող 4:12",
            refRu: "Екклесиаст 4:12",
            refEn: "Ecclesiastes 4:12"
        ),
        BibleVerse(
            textHy: "Մեզ համար մի մանուկ ծնուեցաւ, մեզ մի որդի տրուեցաւ, եւ իշխանութիւնը կլինի նորա ուսի վերայ, եւ նորա անունը կկոչուի Սքանչելի, Խորհրդական, Հզօր Աստուած, Յաւիտենականութեան Հայր, Խաղաղութեան իշխան։",
            textHyArarat: "Մեզ մի մանուկ ծնվեց, մեզ մի որդի տրվեց, և իշխանությունն իր ուսերի վրա կլինի, և կկոչվի Սքանչելի Խորհրդական, Հզոր Աստված, Հավիտենականության Հայր և Խաղաղության Իշխան։",
            textRu: "Младенец родился нам — Сын дан нам; владычество на раменах Его, и нарекут имя Ему: Чудный, Советник, Бог крепкий, Отец вечности, Князь мира.",
            textEn: "Unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.",
            refHy: "Եսայի 9:6",
