        BibleVerse(
            textHy: "Եւ դորա համար Տէրը սպասելու է, որ ձեզ ողորմէ, եւ դորա համար բարձրանալու է որ ձեզ գթայ. որովհետեւ Տէրը իրաւունքի Աստուած է. երանի՜ այն ամենին որ սպասում են նորան։",
            textHyArarat: "Դրա համար Տերը սպասում է, որ ձեզ իր հաճությունը ցույց տա, և վեր է կենալու, որ ձեզ գթա. որովհետև Տերն իրավունքի Աստված է. երանելի են բոլոր նրանք, ովքեր սպասում են նրան։",
            textRu: "И потому Господь медлит, чтобы помиловать вас, и потому еще удерживается, чтобы сжалиться над вами; ибо Господь есть Бог правды: блаженны все уповающие на Него!",
            textEn: "And therefore will the LORD wait, that he may be gracious unto you, and therefore will he be exalted, that he may have mercy upon you: for the LORD is a God of judgment: blessed are all they that wait for him.",
            refHy: "Եսայի 30:18",
            refRu: "Исаия 30:18",
            refEn: "Isaiah 30:18"
        ),
        BibleVerse(
            textHy: "Խոտը կչորանայ, ծաղիկը կթառամէ, բայց մեր Աստուծոյ խօսքը կմնայ յաւիտեան։",
            textHyArarat: "Խոտը չորանում է, ծաղիկը՝ թառամում, բայց մեր Աստծու խոսքը մնում է հավիտյան»։",
            textRu: "Трава засыхает, цвет увядает, а слово Бога нашего пребудет вечно.",
            textEn: "The grass withereth, the flower fadeth: but the word of our God shall stand for ever.",
            refHy: "Եսայի 40:8",
            refRu: "Исаия 40:8",
