        ),
        BibleVerse(
            textHy: "Ես Եհովաս՝ քո Աստուածը՝ զօրացնում եմ քո աջը. որ ասում եմ քեզ. Մի վախենար, ես կօգնեմ քեզ։",
            textHyArarat: "որովհետև ես՝ Տերը՝ քո Աստվածը, բռնում եմ քո աջ ձեռքը. ե՛ս եմ ասում քեզ. «Մի՛ վախեցիր, ես կօգնեմ քեզ»։",
            textRu: "Я Господь, Бог твой; держу тебя за правую руку твою, говорю тебе: «не бойся, Я помогаю тебе».",
            textEn: "I the LORD thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.",
            refHy: "Եսայի 41:13",
            refRu: "Исаия 41:13",
            refEn: "Isaiah 41:13"
