        BibleVerse(
            textHy: "Առաջինները մի յիշէք. եւ հին բաները մի մտաբերէք։ Ահա ես նորա բան եմ անում. Հիմա կյայտնուի. մի՞թէ չէք իմանալ։ Նաեւ մի ճանապարհ եմ շինելու անապատումը, ամայի տեղերումն էլ՝ գետեր։",
            textHyArarat: "«Նախկին բաները մի՛ հիշեք և հին բաները մի՛ մտածեք։ Ահա ես նոր բան եմ անում, որ հիմա կհայտնվի։ Մի՞թե դուք չեք իմանա այդ։ Ես ճանապարհ կբացեմ ամայի տեղերում և գետեր՝ անապատում։",
            textRu: "Вы не вспоминаете прежнего и о древнем не помышляете. Вот, Я делаю новое; ныне же оно явится; неужели вы и этого не хотите знать? Я проложу дорогу в степи, реки в пустыне.",
            textEn: "Remember ye not the former things, neither consider the things of old. Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.",
            refHy: "Եսայի 43:18-19",
            refRu: "Исаия 43:18-19",
            refEn: "Isaiah 43:18-19"
        ),
        BibleVerse(
            textHy: "Մի՞թէ կինը կմոռանայ իր կաթնակեր մանուկին, որ չգթայ իր որովայնի ծննդեան վերայ. նորանք եթէ մոռանան էլ, բայց ես քեզ չեմ մոռանալ։ Ահա ես իմ ձեռքի մէջ եմ նկարագրել քեզ, քո պարիսպները իմ դիմացն են միշտ։",
            textHyArarat: "Մի՞թե կինը կմոռանա իր կաթնակեր մանկանը և չի՞ գթա իր որովայնի ծնունդին. եթե նա մոռանա իսկ, ես, սակայն, քեզ չեմ մոռանա։ Ահա ես իմ ձեռքերի ափերի մեջ փորագրել եմ քեզ, քո պարիսպներն իմ դիմացն են միշտ։",
            textRu: "Забудет ли женщина грудное дитя свое, чтобы не пожалеть сына чрева своего? но если бы и она забыла, то Я не забуду тебя. Вот, Я начертал тебя на дланях Моих; стены твои всегда предо Мною.",
            textEn: "Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee. Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.",
            refHy: "Եսայի 49:15-16",
            refRu: "Исаия 49:15-16",
            refEn: "Isaiah 49:15-16"
        ),
        BibleVerse(
            textHy: "Յիրաւի՜ նա մեր ցաւերը վեր առաւ, եւ մեր վիշտերը բեռնեց իր վերայ, բայց մենք նորան պատուհարուած էինք համարում, Աստուածանից զարկուած եւ նկուն եղած։ Բայց նա մեր մեղքերի համար վիրաւորուեցաւ, եւ մեր անօրէնութիւնների համար հարուածուեցաւ, մեր խաղաղութեան պատիժը նորա վերայ եղաւ, եւ նորա վէրքերովը մենք բժշկուեցանք։",
            textHyArarat: "Հիրավի, նա մեր ցավերը վերցրեց, մեր վշտերը կրեց։ Մենք նրան համարում էինք պատուհասված, Աստծուց հարվածված և տանջված։ Բայց նա մեր հանցանքների համար վիրավորվեց և մեր անօրենությունների համար հարվածվեց. պատիժը, որ մեզ բարօրություն բերեց, նրա վրա ընկավ, և նրա վերքերով մենք բժշկվեցինք։",
            textRu: "Он взял на Себя наши немощи и понес наши болезни; а мы думали, что Он был поражаем, наказуем и уничижен Богом. Но Он изъязвлен был за грехи наши и мучим за беззакония наши; наказание мира нашего было на Нем, и ранами Его мы исцелились.",
            textEn: "Surely he hath borne our griefs, and carried our sorrows: yet we did esteem him stricken, smitten of God, and afflicted. But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.",
            refHy: "Եսայի 53:4-5",
            refRu: "Исаия 53:4-5",
            refEn: "Isaiah 53:4-5"
        ),
        BibleVerse(
            textHy: "Սարերը կքաշուին, եւ բլուրները կսասանեն, բայց իմ ողորմութիւնը քեզանից չի քաշուիլ, եւ իմ խաղաղութեան ուխտը չի սասանիլ, ասում է քեզ ողորմող Տէրը։",
            textHyArarat: "Թեև լեռները գնան, բլուրները վերցվեն, իմ գթությունը քեզանից չի հեռանա, իմ խաղաղության ուխտը չի խախտվի»,- ասում է քեզ գթացող Տերը։",
            textRu: "Горы сдвинутся, и холмы поколеблются, — а милость Моя не отступит от тебя, и завет мира Моего не поколеблется, говорит милующий тебя Господь.",
            textEn: "The mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the LORD that hath mercy on thee.",
            refHy: "Եսայի 54:10",
            refRu: "Исаия 54:10",
            refEn: "Isaiah 54:10"
        ),
        BibleVerse(
            textHy: "Ով բոլոր ծարաւներ, եկէք ջրերին մօտ. եւ դուք որ փող չունիք, եկէք, ծախու առէք եւ կերէք, եկէք առէք առանց փողի, առանց վճարի՝ գինի եւ կաթ։",
            textHyArarat: "Ո՛վ բոլորդ, ծարավածնե՛ր, եկե՛ք ջրերի մոտ, և դուք, որ փող չունեք, եկե՛ք, գնե՛ք ու կերե՛ք. եկե՛ք, գնե՛ք գինի և կաթ առանց փողի, առանց գնի։",
            textRu: "Жаждущие! идите все к водам; даже и вы, у которых нет серебра, идите, покупайте и ешьте; идите, покупайте без серебра и без платы вино и молоко.",
            textEn: "Ho, every one that thirsteth, come ye to the waters, and he that hath no money; come ye, buy, and eat; yea, come, buy wine and milk without money and without price.",
            refHy: "Եսայի 55:1",
            refRu: "Исаия 55:1",
            refEn: "Isaiah 55:1"
        ),
        BibleVerse(
            textHy: "Ինչպէս որ իջնում է անձրեւը եւ ձիւնը երկնքից եւ ետ չէ դառնում այնտեղ, այլ ոռոգում է երկիրը եւ նորան արգասաւոր անում եւ բողբոջեցնում նորան, եւ տալիս է սերմ սերմնացանին եւ հաց՝ ուտողին, Այնպէս էլ պիտի լինի իմ բերանից դուրս եկած խօսքը, նա պիտի պարապ ետ չդառնայ ինձ մօտ, այլ կատարէ իմ ուզածը, եւ յաջողուի նորանում, ինչի համար որ ես նորան ուղարկեցի։",
            textHyArarat: "Քանզի ինչպես որ անձրևն ու ձյունը իջնում են երկնքից և հետ չեն դառնում այնտեղ, այլ ոռոգում են երկիրը, արգասաբեր և ծլարձակ դարձնում այն, սերմ են տալիս սերմնացանին և հաց՝ ուտողին, այնպես էլ կլինի իմ բերանից դուրս եկած խոսքը. նա ապարդյուն չի վերադառնա ինձ մոտ, այլ կկատարի իմ փափագը և հաջողություն կունենա այն բանում, ինչի համար ես ուղարկել եմ նրան»։",
            textRu: "Как дождь и снег нисходит с неба и туда не возвращается, но напояет землю и делает ее способною рождать и произращать, чтобы она давала семя тому, кто сеет, и хлеб тому, кто ест, — так и слово Мое, которое исходит из уст Моих, — оно не возвращается ко Мне тщетным, но исполняет то, что Мне угодно, и совершает то, для чего Я послал его.",
            textEn: "As the rain cometh down, and the snow from heaven, and returneth not thither, but watereth the earth, and maketh it bring forth and bud, that it may give seed to the sower, and bread to the eater: So shall my word be that goeth forth out of my mouth: it shall not return unto me void, but it shall accomplish that which I please, and it shall prosper in the thing whereto I sent it.",
            refHy: "Եսայի 55:10-11",
            refRu: "Исаия 55:10-11",
            refEn: "Isaiah 55:10-11"
