        BibleVerse(
            textHy: "Վեր կաց, լուսաւորուիր, որովհետեւ լոյսդ եկել է, եւ Տիրոջ փառքը ծագել է քեզ վերայ։",
            textHyArarat: "Վե՛ր կաց, լուսավորվի՛ր, որովհետև եկել է քո լույսը, և Տիրոջ փառքը ծագեց քեզ վրա։",
            textRu: "Восстань, светись, ибо пришел свет твой, и слава Господня взошла над тобою.",
            textEn: "Arise, shine; for thy light is come, and the glory of the LORD is risen upon thee.",
            refHy: "Եսայի 60:1",
            refRu: "Исаия 60:1",
