        BibleVerse(
            textHy: "Ինչպէս որ մէկ մարդ՝ որին իր մայրը կմխիթարէ, նոյնպէս էլ ես պիտի մխիթարեմ ձեզ, եւ Երուսաղէմով պիտի մխիթարուիք։",
            textHyArarat: "Ինչպես մարդ, որին հանգստացնում է իր մայրը, այնպես էլ ես պիտի հանգստացնեմ ձեզ. ձեզ կհանգստացնեմ Երուսաղեմում։",
            textRu: "Как утешает кого-либо мать его, так утешу Я вас, и вы будете утешены в Иерусалиме.",
            textEn: "As one whom his mother comforteth, so will I comfort you; and ye shall be comforted in Jerusalem.",
            refHy: "Եսայի 66:13",
            refRu: "Исаия 66:13",
            refEn: "Isaiah 66:13"
