        BibleVerse(
            textHy: "Օրհնեալ լինի այն մարդը, որ Տիրոջն է ապաւինում, եւ Տէրն է նորա յոյսը։ Նա նման կ'լինի մի ծառի, որ տնկուած է ջրերի մօտ. նա իր արմատները կ'ձգէ գետի մօտովը, եւ չի տեսնիլ տաքութիւնը՝ եկած ժամանակը. այլ նորա տերեւները կանաչ կ'լինի, եւ երաշտ տարին նա չի վախենալ եւ չի դադարիլ պտուղ տալուց։",
            textHyArarat: "Օրհնյա՜լ լինի այն մարդը, որ Տիրոջն է վստահում, և Տերն է նրա վստահությունը։ Նա ջրերի մոտ տնկված մի ծառի նման կլինի. նա իր արմատները կձգի գետի մոտով և չի տեսնի տաքության գալու ժամանակը. նրա տերևները կանաչ կլինեն, երաշտի տարում նա չի մտահոգվի և չի դադարի պտուղ տալուց։",
            textRu: "Благословен человек, который надеется на Господа, и которого упование — Господь. Ибо он будет как дерево, посаженное при водах и пускающее корни свои у потока; не знает оно, когда приходит зной; лист его зелен, и во время засухи оно не боится и не перестает приносить плод.",
            textEn: "Blessed is the man that trusteth in the LORD, and whose hope the LORD is. For he shall be as a tree planted by the waters, and that spreadeth out her roots by the river, and shall not see when heat cometh, but her leaf shall be green; and shall not be careful in the year of drought, neither shall cease from yielding fruit.",
            refHy: "Երեմիա 17:7-8",
            refRu: "Иеремия 17:7-8",
            refEn: "Jeremiah 17:7-8"
        ),
        BibleVerse(
            textHy: "Հեռուանց է երեւացել ինձ Տէրը, թէ Յաւիտենական սիրով սիրել եմ քեզ. դորա համար քաշեցի քեզ ողորմութիւնով։",
            textHyArarat: "Տերը վաղուց երևաց ինձ և ասաց. «Հավիտենական սիրով եմ սիրել քեզ, դրա համար ողորմությամբ քեզ դեպի ինձ քաշեցի։",
            textRu: "Издали явился мне Господь и сказал: любовью вечною Я возлюбил тебя и потому простер к тебе благоволение.",
            textEn: "The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.",
            refHy: "Երեմիա 31:3",
            refRu: "Иеремия 31:3",
            refEn: "Jeremiah 31:3"
        ),
        BibleVerse(
            textHy: "Տիրոջ ողորմութիւններն են, որ չ'վերջացանք, որովհետեւ չ'պակասեցան նորա գթութիւնները. Նորանք ամեն առաւօտ նորանոր են. մեծ է քո հաւատարմութիւնը։ Իմ բաժինը Տէրն է, ասեց իմ հոգին, սորա համար նորան եմ յուսալու։",
            textHyArarat: "Տիրոջ ողորմությունը չի դադարում, նրա գթությունը վերջ չունի։ Նրանք ամեն առավոտ նորանում են. մեծ է քո հավատարմությունը։ «Տերն է իմ բաժինը,- ասաց իմ հոգին,- ուստի ես նրան եմ հուսալու»։",
            textRu: "По милости Господа мы не исчезли, ибо милосердие Его не истощилось. Оно обновляется каждое утро; велика верность Твоя! Господь часть моя, говорит душа моя, итак буду надеяться на Него.",
            textEn: "It is of the LORD'S mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness. The LORD is my portion, saith my soul; therefore will I hope in him.",
            refHy: "Ողբ 3:22-24",
            refRu: "Плач Иеремии 3:22-24",
            refEn: "Lamentations 3:22-24"
