        BibleVerse(
            textHy: "Բարի է Տէրը իրան յուսացողներին՝ այն անձին որ նորան որոնում է։ Լաւ է յուսալ եւ սպասել լռութիւնով Տիրոջ փրկութեանը։",
            textHyArarat: "Տերը բարի է իրեն հուսացողներին, այն անձին, որը նրան է փնտրում։ Լավ է լռությամբ սպասել, սպասել Տիրոջ փրկությանը։",
            textRu: "Благ Господь к надеющимся на Него, к душе, ищущей Его. Благо тому, кто терпеливо ожидает спасения от Господа.",
            textEn: "The LORD is good unto them that wait for him, to the soul that seeketh him. It is good that a man should both hope and quietly wait for the salvation of the LORD.",
            refHy: "Ողբ 3:25-26",
            refRu: "Плач Иеремии 3:25-26",
            refEn: "Lamentations 3:25-26"
        ),
        BibleVerse(
            textHy: "Ես Տիրոջը կ'սպասեմ, եւ կ'յուսամ իմ փրկութեան Աստուծուն. ինձ պիտի լսէ իմ Աստուածը։ Մի ուրախանար ինձ վերայ, ով իմ թշնամի, որովհետեւ թէեւ ընկնեմ, վեր կ'կենամ, թէեւ խաւարի մէջ նստեմ, Տէրը ինձ լոյս կ'լինի։",
            textHyArarat: "Ես, ես Տիրոջն եմ նայում, կսպասեմ իմ փրկության Աստծուն. ինձ պիտի լսի իմ Աստվածը։ Մի՛ ուրախացիր իմ դեմ, ո՛վ իմ թշնամի. թեև ընկնեմ, վեր կկենամ, թեկուզ խավարի մեջ նստեմ, Տերն ինձ լույս կլինի։",
            textRu: "Я буду взирать на Господа, уповать на Бога спасения моего: Бог мой услышит меня. Не радуйся ради меня, неприятельница моя! хотя я упал, но встану; хотя я во мраке, но Господь — свет для меня.",
            textEn: "I will look unto the LORD; I will wait for the God of my salvation: my God will hear me. Rejoice not against me, O mine enemy: when I fall, I shall arise; when I sit in darkness, the LORD shall be a light unto me.",
            refHy: "Միքիա 7:7-8",
            refRu: "Михей 7:7-8",
            refEn: "Micah 7:7-8"
        ),
        BibleVerse(
            textHy: "Ես ասում եմ ձեզ, Սիրեցէք ձեր թշնամիներին, օրհնեցէք ձեզ անիծողներին. բարի արէք ձեզ ատողներին. եւ աղօթք արէք ձեզ չարչարողների եւ ձեզ հալածողների համար. Որ որդիք լինիք ձեր Հօրն, որ երկնքումն է. որովհետեւ նա իր արեգակը ծագեցնում է չարերի եւ բարիների վերայ, եւ անձրեւ է բերում արդարների եւ անիրաւների վերայ։",
            textHyArarat: "Ես ասում եմ ձեզ. սիրե՛ք ձեր թշնամիներին, օրհնե՛ք ձեզ անիծողներին, բարի՛ք արեք ձեզ ատողներին և աղոթե՛ք ձեզ չարչարողների ու հալածողների համար, որպեսզի որդիները լինեք ձեր Հոր, որ երկնքում է. որովհետև նա իր արեգակը ծագեցնում է և՛ չարերի, և՛ բարիների վրա ու անձրև է բերում և՛ արդարների, և՛ անարդարների վրա։",
            textRu: "Я говорю вам: любите врагов ваших, благословляйте проклинающих вас, благотворите ненавидящим вас и молитесь за обижающих вас и гонящих вас, да будете сынами Отца вашего Небесного, ибо Он повелевает солнцу Своему восходить над злыми и добрыми и посылает дождь на праведных и неправедных.",
            textEn: "I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you; That ye may be the children of your Father which is in heaven: for he maketh his sun to rise on the evil and on the good, and sendeth rain on the just and on the unjust.",
            refHy: "Մատթեոս 5:44-45",
            refRu: "Матфея 5:44-45",
            refEn: "Matthew 5:44-45"
        ),
        BibleVerse(
            textHy: "Դու երբոր աղօթք անես, մտիր քո սենեակը եւ դուռդ փակած աղօթք արա դէպի քո Հայրը, որ ծածուկումն է. եւ քո Հայրն՝ որ ծածուկ տեղը տեսնում է, յայտնապէս կհատուցանէ քեզ։",
            textHyArarat: "Այլ երբ դու աղոթես, մտի՛ր քո սենյակը, փակի՛ր դուռդ և ծածուկ աղոթի՛ր քո Հորը, և քո Հայրը, որ տեսնում է ծածուկը, հայտնապես կհատուցի քեզ։",
            textRu: "Ты же, когда молишься, войди в комнату твою и, затворив дверь твою, помолись Отцу твоему, Который втайне; и Отец твой, видящий тайное, воздаст тебе явно.",
            textEn: "Thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly.",
            refHy: "Մատթեոս 6:6",
            refRu: "Матфея 6:6",
            refEn: "Matthew 6:6"
        ),
        BibleVerse(
            textHy: "Դուք այսպէս աղօթք արէք. Մեր Հայր, որ երկնքումն ես. սուրբ լինի քո անունը. Գայ քո արքայութիւնը, լինի քո կամքը, ինչպէս երկնքումն՝ այնպէս էլ երկրի վերայ։ Մեր ամեն օրուայ հացը տուր մեզ այսօր։ Եւ թող մեզ մեր պարտքերը, ինչպէս մենք էլ թողում ենք մեր պարտականներին։ Եւ մի տանիր մեզ փորձութեան մէջ. այլ ազատիր մեզ չարիցը. որովհետեւ քոնն է թագաւորութիւնը եւ զօրութիւնը եւ փառքը յաւիտեանս. ամէն։",
            textHyArarat: "Արդ, դուք այսպե՛ս աղոթեք. \"Հա՛յր մեր, որ երկնքում ես, սուրբ լինի քո անունը. քո արքայությունը գա, քո կամքը լինի ինչպես երկնքում, այնպես էլ երկրի վրա։ Տո՛ւր մեզ այսօր մեր հանապազօրյա հացը։ Եվ ների՛ր մեզ մեր պարտքերը, ինչպես մենք ենք ներում մեր պարտապաններին։ Եվ մի՛ տար մեզ փորձության, այլ ազատի՛ր մեզ չարից\"։",
            textRu: "Молитесь же так: Отче наш, сущий на небесах! да святится имя Твое; да приидет Царствие Твое; да будет воля Твоя и на земле, как на небе; хлеб наш насущный дай нам на сей день; и прости нам долги наши, как и мы прощаем должникам нашим; и не введи нас в искушение, но избавь нас от лукавого. Ибо Твое есть Царство и сила и слава во веки. Аминь.",
            textEn: "After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name. Thy kingdom come. Thy will be done in earth, as it is in heaven. Give us this day our daily bread. And forgive us our debts, as we forgive our debtors. And lead us not into temptation, but deliver us from evil: For thine is the kingdom, and the power, and the glory, for ever. Amen.",
            refHy: "Մատթեոս 6:9-13",
            refRu: "Матфея 6:9-13",
            refEn: "Matthew 6:9-13"
        ),
        BibleVerse(
            textHy: "Ձեզ համար գանձեր մի դիզէք երկրիս վերայ. ուր որ ցեցն եւ ժանգն ապականում են, եւ ուր որ գողերը պատը ծակում են եւ գողանում։ Բայց ձեզ համար գանձեր դիզեցէք երկնքումը, ուր ո՛չ ցեց եւ ո՛չ ժանգ չեն ապականում, եւ ուր գողերը պատը չեն ծակում եւ չեն գողանում։ Որովհետեւ ինչ տեղ որ ձեր գանձն է, այնտեղ կլինի եւ ձեր սիրտը։",
            textHyArarat: "Ձեզ համար գանձեր մի՛ դիզեք երկրի վրա, որտեղ ցեցն ու ժանգն ապականում են, և որտեղ գողերը սողոսկում են ու գողանում։ Այլ ձեզ համար երկնքո՛ւմ գանձեր դիզեք, որտեղ ո՛չ ցեցը, ո՛չ ժանգը չեն ապականում, ո՛չ էլ գողերն են սողոսկում ու գողանում. որովհետև որտեղ ձեր գանձն է, այնտեղ էլ ձեր սիրտը կլինի։",
            textRu: "Не собирайте себе сокровищ на земле, где моль и ржа истребляют и где воры подкапывают и крадут, но собирайте себе сокровища на небе, где ни моль, ни ржа не истребляют и где воры не подкапывают и не крадут, ибо где сокровище ваше, там будет и сердце ваше.",
            textEn: "Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal: But lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt, and where thieves do not break through nor steal: For where your treasure is, there will your heart be also.",
            refHy: "Մատթեոս 6:19-21",
            refRu: "Матфея 6:19-21",
            refEn: "Matthew 6:19-21"
        ),
        BibleVerse(
            textHy: "Ոչ ով չէ կարող երկու տէրերի ծառայել. որովհետեւ կամ մէկին կատէ եւ միւսին կսիրէ, կամ մէկին կմեծարէ եւ միւսին կարհամարհէ։ Չէք կարող Աստուծուն ծառայել եւ մամոնային։",
            textHyArarat: "Ոչ ոք չի կարող երկու տիրոջ ծառայել, որովհետև կա՛մ մեկին կատի և մյուսին կսիրի, կա՛մ մեկին կմեծարի և մյուսին կարհամարհի։ Չեք կարող ծառայել և՛ Աստծուն, և՛ մամոնային ։",
            textRu: "Никто не может служить двум господам: ибо или одного будет ненавидеть, а другого любить; или одному станет усердствовать, а о другом нерадеть. Не можете служить Богу и маммоне.",
            textEn: "No man can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon.",
            refHy: "Մատթեոս 6:24",
            refRu: "Матфея 6:24",
            refEn: "Matthew 6:24"
        ),
        BibleVerse(
            textHy: "Ամեն ինչ որ կամենում էք՝ թէ ձեզ անեն մարդիկ, այնպէս էլ դուք արէք նորանց. որովհետեւ այս է օրէնքը եւ մարգարէները։",
            textHyArarat: "Այն ամենը, ինչ կամենում եք, որ մարդիկ ձեզ անեն, այդպես և դո՛ւք արեք նրանց, որովհետև սա են օրենքը և մարգարեները։",
            textRu: "Во всем, как хотите, чтобы с вами поступали люди, так поступайте и вы с ними, ибо в этом закон и пророки.",
            textEn: "All things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets.",
            refHy: "Մատթեոս 7:12",
            refRu: "Матфея 7:12",
            refEn: "Matthew 7:12"
        ),
        BibleVerse(
            textHy: "Արդ՝ ամեն ով որ իմ այս խօսքերը լսում է եւ նորանց կատարում, կնմանացնեմ նորան մի իմաստուն մարդի որ իր տունը շինեց ժայռի վերայ։ Եւ անձրեւն էլ եկաւ, գետերն էլ վարարեցին, քամիներն էլ փչեցին եւ այն տանը զարկեցին, եւ նա չկործանուեցաւ. որովհետեւ ժայռի վերայ հաստատուած էր։",
            textHyArarat: "Արդ, ամեն ոք, ով լսում է իմ այս խոսքերն ու դրանք կատարում, կնմանեցնեմ մի իմաստուն մարդու, որն իր տունը կառուցեց ժայռի վրա։ Անձրևը եկավ, գետերը հորդեցին, քամիները փչեցին և զարկեցին տանը, բայց այն չկործանվեց, որովհետև ժայռի վրա էր հաստատված։",
            textRu: "Всякого, кто слушает слова Мои сии и исполняет их, уподоблю мужу благоразумному, который построил дом свой на камне; и пошел дождь, и разлились реки, и подули ветры, и устремились на дом тот, и он не упал, потому что основан был на камне.",
            textEn: "Whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock: And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell not: for it was founded upon a rock.",
            refHy: "Մատթեոս 7:24-25",
            refRu: "Матфея 7:24-25",
            refEn: "Matthew 7:24-25"
        ),
        BibleVerse(
            textHy: "Այն ժամանակ Յիսուսը իր աշակերտներին ասեց. Եթէ մէկը կամենում է իմ ետեւից գալ, թող իր անձն ուրանայ եւ իր խաչն առնէ, եւ իմ ետեւից գայ։ Որովհետեւ ով որ իր անձը ուզէ ապրեցնել, կկորցնէ նորան, եւ ով որ իր անձը կորցնէ ինձ համար՝ կգտնէ նորան։ Որովհետեւ ի՞նչ օգուտ ունի մարդ, որ բոլոր աշխարհքն ստանայ եւ իր անձը կորցնէ. կամ ի՞նչ գին կտայ մարդ իր անձը փրկելու համար։",
            textHyArarat: "Այդ ժամանակ Հիսուսն իր աշակերտներին ասաց. «Եթե մեկը կամենում է իմ հետևից գալ, թող ուրանա ինքն իրեն, վերցնի իր խաչը և գա իմ հետևից։ Որովհետև ով ուզենա փրկել իր կյանքը, կկորցնի այն, իսկ ով իր կյանքը կորցնի ինձ համար, կգտնի այն։ Մարդուն ի՞նչ օգուտ, եթե ամբողջ աշխարհը շահի, բայց իր կյանքը կորցնի, կամ մարդն ի՞նչ փրկագին կտա։",
            textRu: "Тогда Иисус сказал ученикам Своим: если кто хочет идти за Мною, отвергнись себя, и возьми крест свой, и следуй за Мною, ибо кто хочет душу свою сберечь, тот потеряет ее, а кто потеряет душу свою ради Меня, тот обретет ее; какая польза человеку, если он приобретет весь мир, а душе своей повредит? или какой выкуп даст человек за душу свою?",
            textEn: "Then said Jesus unto his disciples, If any man will come after me, let him deny himself, and take up his cross, and follow me. For whosoever will save his life shall lose it: and whosoever will lose his life for my sake shall find it. For what is a man profited, if he shall gain the whole world, and lose his own soul? or what shall a man give in exchange for his soul?",
            refHy: "Մատթեոս 16:24-26",
            refRu: "Матфея 16:24-26",
            refEn: "Matthew 16:24-26"
        ),
        BibleVerse(
            textHy: "Նորա տէրն էլ ասեց նորան. Լա՜ւ, բարի եւ հաւատարիմ ծառայ, քիչ բաների վերայ հաւատարիմ էիր, ես քեզ շատ բաների վերայ կդնեմ. մտիր քո տիրոջ ուրախութիւնը։",
            textHyArarat: "Եվ նրա տերը նրան ասաց. \"Լա՛վ, բարի ու հավատարի՛մ ծառա, քանի որ դու քչի մեջ հավատարիմ եղար, ես քեզ շատի վրա կկարգեմ. մտի՛ր քո տիրոջ ուրախության մեջ\"։",
            textRu: "Господин его сказал ему: хорошо, добрый и верный раб! в малом ты был верен, над многим тебя поставлю; войди в радость господина твоего.",
            textEn: "His lord said unto him, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord.",
            refHy: "Մատթեոս 25:21",
            refRu: "Матфея 25:21",
            refEn: "Matthew 25:21"
        ),
        BibleVerse(
            textHy: "Յիսուսն էլ նորանց մտիկ տուաւ եւ ասեց. Մարդկանց կողմանէ անկարելի է, այլ ոչ թէ Աստուծոյ կողմանէ. Որովհետեւ ամեն բան կարելի է Աստուծոյ կողմանէ։",
            textHyArarat: "Հիսուսը նրանց նայեց ու ասաց. «Մարդկանց համար դա անհնար է, բայց ո՛չ Աստծու համար։ Աստծու համար ամեն ինչ է հնարավոր»։",
            textRu: "Иисус, воззрев на них, говорит: человекам это невозможно, но не Богу, ибо всё возможно Богу.",
            textEn: "And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible.",
            refHy: "Մարկոս 10:27",
            refRu: "Марка 10:27",
            refEn: "Mark 10:27"
        ),
        BibleVerse(
            textHy: "Սորա համար ասում եմ ձեզ թէ Ամեն ինչ որ աղօթք անելով խնդրէք, հաւատացէք թէ կառնէք, եւ կլինի ձեզ։",
            textHyArarat: "Դրա համար ասում եմ ձեզ. այն ամենը, ինչ աղոթքով խնդրեք, հավատացե՛ք, որ կստանաք, ու դա կտրվի ձեզ։",
            textRu: "Потому говорю вам: всё, чего ни будете просить в молитве, верьте, что получите, — и будет вам.",
            textEn: "I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.",
            refHy: "Մարկոս 11:24",
            refRu: "Марка 11:24",
            refEn: "Mark 11:24"
        ),
        BibleVerse(
            textHy: "Ձեզ՝ որ լսում էք, ասում եմ. Սիրեցէք ձեր թշնամիներին, բարի արէք ձեզ ատողներին։ Օրհնեցէք ձեզ անիծողներին, աղօթք արէք ձեզ նեղացնողների վերայ։",
            textHyArarat: "Ասում եմ ձեզ, դուք, որ լսում եք. սիրե՛ք ձեր թշնամիներին, բարի՛ք արեք ձեզ ատողներին։ Օրհնե՛ք ձեզ անիծողներին, աղոթե՛ք ձեզ նեղողների համար։",
            textRu: "Вам, слушающим, говорю: любите врагов ваших, благотворите ненавидящим вас, благословляйте проклинающих вас и молитесь за обижающих вас.",
            textEn: "I say unto you which hear, Love your enemies, do good to them which hate you, Bless them that curse you, and pray for them which despitefully use you.",
            refHy: "Ղուկաս 6:27-28",
            refRu: "Луки 6:27-28",
            refEn: "Luke 6:27-28"
        ),
        BibleVerse(
            textHy: "Եւ ինչպէս կամենում էք՝ որ մարդիկ ձեզ անեն, նոյնպէս էլ դուք արէք նորանց։",
            textHyArarat: "Ինչպես ուզում եք, որ մարդիկ ձեզ անեն, նույնն էլ դո՛ւք արեք նրանց։",
            textRu: "И как хотите, чтобы с вами поступали люди, так и вы поступайте с ними.",
            textEn: "And as ye would that men should do to you, do ye also to them likewise.",
            refHy: "Ղուկաս 6:31",
            refRu: "Луки 6:31",
            refEn: "Luke 6:31"
        ),
        BibleVerse(
            textHy: "Ողորմած եղէք, ինչպէս ձեր Հայրն էլ ողորմած է։ Եւ մի դատէք, եւ չէք դատուիլ. մի դատապարտէք, եւ չէք դատապարտուիլ. արձակեցէք՝ եւ կ’արձակուիք։ Տուէք եւ կ’տրուի ձեզ. լաւ չափով՝ թափ տրուած շարժուած լիփ լիքը կ’տան ձեր գոգը. որովհետեւ այն չափովը որ չափէք, նորանով կ’չափուի ձեզ։",
            textHyArarat: "Ողորմա՛ծ եղեք, ինչպես որ ձեր Հայրն է ողորմած։ Եվ մի՛ դատեք ու չեք դատվի, մի՛ պատժեք ու չեք պատժվի, ներե՛ք և ներված կլինեք։ Տվե՛ք, և կտրվի ձեզ. ձեր գոգը կլցվի լա՛վ չափով՝ լեփ-լեցուն, առատ, որովհետև ինչ չափով որ չափեք, նույնով էլ ձեզ կչափվի»։",
            textRu: "Будьте милосерды, как и Отец ваш милосерд. Не судите, и не будете судимы; не осуждайте, и не будете осуждены; прощайте, и прощены будете; давайте, и дастся вам: мерою доброю, утрясенною, нагнетенною и переполненною отсыплют вам в лоно ваше; ибо, какою мерою мерите, такою же отмерится и вам.",
            textEn: "Be ye therefore merciful, as your Father also is merciful. Judge not, and ye shall not be judged: condemn not, and ye shall not be condemned: forgive, and ye shall be forgiven: Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again.",
            refHy: "Ղուկաս 6:36-38",
            refRu: "Луки 6:36-38",
            refEn: "Luke 6:36-38"
        ),
        BibleVerse(
            textHy: "Եւ ես ասում եմ ձեզ, Խնդրեցէք՝ եւ կտրուի ձեզ, որոնեցէք եւ կ’գտնէք, դուռը թակեցէք՝ եւ կ’բացուի ձեզ։ Որովհետեւ ամեն ով որ խնդրում է՝ առնում է, եւ ով որ որոնում է՝ գտնում է, եւ ով որ դուռը թակում է՝ բացվում է նորան։",
            textHyArarat: "Եվ ես ասում եմ ձեզ. խնդրե՛ք, և կտրվի ձեզ, փնտրե՛ք և կգտնեք, դուռը բախե՛ք, ու ձեր առաջ կբացվի։ Որովհետև ով խնդրում է, ստանում է, և ով փնտրում է, գտնում է, և ով դուռը բախում է, նրա առաջ բացվում է։",
            textRu: "И Я скажу вам: просите, и дано будет вам; ищите, и найдете; стучите, и отворят вам, ибо всякий просящий получает, и ищущий находит, и стучащему отворят.",
            textEn: "And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you. For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened.",
            refHy: "Ղուկաս 11:9-10",
