        BibleVerse(
            textHy: "Չէ՞ որ հինգ ճնճղուկ երկու դանկի են ծախվում. եւ նորանցից մէկն էլ Աստուծոյ առաջին մոռացուած չէ։ Բայց ձեր գլխի բոլոր մազերն էլ համարուած են. ուրեմն մի վախենաք. որովհետեւ դուք շատ ճնճղուկներից աւելի լաւ էք։",
            textHyArarat: "Չէ՞ որ հինգ ճնճղուկը, որ երկու ասսարիոնով են վաճառում, նույնիսկ դրանցից մեկը Աստծու առաջ մոռացված չէ։ Ձեր գլխի բոլոր մազերն էլ հաշվված են. ուրեմն մի՛ վախեցեք, քանի որ դուք ճնճղուկներից շատ ավելին արժեք։",
            textRu: "Не пять ли малых птиц продаются за два ассария? и ни одна из них не забыта у Бога. А у вас и волосы на голове все сочтены. Итак не бойтесь: вы дороже многих малых птиц.",
            textEn: "Are not five sparrows sold for two farthings, and not one of them is forgotten before God? But even the very hairs of your head are all numbered. Fear not therefore: ye are of more value than many sparrows.",
            refHy: "Ղուկաս 12:6-7",
            refRu: "Луки 12:6-7",
            refEn: "Luke 12:6-7"
