        BibleVerse(
            textHy: "Ասում եմ ձեզ, թէ այսպէս ուրախութիւն կ’լինի երկնքումը մէկ մեղաւորի համար, որ ապաշխարէ, քան թէ իննսուն եւ ինն արդարների համար, որոնց ապաշխարհութիւն պէտք չէ։",
            textHyArarat: "Ասում եմ ձեզ, որ այդպես էլ երկնքում ուրախություն կլինի մեկ մեղավորի համար, որ ապաշխարի, քան իննսունինը արդարների համար, որոնք ապաշխարության կարիք չունեն։",
            textRu: "Сказываю вам, что так на небесах более радости будет об одном грешнике кающемся, нежели о девяноста девяти праведниках, не имеющих нужды в покаянии.",
            textEn: "I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance.",
