        BibleVerse(
            textHy: "Նա էլ ասեց. Այն բաներն որ կարելի չեն մարդկանց մօտ, կարելի են Աստուծոյ մօտ։",
            textHyArarat: "Նա ասաց. «Ինչ որ անհնար է մարդկանց համար, Աստծու համար հնարավոր է»։",
            textRu: "Он сказал: невозможное человекам возможно Богу.",
