        BibleVerse(
            textHy: "Հետեւեալ օրը Յովհաննէսը տեսնում է Յիսուսին իրան մօտ գալիս, եւ ասում է. Ահա Աստուծոյ Գառը, որ վեր է առնում աշխարհքի մեղքը։",
            textHyArarat: "Հաջորդ օրը Հովհաննեսը տեսավ Հիսուսին, որ գալիս էր իր մոտ, ու ասաց. «Ահա Աստծու Գառը, որ իր վրա է վերցնում աշխարհի մեղքը։",
            textRu: "На другой день видит Иоанн идущего к нему Иисуса и говорит: вот Агнец Божий, Который берет на Себя грех мира.",
