        BibleVerse(
            textHy: "Ժամանակ կգայ, եւ հիմա է, որ ճշմարիտ երկրպագողները հոգով եւ ճշմարտութիւնով կերկրպագեն Հօրը, որովհետեւ Հայրն էլ այսպէս է ուզում իր երկրպագողներին։ Աստուած Հոգի է, եւ նորան երկրպագողները պէտք է հոգով եւ ճշմարտութիւնով երկրպագեն։",
            textHyArarat: "Ժամանակը կգա, և արդեն եկել է, երբ ճշմարիտ երկրպագողները կերկրպագեն Հորը հոգով ու ճշմարտությամբ, որովհետև Հայրն իրեն այդպիսի երկրպագողներ է ուզում։ Աստված Հոգի է, ու նրան երկրպագողները պետք է հոգով ու ճշմարտությամբ երկրպագեն»։",
            textRu: "Настанет время и настало уже, когда истинные поклонники будут поклоняться Отцу в духе и истине, ибо таких поклонников Отец ищет Себе. Бог есть дух, и поклоняющиеся Ему должны поклоняться в духе и истине.",
            textEn: "The hour cometh, and now is, when the true worshippers shall worship the Father in spirit and in truth: for the Father seeketh such to worship him. God is a Spirit: and they that worship him must worship him in spirit and in truth.",
