        BibleVerse(
            textHy: "Յիսուսն էլ նորանց ասեց. Ես եմ կեանքի հացը. ինձ մօտ եկողը չի սովիլ, եւ ինձ հաւատացողը երբէք չի ծարաւիլ։",
            textHyArarat: "Հիսուսը նրանց ասաց. «Ես եմ կյանքի հացը. դեպի ինձ եկողը չի քաղցի, և ինձ հավատացողը երբեք չի ծարավի։",
            textRu: "Иисус же сказал им: Я есмь хлеб жизни; приходящий ко Мне не будет алкать, и верующий в Меня не будет жаждать никогда.",
            textEn: "And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.",
