        BibleVerse(
            textHy: "Այն ամենը որ Հայրն ինձ տալիս է, ինձ մօտ կգայ. եւ ինձ մօտ եկողին ես դուրս չեմ հանիլ։ Որովհետեւ ես իջայ երկնքիցը, որ ոչ թէ իմ կամքն անեմ, այլ ինձ ուղարկողի կամքը։",
            textHyArarat: "Նա, ում Հայրը ինձ տալիս է, կգա ինձ մոտ, և ինձ մոտ եկողին ես դուրս չեմ անի, որովհետև ես իջել եմ երկնքից, որպեսզի ոչ թե իմ կամքը կատարեմ, այլ ինձ ուղարկողի կամքը։",
            textRu: "Все, что дает Мне Отец, ко Мне придет; и приходящего ко Мне не изгоню вон, ибо Я сошел с небес не для того, чтобы творить волю Мою, но волю пославшего Меня Отца.",
