        BibleVerse(
            textHy: "Դուք չէք հաւատում. որովհետեւ իմ ոչխարներիցը չէք, ինչպէս որ ասեցի ձեզ։ Իմ ոչխարներն իմ ձայնը լսում են, եւ ես ճանաչում եմ նորանց, եւ իմ ետեւից գալիս են։",
            textHyArarat: "Իմ ոչխարներն իմ ձայնը լսում են, ու ես նրանց ճանաչում եմ, և նրանք գալիս են իմ հետևից։ Եվ ես նրանց հավիտենական կյանք եմ տալիս, և նրանք հավիտյան չեն կորչի, ու ոչ ոք նրանց իմ ձեռքից չի հափշտակի։",
            textRu: "Овцы Мои слушаются голоса Моего, и Я знаю их; и они идут за Мною. И Я даю им жизнь вечную, и не погибнут вовек; и никто не похитит их из руки Моей.",
