        BibleVerse(
            textHy: "Մարթան նորան ասեց. Գիտեմ որ յարութիւն կառնէ յարութիւնումը՝ յետին օրը։ Յիսուսը նորան ասեց. Ես եմ յարութիւնը եւ կեանքը. ինձ հաւատացողը թէեւ մեռնի էլ, կապրի։",
            textHyArarat: "Հիսուսը նրան ասաց. «Ես եմ հարությունը և կյանքը. ով հավատում է ինձ, թեկուզ և մեռնի, կապրի։ Եվ ամեն ոք, ով կենդանի է ու ինձ հավատում է, հավիտյան չի մեռնի։ Սրան հավատո՞ւմ ես»։",
            textRu: "Иисус сказал ей: Я есмь воскресение и жизнь; верующий в Меня, если и умрет, оживет. И всякий, живущий и верующий в Меня, не умрет вовек. Веришь ли сему?",
