            textHy: "Ճշմարիտ ճշմարիտ ասում եմ ձեզ. եթէ ցորենի հատը հողի մէջ չընկնի եւ մեռնի, ինքը մինակ կմնայ. բայց եթէ մեռնի, շատ պտուղ կբերէ։",
            textHyArarat: "Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. եթե ցորենի հատիկը հողի մեջ ընկնի ու չմեռնի, միայն հատիկն ինքը կմնա, իսկ եթե մեռնի, շատ արդյունք կտա։",
            textRu: "Истинно, истинно говорю вам: если пшеничное зерно, пав в землю, не умрет, то останется одно; а если умрет, то принесет много плода.",
            textEn: "Verily, verily, I say unto you, Except a corn of wheat fall into the ground and die, it abideth alone: but if it die, it bringeth forth much fruit.",
