        ),
        BibleVerse(
            textHy: "Ձեր սիրտերը թող չխռովին. Աստուծուն հաւատացէք, եւ ինձ հաւատացէք։ Իմ Հօր տանը շատ բնակարաններ կան. ապա թէ ոչ ես ձեզ կասէի. Գնում եմ ձեզ համար տեղ պատրաստելու։ Եւ եթէ գնամ եւ ձեզ համար տեղ պատրաստեմ, դարձեալ կգամ եւ ձեզ ինձ մօտ կառնեմ. որ ուր ես եմ, դուք էլ լինիք,",
            textHyArarat: "«Ձեր սրտերը թող չխռովվեն. հավատացե՛ք Աստծուն, հավատացե՛ք նաև ինձ։ Իմ Հոր տանը բազում օթևաններ կան։ Եթե ոչ, ես ձեզ կասեի։ Ես գնում եմ ձեզ համար տեղ պատրաստելու։ Եվ երբ գնամ ու ձեզ համար տեղ պատրաստեմ, վերստին կգամ ու ձեզ ինձ մոտ կվերցնեմ, որպեսզի որտեղ ես եմ, դուք էլ լինեք։",
            textRu: "Да не смущается сердце ваше; веруйте в Бога, и в Меня веруйте. В доме Отца Моего обителей много. А если бы не так, Я сказал бы вам: Я иду приготовить место вам. И когда пойду и приготовлю вам место, приду опять и возьму вас к Себе, чтобы и вы были, где Я.",
            textEn: "Let not your heart be troubled: ye believe in God, believe also in me. In my Father's house are many mansions: if it were not so, I would have told you. I go to prepare a place for you. And if I go and prepare a place for you, I will come again, and receive you unto myself; that where I am, there ye may be also.",
            refHy: "Հովհաննես 14:1-3",
            refRu: "Иоанна 14:1-3",
            refEn: "John 14:1-3"
        ),
        BibleVerse(
            textHy: "Եթէ ինձ սիրում էք, իմ պատուիրանքները պահեցէք։ Եւ ես Հօրը կաղաչեմ եւ ուրիշ Մխիթարիչ կտայ ձեզ. որ մնայ ձեզ հետ յաւիտեան։ Ճշմարտութեան Հոգին, որին աշխարհքս կարող չէ ընդունել. որ չէ տեսնում նորան. եւ ոչ. Էլ ճանաչում նորան. բայց դուք նորան ճանաչում էք, որովհետեւ ձեզ մօտ է մնում եւ ձեզ հետ կլինի։",
            textHyArarat: "Եթե ինձ սիրում եք, պահե՛ք իմ պատվիրանները։ Եվ ես Հորը կխնդրեմ, և ձեզ ուրիշ Մխիթարիչ կտա, որպեսզի հավիտյան ձեզ հետ լինի. ճշմարտության Հոգին, որին աշխարհը չի կարող ընդունել, որովհետև նրան չի տեսնում և չի ճանաչում։ Բայց դուք նրան ճանաչում եք, որովհետև այն ձեզ մոտ է մնում ու ձեր մեջ է լինելու։",
            textRu: "Если любите Меня, соблюдите Мои заповеди. И Я умолю Отца, и даст вам другого Утешителя, да пребудет с вами вовек, Духа истины, Которого мир не может принять, потому что не видит Его и не знает Его; а вы знаете Его, ибо Он с вами пребывает и в вас будет.",
            textEn: "If ye love me, keep my commandments. And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever; Even the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you.",
            refHy: "Հովհաննես 14:15-17",
            refRu: "Иоанна 14:15-17",
            refEn: "John 14:15-17"
        ),
        BibleVerse(
            textHy: "Եւ սա է յաւիտենական կեանքը, որ ճանաչեն քեզ միայն ճշմարիտ Աստուած. եւ նորան, որ ուղարկեցիր՝ Յիսուսին Քրիստոսին։",
            textHyArarat: "Այս է հավիտենական կյանքը, որ ճանաչեն քեզ իբրև միակ ճշմարիտ Աստծու և նրան, որին ուղարկել ես՝ Հիսուս Քրիստոսին։",
            textRu: "Сия же есть жизнь вечная, да знают Тебя, единого истинного Бога, и посланного Тобою Иисуса Христа.",
            textEn: "And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent.",
            refHy: "Հովհաննես 17:3",
            refRu: "Иоанна 17:3",
            refEn: "John 17:3"
        ),
        BibleVerse(
            textHy: "Յիսուսը նորան ասեց. Որովհետեւ տեսար ինձ՝ հաւատացիր. երանի նորանց, որ չեն տեսել եւ հաւատում են։",
            textHyArarat: "Հիսուսը նրան ասաց. «Հավատացիր, քանի որ տեսար ինձ. երանի՜ նրանց, ովքեր կհավատան առանց տեսնելու»։",
            textRu: "Иисус говорит ему: ты поверил, потому что увидел Меня; блаженны невидевшие и уверовавшие.",
            textEn: "Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed.",
            refHy: "Հովհաննես 20:29",
            refRu: "Иоанна 20:29",
            refEn: "John 20:29"
        ),
        BibleVerse(
            textHy: "Դուք զօրութիւն կ’առնէք՝ երբոր Հոգին ձեզ վերայ կ’գայ, եւ իմ վկաները կ’լինիք Երուսաղէմումը եւ բոլոր Հրէաստանի եւ Սամարիայի մէջ մինչեւ երկրի ծայրերը։",
            textHyArarat: "Դուք զորություն կստանաք, երբ Հոգին ձեզ վրա գա, և իմ վկաները կլինեք Երուսաղեմում, ամբողջ Հրեաստանում ու Սամարիայում, մինչև աշխարհի ծայրերը»։",
            textRu: "Вы примете силу, когда сойдет на вас Дух Святый; и будете Мне свидетелями в Иерусалиме и во всей Иудее и Самарии и даже до края земли.",
            textEn: "Ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth.",
            refHy: "Գործք Առաքելոց 1:8",
            refRu: "Деяния 1:8",
            refEn: "Acts 1:8"
        ),
        BibleVerse(
            textHy: "Եւ էլ մի ուրիշ ոչ մէկով փրկութիւն չ’կայ. Որովհետեւ ուրիշ անուն էլ չ’կայ երկնքի ներքեւ մարդկանց տրուած, որով կարելի լինի մեզ փրկուիլ։",
            textHyArarat: "Եվ ուրիշ մեկի միջոցով փրկություն չկա, որովհետև երկնքի տակ չկա մարդկանց տրված ուրիշ անուն, որով մենք կարող ենք փրկվել»։",
            textRu: "Нет другого имени под небом, данного человекам, которым надлежало бы нам спастись.",
            textEn: "Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved.",
            refHy: "Գործք Առաքելոց 4:12",
            refRu: "Деяния 4:12",
            refEn: "Acts 4:12"
        ),
        BibleVerse(
            textHy: "Ամեն բան ցոյց տուի ձեզ՝ որ այսպէս պէտք է աշխատել, եւ տկարներին հոգ տանել, եւ Տէր Յիսուսի խօսքը յիշել, որ ինքն ասեց. Աւելի երանելի է տալը քան թէ առնելը։",
            textHyArarat: "Ամեն բան ձեզ ցույց տվեցի, որ այսպես պետք է աշխատել և հոգ տանել տկարներին ու Տեր Հիսուսի խոսքը հիշել, որ ասաց. \"Ավելի երանելի է տալը, քան առնելը\"»։",
            textRu: "Во всем показал я вам, что, так трудясь, надобно поддерживать слабых и памятовать слова Господа Иисуса, ибо Он Сам сказал: «блаженнее давать, нежели принимать».",
            textEn: "I have shewed you all things, how that so labouring ye ought to support the weak, and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive.",
            refHy: "Գործք Առաքելոց 20:35",
            refRu: "Деяния 20:35",
            refEn: "Acts 20:35"
        ),
        BibleVerse(
            textHy: "Ես Քրիստոսի աւետարանը ամօթ չեմ համարում. որովհետեւ Աստուծոյ զօրութիւն է փրկելու համար ամեն հաւատացողին, առաջ Հրէային՝ եւ յետոյ Յոյնին։",
            textHyArarat: "Ես Ավետարանը ամոթ չեմ համարում, քանի որ Աստծու զորությունն է ամեն հավատացյալի փրկության համար. նախ՝ հրեայի, ապա՝ նաև հույնի։",
            textRu: "Я не стыжусь благовествования Христова, потому что оно есть сила Божия ко спасению всякому верующему, во-первых, Иудею, потом и Еллину.",
            textEn: "I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek.",
            refHy: "Հռոմեացիս 1:16",
            refRu: "Римлянам 1:16",
            refEn: "Romans 1:16"
        ),
        BibleVerse(
            textHy: "Մենք՝ հաւատքով արդարացած լինելով Աստուծոյ հետ խաղաղութիւն ունինք՝ մեր Տէր Յիսուս Քրիստոսի ձեռովը։ Որով ընդունեցինք հաւատքով այս շնորհքի մէջ մտնելն էլ, որ նորանում կանգնած ենք, եւ պարծենում ենք Աստուծոյ փառքի յոյսովը։",
            textHyArarat: "Մենք, հավատով արդարացած լինելով, Աստծու հետ խաղաղություն ունենք մեր Տեր Հիսուս Քրիստոսի միջոցով։ Նրա միջոցով հավատով ընդունել ենք այս շնորհը, որի մեջ մտել ենք ու կանք և պարծենում ենք Աստծու փառքի հույսով։",
            textRu: "Оправдавшись верою, мы имеем мир с Богом через Господа нашего Иисуса Христа, через Которого верою и получили мы доступ к той благодати, в которой стоим и хвалимся надеждою славы Божией.",
            textEn: "Being justified by faith, we have peace with God through our Lord Jesus Christ: By whom also we have access by faith into this grace wherein we stand, and rejoice in hope of the glory of God.",
            refHy: "Հռոմեացիս 5:1-2",
            refRu: "Римлянам 5:1-2",
            refEn: "Romans 5:1-2"
        ),
        BibleVerse(
            textHy: "Եւ ոչ միայն այսքան, այլ նեղութիւնների մէջ էլ պարծենում ենք. գիտենալով որ նեղութիւնը համբերութիւն է գործում, Համբերութիւնը՝ փորձառութիւն, փորձառութիւնը՝ յոյս. Յոյսն էլ չէ ամաչեցնում. որովհետեւ Աստուծոյ սերը փռուած է մեր սրտերի մէջ Սուրբ Հոգու ձեռովը՝ որ տրուեցաւ մեզ։",
            textHyArarat: "Եվ ոչ միայն այսքանը, այլ նաև նեղությունների մեջ ենք պարծենում՝ գիտենալով, որ նեղությունը համբերություն է բերում, համբերությունը՝ փորձառություն, փորձառությունը՝ հույս։ Իսկ հույսը չի ամաչեցնում, որովհետև Աստծու սերը սփռված է մեր սրտերի մեջ Սուրբ Հոգու միջոցով, որ տրվեց մեզ։",
            textRu: "И не сим только, но хвалимся и скорбями, зная, что от скорби происходит терпение, от терпения опытность, от опытности надежда, а надежда не постыжает, потому что любовь Божия излилась в сердца наши Духом Святым, данным нам.",
            textEn: "And not only so, but we glory in tribulations also: knowing that tribulation worketh patience; And patience, experience; and experience, hope: And hope maketh not ashamed; because the love of God is shed abroad in our hearts by the Holy Ghost which is given unto us.",
            refHy: "Հռոմեացիս 5:3-5",
            refRu: "Римлянам 5:3-5",
            refEn: "Romans 5:3-5"
        ),
        BibleVerse(
            textHy: "Մեղքի վարձքը մահն է. բայց Աստուծոյ շնորհքը՝ յաւիտենական կեանք՝ մեր Տէր Յիսուս Քրիստոսի ձեռովը։",
            textHyArarat: "Մեղքի հատուցումը մահն է, իսկ Աստծու շնորհը՝ հավիտենական կյանքը մեր Տեր Հիսուս Քրիստոսի միջոցով։",
            textRu: "Возмездие за грех — смерть, а дар Божий — жизнь вечная во Христе Иисусе, Господе нашем.",
            textEn: "The wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord.",
            refHy: "Հռոմեացիս 6:23",
            refRu: "Римлянам 6:23",
            refEn: "Romans 6:23"
        ),
        BibleVerse(
            textHy: "Հիմա դատապարտութիւն չ’կայ Յիսուս Քրիստոսումը լինողների համար, որ մարմնաւորապէս չեն վարվում, այլ հոգեւորապէս՝՝։ Որովհետեւ կեանքի հոգու օրէնքը Յիսուս Քրիստոսումն՝ ազատեց ինձ մեղքի եւ մահի օրէնքիցը։",
            textHyArarat: "Հիմա ոչ մի դատապարտություն չկա Հիսուս Քրիստոսի մեջ եղողների համար։ Որովհետև Հիսուս Քրիստոսով կենարար Հոգու օրենքը մեզ ազատեց մեղքի ու մահվան օրենքից։",
            textRu: "Нет ныне никакого осуждения тем, которые во Христе Иисусе живут не по плоти, но по духу, потому что закон духа жизни во Христе Иисусе освободил меня от закона греха и смерти.",
            textEn: "There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit. For the law of the Spirit of life in Christ Jesus hath made me free from the law of sin and death.",
            refHy: "Հռոմեացիս 8:1-2",
            refRu: "Римлянам 8:1-2",
            refEn: "Romans 8:1-2"
        ),
        BibleVerse(
            textHy: "Այնպէս եմ դատում որ այս ժամանակի չարչարանքները արժանի չեն բաղդատուելու այն գալու փառքին հետ, որ մեզանում պիտի յայտնուի։",
            textHyArarat: "Կարծում եմ, որ այս ժամանակի չարչարանքներն արժանի չեն համեմատվելու այն գալիք փառքի հետ, որ հայտնվելու է մեր մեջ։",
            textRu: "Думаю, что нынешние временные страдания ничего не стоят в сравнении с тою славою, которая откроется в нас.",
            textEn: "I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us.",
            refHy: "Հռոմեացիս 8:18",
            refRu: "Римлянам 8:18",
            refEn: "Romans 8:18"
        ),
        BibleVerse(
            textHy: "Եթէ բերանովդ Յիսուսին Տէր դաւանես, եւ սրտումդ հաւատաս թէ Աստուած յարութիւն տուաւ նորան մեռելներից, կ’ապրես։ Քանզի սրտով հաւատում ենք արդարանալու համար, եւ բերանով դաւանում ենք փրկուելու համար։",
            textHyArarat: "Եթե Հիսուսին քո բերանով Տեր դավանես և քո սրտում հավատաս, որ Աստված նրան մեռելներից հարություն տվեց, կփրկվես. քանի որ սրտով հավատում են արդարանալու համար և բերանով դավանում են փրկության համար։",
            textRu: "Если устами твоими будешь исповедывать Иисуса Господом и сердцем твоим веровать, что Бог воскресил Его из мертвых, то спасешься, потому что сердцем веруют к праведности, а устами исповедуют ко спасению.",
            textEn: "That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved. For with the heart man believeth unto righteousness; and with the mouth confession is made unto salvation.",
            refHy: "Հռոմեացիս 10:9-10",
            refRu: "Римлянам 10:9-10",
            refEn: "Romans 10:9-10"
        ),
        BibleVerse(
            textHy: "Հաւատքը լսելուցն է, եւ լսելը՝ Աստուծոյ խօսքիցը։",
            textHyArarat: "Հավատը լսելուց է, իսկ լսելը՝ Քրիստոսի խոսքից։",
            textRu: "Вера от слышания, а слышание от слова Божия.",
            textEn: "So then faith cometh by hearing, and hearing by the word of God.",
            refHy: "Հռոմեացիս 10:17",
            refRu: "Римлянам 10:17",
            refEn: "Romans 10:17"
        ),
        BibleVerse(
            textHy: "Ուրախացողների հետ ուրախացէք, եւ լացողների հետ լացէք։ Իրար վերայ միեւնոյն խորհուրդը ունեցէք. բարձր բաները մի խորհիք. այլ խոնարհների հետ խոնարհուեցէք. ձեր անձերումը իմաստուն մի լինիք։ Մէկին չարի տեղ չար մի հատուցանէք. ամեն մարդկանց առաջին բարի խորհուրդ ունեցէք։ Եթէ կարելի է՝ որքան ձեզանից է կախուած՝ ամեն մարդկանց հետ խաղաղութիւն ունեցէք։",
            textHyArarat: "Ուրախացողների հետ ուրախացե՛ք և լացողների հետ լացե՛ք։ Միմյանց նկատմամբ նույն վերաբերմո՛ւնքն ունեցեք. մեծամիտ մի՛ եղեք, այլ խոնարհների հե՛տ շփվեք. ինքներդ ձեզ իմաստուն մի՛ համարեք։ Որևէ մեկին չարի դիմաց չար մի՛ հատուցեք. բոլոր մարդկանց առաջ բարիք անե՛լ խորհեք։ Եթե հնարավոր է, որքան ձեզանից է կախված, բոլոր մարդկանց հետ խաղաղությա՛մբ մնացեք։",
            textRu: "Радуйтесь с радующимися и плачьте с плачущими. Будьте единомысленны между собою; не высокомудрствуйте, но последуйте смиренным; не мечтайте о себе; никому не воздавайте злом за зло, но пекитесь о добром перед всеми человеками. Если возможно с вашей стороны, будьте в мире со всеми людьми.",
            textEn: "Rejoice with them that do rejoice, and weep with them that weep. Be of the same mind one toward another. Mind not high things, but condescend to men of low estate. Be not wise in your own conceits. Recompense to no man evil for evil. Provide things honest in the sight of all men. If it be possible, as much as lieth in you, live peaceably with all men.",
            refHy: "Հռոմեացիս 12:15-18",
            refRu: "Римлянам 12:15-18",
            refEn: "Romans 12:15-18"
        ),
        BibleVerse(
            textHy: "Խաչի խօսքը կորածների համար յիմարութիւն է, բայց մեզ փրկուածներիս համար Աստուծոյ զօրութիւն է։",
            textHyArarat: "Քանզի խաչի քարոզը կորուսյալների համար հիմարություն է, բայց մեզ՝ փրկվածներիս համար Աստծու զորություն է։",
            textRu: "Слово о кресте для погибающих юродство есть, а для нас, спасаемых, — сила Божия.",
            textEn: "The preaching of the cross is to them that perish foolishness; but unto us which are saved it is the power of God.",
            refHy: "Ա Կորնթացիս 1:18",
            refRu: "1 Коринфянам 1:18",
            refEn: "1 Corinthians 1:18"
        ),
        BibleVerse(
            textHy: "Ձեզ ուրիշ փորձութիւն չէ պատահել բացի մարդկային փորձութիւնից. բայց Աստուած հաւատարիմ է, որ չի թողիլ ձեզ ձեր կարողութիւնիցը վեր փորձուելու, այլ փորձութեան հետ ելքն էլ կպատրաստէ, որ կարողանաք համբերել։",
            textHyArarat: "Ձեզ ուրիշ փորձություն չի պատահել, բացի մարդկային փորձությունից։ Բայց Աստված հավատարիմ է. նա ձեզ չի թողնի ձեր կարողությունից առավել փորձվելու, այլ փորձության հետ ելքն էլ կպատրաստի, որ կարողանաք դիմանալ։",
            textRu: "Вас постигло искушение не иное, как человеческое; и верен Бог, Который не попустит вам быть искушаемыми сверх сил, но при искушении даст и облегчение, так чтобы вы могли перенести.",
            textEn: "There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it.",
            refHy: "Ա Կորնթացիս 10:13",
            refRu: "1 Коринфянам 10:13",
            refEn: "1 Corinthians 10:13"
        ),
        BibleVerse(
            textHy: "Ով մահ, ո՞ւր է քո խայթոցը. գերեզման, ո՞ւր է քո յաղթութիւնը։ Մահի խայթոցը մեղքն է, եւ մեղքի զօրութիւնը՝ օրէնքը։ Բայց շնորհակալութիւն Աստուծուն, որ տուաւ մեզ յաղթութիւնը մեր Տէր Յիսուս Քրիստոսի ձեռովը։ Ուրեմն, սիրելի եղբարքս, հաստատ եղէք, անշարժ կացէք, ամեն ժամանակ աւելի առաջացէք Տիրոջ գործումը, գիտացէք, որ ձեր աշխատանքը զուր չէ Տէրումը։",
            textHyArarat: "Ո՛վ մահ, ո՞ւր է քո խայթոցը, գերեզմա՛ն, ո՞ւր է քո հաղթությունը »։ Մահվան խայթոցը մեղքն է, իսկ մեղքի զորությունը՝ օրենքը։ Բայց շնորհակալություն Աստծուն, որ մեզ հաղթություն տվեց մեր Տեր Հիսուս Քրիստոսի միջոցով։ Ուրեմն, իմ սիրելի՛ եղբայրներ, եղե՛ք հաստատուն և անսասան, Տիրոջ գործի մեջ ամեն ժամ ավելի՛ առաջ գնացեք, իմացե՛ք, որ Տիրոջով ձեր աշխատանքը զուր չէ։",
            textRu: "Смерть! где твое жало? ад! где твоя победа? Жало же смерти — грех; а сила греха — закон. Благодарение Богу, даровавшему нам победу Господом нашим Иисусом Христом! Итак, братия мои возлюбленные, будьте тверды, непоколебимы, всегда преуспевайте в деле Господнем, зная, что труд ваш не тщетен пред Господом.",
            textEn: "O death, where is thy sting? O grave, where is thy victory? The sting of death is sin; and the strength of sin is the law. But thanks be to God, which giveth us the victory through our Lord Jesus Christ. Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.",
            refHy: "Ա Կորնթացիս 15:55-58",
            refRu: "1 Коринфянам 15:55-58",
            refEn: "1 Corinthians 15:55-58"
        ),
        BibleVerse(
            textHy: "Օրհնեալ լինի Աստուած եւ մեր Տէր Յիսուս Քրիստոսի Հայրը, գթութիւնների Հայրը եւ ամեն մխիթարութեան Աստուածը, Որ մխիթարում է մեզ մեր ամեն նեղութիւնումը, որ մենք կարող լինենք մխիթարել նորանց որ ամեն տեսակ նեղութիւնում են՝ այն մխիթարութիւնովն որով մենք Աստուածանից մխիթարվում ենք։",
            textHyArarat: "Օրհնյա՜լ է Աստված և մեր Տեր Հիսուս Քրիստոսի Հայրը, Հայրը գթությունների և Աստված ամեն մխիթարության, որ մեր բոլոր նեղությունների մեջ մխիթարում է մեզ, որպեսզի մենք էլ կարողանանք մխիթարել նրանց, ովքեր ամեն տեսակ նեղության մեջ են, ա՛յն մխիթարությամբ, որով մենք մխիթարվում ենք Աստծուց։",
            textRu: "Благословен Бог и Отец Господа нашего Иисуса Христа, Отец милосердия и Бог всякого утешения, утешающий нас во всякой скорби нашей, чтобы и мы могли утешать находящихся во всякой скорби тем утешением, которым Бог утешает нас самих!",
            textEn: "Blessed be God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort; Who comforteth us in all our tribulation, that we may be able to comfort them which are in any trouble, by the comfort wherewith we ourselves are comforted of God.",
            refHy: "Բ Կորնթացիս 1:3-4",
            refRu: "2 Коринфянам 1:3-4",
            refEn: "2 Corinthians 1:3-4"
        ),
        BibleVerse(
            textHy: "Նորա համար չենք թուլանում. Այլ թէ եւ մեր դրսի մարդը փճանում է, բայց մեր ներսի մարդն օրէցօր նորոգվում է։ Որովհետեւ մեր այժմեան թեթեւ նեղութիւնը ամենագերազանց յաւիտենական փառքի մեծութիւն է գործում մեզ համար, Որ այս երեւող բաներին չենք մտիկ անում, այլ աներեւոյթներին. Որովհետեւ երեւողները ժամանակաւոր են, իսկ չ’երեւողները յաւիտենական։",
            textHyArarat: "Դրա համար չենք վհատվում։ Թեև մեր արտաքին մարդը քայքայվում է, բայց մեր ներքին մարդն օրեցօր նորոգվում է։ Որովհետև մեր այժմյան թեթև նեղությունը գերազանց հավիտենական փառք է պատրաստում մեզ համար, քանի որ այս տեսանելի բաներին չենք նայում, այլ անտեսանելիներին, որովհետև տեսանելի բաները ժամանակավոր են, իսկ անտեսանելիները՝ հավիտենական։",
            textRu: "Мы не унываем; но если внешний наш человек и тлеет, то внутренний со дня на день обновляется. Ибо кратковременное легкое страдание наше производит в безмерном преизбытке вечную славу, когда мы смотрим не на видимое, но на невидимое: ибо видимое временно, а невидимое вечно.",
            textEn: "Which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day. For our light affliction, which is but for a moment, worketh for us a far more exceeding and eternal weight of glory; While we look not at the things which are seen, but at the things which are not seen: for the things which are seen are temporal; but the things which are not seen are eternal.",
            refHy: "Բ Կորնթացիս 4:16-18",
            refRu: "2 Коринфянам 4:16-18",
            refEn: "2 Corinthians 4:16-18"
        ),
        BibleVerse(
            textHy: "Քրիստոսի կողմից պատգամաւորութիւն ենք անում, իբրեւ թէ Աստուած է յորդորում մեզանով. Աղաչում ենք Քրիստոսի տեղ հաշտուեցէք Աստուծոյ հետ։ Որովհետեւ Աստուած նորան, որ մեղք չ’գիտէր, մեզ համար մեղք արաւ. որ մենք Աստուծոյ արդարութիւնը լինենք նորանում։",
            textHyArarat: "Քրիստոսի անունով ենք պատգամաբերություն անում, որպես թե Աստված ինքն է մեր միջոցով պատգամում. հանուն Քրիստոսի աղաչում ենք, հաշտվե՛ք Աստծու հետ։ Որովհետև Աստված նրան, որ մեղքը չէր ճանաչում, մեզ համար մեղավոր արեց, որպեսզի մենք նրանով Աստծու արդարները լինենք։",
            textRu: "Мы — посланники от имени Христова, и как бы Сам Бог увещевает через нас; от имени Христова просим: примиритесь с Богом. Ибо не знавшего греха Он сделал для нас жертвою за грех, чтобы мы в Нем сделались праведными пред Богом.",
            textEn: "Then we are ambassadors for Christ, as though God did beseech you by us: we pray you in Christ's stead, be ye reconciled to God. For he hath made him to be sin for us, who knew no sin; that we might be made the righteousness of God in him.",
            refHy: "Բ Կորնթացիս 5:20-21",
            refRu: "2 Коринфянам 5:20-21",
            refEn: "2 Corinthians 5:20-21"
        ),
        BibleVerse(
            textHy: "Եւ կենդանի եմ, ոչ թէ այլ եւս ես, այլ Քրիստոս է կենդանի ինձանում. Եւ ինչ որ հիմա կենդանի եմ մարմնով՝ Աստուծոյ Որդու հաւատքովն եմ կենդանի. որ ինձ սիրեց եւ իր անձը ինձ համար մատնեց։",
            textHyArarat: "Եվ ողջ եմ, բայց դա այլևս ես չեմ, այլ Քրիստոսն է ողջ իմ մեջ։ Եթե հիմա ապրում եմ մարմնով, ապրում եմ Աստծու Որդու հավատով, որ ինձ սիրեց ու ինքն իրեն ինձ համար զոհեց։",
            textRu: "И уже не я живу, но живет во мне Христос. А что ныне живу во плоти, то живу верою в Сына Божия, возлюбившего меня и предавшего Себя за меня.",
            textEn: "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.",
            refHy: "Գաղատացիներին 2:20",
            refRu: "Галатам 2:20",
            refEn: "Galatians 2:20"
        ),
        BibleVerse(
            textHy: "Այն ազատութիւնովը որ Քրիստոսը մեզ ազատեց, հաստատ կացէք եւ դարձեալ ծառայութեան լծի տակ մի մտնէք։",
            textHyArarat: "Այն ազատությամբ, որ Քրիստոսը մեզ ազատեց, հաստատո՛ւն կացեք ու դարձյալ ծառայության լծի տակ մի՛ մտեք։",
            textRu: "Стойте в свободе, которую даровал нам Христос, и не подвергайтесь опять игу рабства.",
            textEn: "Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.",
            refHy: "Գաղատացիներին 5:1",
            refRu: "Галатам 5:1",
            refEn: "Galatians 5:1"
        ),
        BibleVerse(
            textHy: "Իրար բեռը վեր առէք, եւ այսպէս Քրիստոսի օրէնքը կատարեցէք։",
            textHyArarat: "Միմյանց բեռը կրե՛ք և այսպես Քրիստոսի օրենքը կատարե՛ք։",
            textRu: "Носите бремена друг друга, и таким образом исполните закон Христов.",
            textEn: "Bear ye one another's burdens, and so fulfil the law of Christ.",
            refHy: "Գաղատացիներին 6:2",
            refRu: "Галатам 6:2",
            refEn: "Galatians 6:2"
        ),
        BibleVerse(
            textHy: "Նորան՝ որ կարող է առատութեամբ անել ամեն բաներից աւելի քան որ խնդրում ենք եւ իմանում, այն զօրութեան չափովը՝ որ մեզանում ներգործում է. Նորան փառք լինի եկեղեցումը, որ Քրիստոս Յիսուսումն է, ամեն դարերում յաւիտեանս յաւիտենից։ Ամէն։",
            textHyArarat: "Նրան, ով մեր մեջ ներգործող զորությամբ կարող է առատությամբ ամեն բանից ավելին անել, քան որ խնդրում ենք ու իմանում, փառք նրան եկեղեցու մեջ, որ Քրիստոս Հիսուսով է, սերնդեսերունդ, հավիտյանս հավիտենից։ Ամեն։",
            textRu: "Тому, Кто действующею в нас силою может сделать несравненно больше всего, чего мы просим, или о чем помышляем, Тому слава в Церкви во Христе Иисусе во все роды, от века до века. Аминь.",
            textEn: "Unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us, Unto him be glory in the church by Christ Jesus throughout all ages, world without end. Amen.",
            refHy: "Եփեսացիս 3:20-21",
            refRu: "Ефесянам 3:20-21",
            refEn: "Ephesians 3:20-21"
        ),
        BibleVerse(
            textHy: "Աղաչում եմ ձեզ ես՝ Տիրոջ համար կապուածս, որ այնպէս գնաք ինչպէս որ կվայելէ այն կոչումին որի մէջ կանչուեցաք։ Ամեն խոնարհութիւնով եւ հեզութիւնով եւ երկայնմտութիւնով, սիրով իրար համբերելով։ Ջանալով Հոգու միաբանութիւնը պահել խաղաղութեան կապովը։",
            textHyArarat: "Աղաչում եմ ձեզ ես՝ Տիրոջ համար բանտարկյալս, որ այնպես ընթանաք, ինչպես վայել է այն կոչմանը, որի մեջ կանչվել եք. ամենայն խոնարհությամբ, հեզությամբ և համբերատարությամբ, սիրով միմյանց հանդուրժելով, ջանալով Հոգու միությունը խաղաղության կապով պահել։",
            textRu: "Я, узник в Господе, умоляю вас поступать достойно звания, в которое вы призваны, со всяким смиренномудрием и кротостью и долготерпением, снисходя друг ко другу любовью, стараясь сохранять единство духа в союзе мира.",
            textEn: "I therefore, the prisoner of the Lord, beseech you that ye walk worthy of the vocation wherewith ye are called, With all lowliness and meekness, with longsuffering, forbearing one another in love; Endeavouring to keep the unity of the Spirit in the bond of peace.",
            refHy: "Եփեսացիս 4:1-3",
            refRu: "Ефесянам 4:1-3",
            refEn: "Ephesians 4:1-3"
        ),
        BibleVerse(
            textHy: "Նմանող եղէք Աստուծուն ինչպէս սիրելի որդիներ։ Եւ սէրով գնացէք, ինչպէս որ Քրիստոսն էլ մեզ սիրեց, եւ իր անձը մեզ համար մատնեց, պատարագ եւ զոհ Աստուծոյ անոյշ հոտ լինելու.",
            textHyArarat: "Աստծուն նմանվե՛ք որպես սիրելի որդիներ։ Եվ սիրո՛վ վարվեք, ինչպես որ Քրիստոսն էլ մեզ սիրեց ու իրեն մեզ համար ընծա և զոհ մատուցեց Աստծուն՝ որպես անուշահոտություն։",
            textRu: "Подражайте Богу, как чада возлюбленные, и живите в любви, как и Христос возлюбил нас и предал Себя за нас в приношение и жертву Богу, в благоухание приятное.",
            textEn: "Be ye therefore followers of God, as dear children; And walk in love, as Christ also hath loved us, and hath given himself for us an offering and a sacrifice to God for a sweetsmelling savour.",
            refHy: "Եփեսացիս 5:1-2",
            refRu: "Ефесянам 5:1-2",
            refEn: "Ephesians 5:1-2"
        ),
        BibleVerse(
            textHy: "Եղբարք, ես իմ անձը չեմ համարում որ հասած լինեմ, բայց մէկ բան կայ, ետեւի բաները մոռանալով, դէպի առաջի լինողներն եմ նկրտում։ Հետեւում եմ դէպի նպատակը՝ Աստուծոյ վերին կոչումի մրցանակին Քրիստոս Յիսուսումը։",
            textHyArarat: "Եղբայրնե՛ր, ես ինձ չեմ համարում, որ հասել եմ, բայց մի բան կա. հետևում թողածը մոռանալով՝ դեպի առջևում եղածներն եմ ձգտում։ Հետևում եմ նպատակակետին՝ Հիսուս Քրիստոսով դեպի վեր՝ երկինք՝ Աստծու կողմից կոչվելու մրցանակին։",
            textRu: "Братия, я не почитаю себя достигшим; а только, забывая заднее и простираясь вперед, стремлюсь к цели, к почести вышнего звания Божия во Христе Иисусе.",
            textEn: "Brethren, I count not myself to have apprehended: but this one thing I do, forgetting those things which are behind, and reaching forth unto those things which are before, I press toward the mark for the prize of the high calling of God in Christ Jesus.",
            refHy: "Փիլիպպեցիներին 3:13-14",
            refRu: "Филиппийцам 3:13-14",
            refEn: "Philippians 3:13-14"
        ),
        BibleVerse(
            textHy: "Այսուհետեւ, եղբարք, ինչ որ ճշմարիտ է, ինչ որ պարկեշտ, ինչ որ արդար, ինչ որ սուրբ, ինչ որ սիրուն, ինչ որ բարի անուն, թէ առաքինութիւն է, եւ թէ գովութիւն է, այն մտածեցէք։",
            textHyArarat: "Այսուհետև, եղբայրնե՛ր, ինչ որ ճշմարիտ է, ինչ որ պարկեշտ, ինչ որ արդար, ինչ որ անարատ, ինչ որ սիրելի, ինչ որ բարեհամբավ, առաքինի և գովելի, ա՛յն մտածեք։",
            textRu: "Наконец, братия мои, что только истинно, что честно, что справедливо, что чисто, что любезно, что достославно, что только добродетель и похвала, о том помышляйте.",
            textEn: "Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.",
            refHy: "Փիլիպպեցիներին 4:8",
            refRu: "Филиппийцам 4:8",
            refEn: "Philippians 4:8"
        ),
        BibleVerse(
            textHy: "Եթէ Քրիստոսի հետ յարութիւն առաք, ապա խնդրեցէք վերինները, որտեղ Քրիստոսն է նստում Աստուծոյ աջ կողմը։ Վերինները մտածեցէք, ոչ թէ երկրի վերայինները. Վասնզի դուք մեռաք՝ եւ ձեր կեանքը ծածկուած է Քրիստոսի հետ Աստուծոյ մէջ։",
            textHyArarat: "Եթե Քրիստոսի հետ հարություն առաք, ապա փնտրե՛ք այն, ինչ վերևում է, որտեղ Քրիստոսն է՝ Աստծու աջ կողմում նստած։ Վերևում եղած բաների մասի՛ն մտածեք և ոչ թե այն, ինչ երկրի վրա է։ Որովհետև դուք մեռաք, ու ձեր կյանքը ծածկված է Քրիստոսի հետ Աստծու մեջ։",
            textRu: "Если вы воскресли со Христом, то ищите горнего, где Христос сидит одесную Бога; о горнем помышляйте, а не о земном. Ибо вы умерли, и жизнь ваша сокрыта со Христом в Боге.",
            textEn: "If ye then be risen with Christ, seek those things which are above, where Christ sitteth on the right hand of God. Set your affection on things above, not on things on the earth. For ye are dead, and your life is hid with Christ in God.",
            refHy: "Կողոսացիս 3:1-3",
            refRu: "Колоссянам 3:1-3",
            refEn: "Colossians 3:1-3"
        ),
        BibleVerse(
            textHy: "Եւ ամեն ինչ որ էլ անէք, սրտանց արէք, ինչպէս Տիրոջը, եւ ոչ թէ մարդկանց. Գիտենալով որ Տէրիցը կառնէք ժառանգութեան հատուցումը. վասնզի Տէր Քրիստոսին էք ծառայում։",
            textHyArarat: "Ինչ էլ որ անեք, սրտա՛նց արեք, ինչպես կանեիք Տիրոջ և ոչ թե մարդկանց համար, իմանալով, որ Տիրոջից ժառանգության հատուցումը կստանաք, որովհետև Տիրոջը՝ Քրիստոսին եք ծառայում։",
            textRu: "И всё, что делаете, делайте от души, как для Господа, а не для человеков, зная, что в воздаяние от Господа получите наследие, ибо вы служите Господу Христу.",
            textEn: "And whatsoever ye do, do it heartily, as to the Lord, and not unto men; Knowing that of the Lord ye shall receive the reward of the inheritance: for ye serve the Lord Christ.",
            refHy: "Կողոսացիս 3:23-24",
            refRu: "Колоссянам 3:23-24",
            refEn: "Colossians 3:23-24"
        ),
        BibleVerse(
            textHy: "Սորա համար իրար մխիթարեցէք, եւ իրար շինութիւն տուէք՝ ինչպէս անում էլ էք։",
            textHyArarat: "Դրա համար միմյանց քաջալերե՛ք և ամրապնդե՛ք, ինչպես որ արդեն անում եք։",
            textRu: "Увещавайте друг друга и назидайте один другого, как вы и делаете.",
            textEn: "Comfort yourselves together, and edify one another, even as also ye do.",
            refHy: "Ա Թեսաղոնիկեցիս 5:11",
            refRu: "1 Фессалоникийцам 5:11",
            refEn: "1 Thessalonians 5:11"
        ),
        BibleVerse(
            textHy: "Տէրը հաւատարիմ է, որ կ’հաստատէ ձեզ եւ կ’պահէ այն չարիցը։",
            textHyArarat: "Տերը հավատարիմ է. նա ձեզ կհաստատի և կպահի չարից։",
            textRu: "Верен Господь, Который утвердит вас и сохранит от лукавого.",
            textEn: "The Lord is faithful, who shall stablish you, and keep you from evil.",
            refHy: "Բ Թեսաղոնիկեցիներ 3:3",
            refRu: "2 Фессалоникийцам 3:3",
            refEn: "2 Thessalonians 3:3"
        ),
        BibleVerse(
            textHy: "Ոչ ոք քո մանկութիւնը չ’անարգէ. այլ օրինակ եղիր հաւատացեալներին խօսքով, վարքով, սիրով, հաւատքով, սրբութիւնով,",
            textHyArarat: "Թող ոչ ոք քո երիտասարդ տարիքը չարհամարհի, այլ հավատացյալներին օրինա՛կ եղիր խոսքով, վարքով, սիրով, հավատով, անարատությամբ։",
            textRu: "Никто да не пренебрегает юностью твоею; но будь образцом для верных в слове, в житии, в любви, в духе, в вере, в чистоте.",
            textEn: "Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.",
            refHy: "Ա Տիմոթեոս 4:12",
            refRu: "1 Тимофею 4:12",
            refEn: "1 Timothy 4:12"
        ),
        BibleVerse(
            textHy: "Մեծ շահավաճառութիւն է իրաւ աստուածպաշտութիւնը բաւականութեան հետ միասին։ Որովհետեւ ոչինչ չենք բերել աշխարհքս եւ յայտնի է որ ոչինչ էլ չենք կարող դուրս տանիլ։ Բայց եթէ կերակուր եւ հագուստ ունինք, նորանցով բաւականանանք։",
            textHyArarat: "Սակայն աստվածապաշտությունը գոհունակության հետ միասին մեծ շահ է։ Որովհետև ոչինչ չենք բերել այս աշխարհ և ոչինչ էլ չենք կարող տանել։ Ուտելիք և հագուստ ունենք, դրանցով բավարարվենք։",
            textRu: "Великое приобретение — быть благочестивым и довольным. Ибо мы ничего не принесли в мир; явно, что ничего не можем и вынести из него. Имея пропитание и одежду, будем довольны тем.",
            textEn: "Godliness with contentment is great gain. For we brought nothing into this world, and it is certain we can carry nothing out. And having food and raiment let us be therewith content.",
            refHy: "Ա Տիմոթեոս 6:6-8",
            refRu: "1 Тимофею 6:6-8",
            refEn: "1 Timothy 6:6-8"
        ),
        BibleVerse(
            textHy: "Բարի պատերազմը պատերազմեցի, ընթացքը կատարեցի, հաւատքը պահեցի. Այսուհետեւ մնում է ինձ արդարութեան պսակը, որ Տէրը կ’տայ ինձ այն օրումը՝ արդար դատաւորը. եւ ոչ միայն ինձ, այլ եւ ամենին, որ սիրեցին նորա յայտնութիւնը։",
            textHyArarat: "Բարի պատերազմ մղեցի, ընթացքը ավարտեցի, հավատը պահեցի։ Այսուհետև ինձ է սպասում արդարության պսակը, որ Տերը՝ արդար դատավորը, կտա ինձ այն օրը. և ոչ միայն ինձ, այլև բոլորին, ովքեր սիրեցին նրա հայտնությունը։",
            textRu: "Подвигом добрым я подвизался, течение совершил, веру сохранил; а теперь готовится мне венец правды, который даст мне Господь, праведный Судия, в день оный; и не только мне, но и всем, возлюбившим явление Его.",
            textEn: "I have fought a good fight, I have finished my course, I have kept the faith: Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing.",
            refHy: "Բ Տիմոթեոս 4:7-8",
            refRu: "2 Тимофею 4:7-8",
            refEn: "2 Timothy 4:7-8"
        ),
        BibleVerse(
            textHy: "Երբ որ մեր Փրկիչ Աստուծոյ քաղցրութիւնը եւ մարդասիրութիւնը յայտնուեցաւ, Ոչ թէ արդարութեան գործերիցը, որ մենք արինք, այլ իր ողորմութեան համեմատ փրկեց մեզ միւս անգամ ծնուելու աւազանովը, եւ Սուրբ Հոգու նորոգութիւնովը, Որ առատութիւնով թափեց մեզ վերայ մեր Փրկիչ Յիսուս Քրիստոսի ձեռովը, Որ նորա շնորհքովն արդարացած ժառանգ լինենք յաւիտենական կեանքի յոյսովը։",
            textHyArarat: "Երբ մեր Փրկիչ Աստծու քաղցրությունը և մարդասիրությունը հայտնվեց, նա ոչ թե ըստ մեր կատարած արդար գործերի մեզ փրկեց, այլ իր ողորմությամբ, վերստին ծննդյան ավազանի միջոցով և Սուրբ Հոգու նորոգությամբ, որ առատությամբ մեզ վրա թափեց մեր Փրկիչ Հիսուս Քրիստոսի միջոցով, որպեսզի նրա շնորհով արդարացած՝ ժառանգներ լինենք՝ հավիտենական կյանքի հույսով։",
            textRu: "Когда же явилась благодать и человеколюбие Спасителя нашего, Бога, Он спас нас не по делам праведности, которые бы мы сотворили, а по Своей милости, банею возрождения и обновления Святым Духом, Которого излил на нас обильно через Иисуса Христа, Спасителя нашего, чтобы, оправдавшись Его благодатью, мы по упованию соделались наследниками вечной жизни.",
            textEn: "After that the kindness and love of God our Saviour toward man appeared, Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost; Which he shed on us abundantly through Jesus Christ our Saviour; That being justified by his grace, we should be made heirs according to the hope of eternal life.",
            refHy: "Տիտոս 3:4-7",
            refRu: "Титу 3:4-7",
            refEn: "Titus 3:4-7"
        ),
        BibleVerse(
            textHy: "Աստուծոյ խօսքը կենդանի է եւ զօրաւոր եւ ամեն երկսայրի սուրից աւելի կտրուկ է, եւ թափանցում է մինչեւ շունչի եւ ոգու եւ յօդուածների եւ ծուծի բաժանուիլը. եւ քննող է սրտի մտքերը եւ խորհուրդները։",
            textHyArarat: "Կենդանի է Աստծու խոսքն ու ազդեցիկ և ամեն մի երկսայրի սրից առավել կտրուկ է. այն թափանցում է մինչև շնչի և հոգու, հոդերի և ողնածուծի բաժանումը, քննում է սրտի խոկումներն ու խորհուրդները։",
            textRu: "Слово Божие живо и действенно и острее всякого меча обоюдоострого: оно проникает до разделения души и духа, составов и мозгов и судит помышления и намерения сердечные.",
            textEn: "The word of God is quick, and powerful, and sharper than any twoedged sword, piercing even to the dividing asunder of soul and spirit, and of the joints and marrow, and is a discerner of the thoughts and intents of the heart.",
            refHy: "Եբրայեցիս 4:12",
            refRu: "Евреям 4:12",
            refEn: "Hebrews 4:12"
        ),
        BibleVerse(
            textHy: "Ոչ թէ այնպիսի քահանայապետ ունինք որ չկարողանայ մեր տկարութիւններին հետ կարեկից լինիլ. այլ մի այնպիսին, որ ամեն բանով փորձուած մեր նմանութեամբ, բայց առանց մեղքի։ Ուրեմն համարձակութիւնով մօտենանք շնորհքի աթոռին, որ ողորմութիւն ընդունենք եւ շնորհք գտնենք պատշաճ ժամանակին օգնելու։",
            textHyArarat: "Ոչ թե մի քահանայապետ ունենք, որ չի կարող մեր տկարություններին չարչարակից լինել, այլ մի այնպիսին, որ ամեն բանով փորձված է մեզ նման, բայց առանց մեղքի է։ Ուրեմն նրա շնորհի աթոռին համարձակությամբ մոտենանք, որպեսզի ողորմություն ստանանք ու շնորհ գտնենք մեզ օգնության պատեհ ժամին։",
            textRu: "Мы имеем не такого первосвященника, который не может сострадать нам в немощах наших, но Который, подобно нам, искушен во всем, кроме греха. Посему да приступаем с дерзновением к престолу благодати, чтобы получить милость и обрести благодать для благовременной помощи.",
            textEn: "We have not an high priest which cannot be touched with the feeling of our infirmities; but was in all points tempted like as we are, yet without sin. Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.",
            refHy: "Եբրայեցիս 4:15-16",
            refRu: "Евреям 4:15-16",
            refEn: "Hebrews 4:15-16"
        ),
        BibleVerse(
            textHy: "Առանց հաւատքի անկարելի է հաճոյ լինել. որովհետեւ Աստուծուն մօտեցողը պէտք է հաւատայ, թէ նա կայ, եւ թէ իրան խնդրողներին վարձահատոյց կլինի։",
            textHyArarat: "Առանց հավատի անկարելի է Աստծուն հաճո լինել, որովհետև Աստծուն մոտեցողը պետք է հավատա, որ նա կա և իրեն փնտրողներին վարձահատույց է լինում։",
            textRu: "Без веры угодить Богу невозможно; ибо надобно, чтобы приходящий к Богу веровал, что Он есть, и ищущим Его воздает.",
            textEn: "Without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.",
            refHy: "Եբրայեցիս 11:6",
            refRu: "Евреям 11:6",
            refEn: "Hebrews 11:6"
        ),
        BibleVerse(
            textHy: "Մենք էլ որ վկաների այսքան բազմութիւն ունինք մեզ շրջապատած, դէն գցենք ամեն ծանրութիւն, եւ մեզ դիւրաւ պաշարող մեղքը. եւ համբերութեամբ վազենք մեր առաջին դրած ասպարէզի ընթացքը. Մտիկ տանք հաւատքի զօրագլուխին եւ կատարողին՝ Յիսուսին, որ իր առաջին դրուած ուրախութեան փոխանակ խաչը յանձն առաւ, եւ ամօթն արհամարհելով՝ Աստուծոյ աթոռի աջ կողմը նստեց։",
            textHyArarat: "Մենք էլ, որ շրջապատված ենք վկաների այսչափ բազմությամբ, դեն գցենք ամեն ծանրություն և մեղքը, որ մեզ հեշտությամբ է պաշարում, և համբերությամբ ընթանանք մեր առջև բացված մրցասպարեզ, նայենք հավատի զորագլխին ու այն կատարողին՝ Հիսուսին, որն իր առջև դրված ուրախության փոխարեն խաչը հանձն առավ և ամոթն արհամարհելով՝ Աստծու աթոռի աջ կողմում նստեց։",
            textRu: "И мы, имея вокруг себя такое облако свидетелей, свергнем с себя всякое бремя и запинающий нас грех и с терпением будем проходить предлежащее нам поприще, взирая на начальника и совершителя веры Иисуса, Который, вместо предлежавшей Ему радости, претерпел крест, пренебрегши посрамление, и воссел одесную престола Божия.",
            textEn: "Seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us, Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.",
            refHy: "Եբրայեցիս 12:1-2",
            refRu: "Евреям 12:1-2",
            refEn: "Hebrews 12:1-2"
        ),
        BibleVerse(
            textHy: "Վարքն առանց արծաթասիրութեան լինի. բաւական համարեցէք այն որ ձեռներումդ ունիք. որովհետեւ ինքն ասեց, թէ Չեմ թողիլ քեզ եւ երեսից չեմ գցիլ։ Այնպէս որ համարձակ ենք ասելու. Տէրն է իմ օգնականը, եւ ես չեմ վախենալ, ի՞նչ կանէ ինձ մարդը։",
            textHyArarat: "Վարքն առանց արծաթասիրության թող լինի. բավարա՛ր համարեք այն, ինչ ձեռք եք բերել, որովհետև ինքն իսկ ասաց. «Քեզ չեմ թողնելու ու չեմ լքելու»։ Այնպես որ համարձակվում ենք ասել. «Տերն է իմ օգնականը, և ես չպիտի վախենամ. մարդն ինձ ի՞նչ կարող է անել» ։",
            textRu: "Имейте нрав несребролюбивый, довольствуясь тем, что есть. Ибо Сам сказал: «не оставлю тебя и не покину тебя», так что мы смело говорим: «Господь мне помощник, и не убоюсь: что сделает мне человек?»",
            textEn: "Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee. So that we may boldly say, The Lord is my helper, and I will not fear what man shall do unto me.",
            refHy: "Եբրայեցիս 13:5-6",
            refRu: "Евреям 13:5-6",
            refEn: "Hebrews 13:5-6"
        ),
        BibleVerse(
            textHy: "Նորա ձեռովն ամեն ժամանակ Աստուծուն օրհնութեան պատարագ մատուցանենք. այսինքն նորա անունը դաւանող շրթունքների պտուղ։ Իսկ բարերարութիւնը եւ հաղորդակցիլը մի մոռանաք. որ այնպիսի պատարագներին հաւանում է Աստուած։",
            textHyArarat: "Նրա միջոցով ամեն ժամանակ Աստծուն օրհնության զոհ մատուցենք, այսինքն՝ նրա անունը դավանող շրթունքների պտուղը։ Մի՛ մոռացեք բարեգործություն անել և կարոտյալներին ձեր ունեցածից բաժին հանել. այդպիսի զոհերը հաճելի են Աստծուն։",
            textRu: "Будем через Него непрестанно приносить Богу жертву хвалы, то есть плод уст, прославляющих имя Его. Не забывайте также благотворения и общительности, ибо таковые жертвы благоугодны Богу.",
            textEn: "By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name. But to do good and to communicate forget not: for with such sacrifices God is well pleased.",
            refHy: "Եբրայեցիս 13:15-16",
            refRu: "Евреям 13:15-16",
            refEn: "Hebrews 13:15-16"
        ),
        BibleVerse(
            textHy: "Բոլորովին ուրախութիւն համարեցէք, եղբարքս, երբոր կերպ կերպ փորձանքների մէջ ընկնիք. Գիտենալով որ ձեր հաւատքի փորձառութիւնը համբերութիւն է գործում։ Իսկ համբերութիւնը թող կատարեալ գործ ունենայ. Որ կատարեալ եւ ամբողջ լինիք, եւ ոչ մի բանի պակասութիւն չ’ունենաք։",
            textHyArarat: "Լիարժեք ուրախությո՛ւն համարեք, եղբայրնե՛ր, երբ տարատեսակ փորձանքների մեջ ընկնեք՝ իմանալով, որ ձեր հավատի փորձությունը համբերություն է առաջացնում։ Իսկ համբերությունը թող լիովին գործուն լինի, որպեսզի կատարյալ ու լիարժեք լինեք և ոչ մի բանի պակասություն չունենաք։",
            textRu: "С великою радостью принимайте, братия мои, когда впадаете в различные искушения, зная, что испытание вашей веры производит терпение; терпение же должно иметь совершенное действие, чтобы вы были совершенны во всей полноте, без всякого недостатка.",
            textEn: "My brethren, count it all joy when ye fall into divers temptations; Knowing this, that the trying of your faith worketh patience. But let patience have her perfect work, that ye may be perfect and entire, wanting nothing.",
            refHy: "Հակոբոս 1:2-4",
            refRu: "Иакова 1:2-4",
            refEn: "James 1:2-4"
        ),
        BibleVerse(
            textHy: "Երանելի է այն մարդը որ համբերում է փորձութեան. Վասնզի եթէ փորձուելով ընտիր գտնուի կեանքի պսակը կ’առնէ, այն որ Տէրը խոստացաւ իրան սիրողներին։",
            textHyArarat: "Երանելի է այն մարդը, որ համբերում է փորձության, որովհետև փորձվելով կստանա կյանքի պսակը, որ Տերը խոստացավ իրեն սիրողներին։",
            textRu: "Блажен человек, который переносит искушение, потому что, быв испытан, он получит венец жизни, который обещал Господь любящим Его.",
            textEn: "Blessed is the man that endureth temptation: for when he is tried, he shall receive the crown of life, which the Lord hath promised to them that love him.",
            refHy: "Հակոբոս 1:12",
            refRu: "Иакова 1:12",
            refEn: "James 1:12"
