        BibleVerse(
            textHy: "Ուստի, իմ սիրելի եղբայրներ, թող ամեն մարդ շուտ լինի լսելու համար, եւ ծանր՝ խօսելու համար, եւ ծանր՝ բարկանալու համար։ Որովհետեւ մարդի բարկութիւնն Աստուծոյ արդարութիւնը չէ գործում։",
            textHyArarat: "Իմացե՛ք, իմ սիրելի՛ եղբայրներ, թող ամեն մարդ արագահաս լինի լսելու մեջ, ծանրաշարժ՝ խոսելու և բարկանալու մեջ. որովհետև մարդու բարկությունն Աստծու արդարությունը չի կատարում։",
            textRu: "Братия мои возлюбленные, всякий человек да будет скор на слышание, медлен на слова, медлен на гнев, ибо гнев человека не творит правды Божией.",
            textEn: "Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath: For the wrath of man worketh not the righteousness of God.",
            refHy: "Հակոբոս 1:19-20",
            refRu: "Иакова 1:19-20",
            refEn: "James 1:19-20"
        ),
        BibleVerse(
            textHy: "Խօսքը անող եղէք, եւ ոչ միայն լսողներ՝ ձեր անձերը խաբելով։",
            textHyArarat: "Խոսքը կատարողնե՛ր եղեք և ոչ միայն լսողներ, որ ինքներդ ձեզ խաբեք։",
            textRu: "Будьте же исполнители слова, а не слышатели только, обманывающие самих себя.",
