        BibleVerse(
            textHy: "Խոնարհեցէք Տիրոջ առաջին, եւ նա կ’բարձրացնէ ձեզ։",
            textHyArarat: "Խոնարհվե՛ք Տիրոջ առաջ, և նա ձեզ կբարձրացնի։",
            textRu: "Смиритесь пред Господом, и вознесет вас.",
            textEn: "Humble yourselves in the sight of the Lord, and he shall lift you up.",
            refHy: "Հակոբոս 4:10",
