        BibleVerse(
            textHy: "Իրար խոստովանեցէք ձեր յանցանքները, եւ իրար վերայ աղօթք արէք, որ բժշկուիք, շատ զօրաւոր է արդարի աղօթքը ներգործելով։",
            textHyArarat: "Միմյանց խոստովանե՛ք ձեր մեղքերը և միմյանց համար աղոթե՛ք, որ բժշկվեք։ Արդարի աղոթքը ավելի ուժեղ է ներգործում։",
            textRu: "Признавайтесь друг пред другом в проступках и молитесь друг за друга, чтобы исцелиться: много может усиленная молитва праведного.",
            textEn: "Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much.",
            refHy: "Հակոբոս 5:16",
            refRu: "Иакова 5:16",
            refEn: "James 5:16"
        ),
        BibleVerse(
            textHy: "Օրհնեալ է Աստուած եւ մեր Տէր Յիսուս Քրիստոսի Հայրը, որ իր առատ ողորմութեան համեմատ մեզ վերստին ծնեց դէպի կենդանի յոյսը, Յիսուս Քրիստոսի մեռելներից յարութիւն առնելովը, Դէպի այն անեղծ եւ անարատ եւ անթառամ ժառանգութիւնը, որ երկնքումը պահուած է ձեզ համար. Որ Աստուծոյ զօրութեամբը պահպանվում էք հաւատքով դէպի պատրաստուած փրկութիւնը, որ յայտնուելու էր յետին ժամանակումը։",
            textHyArarat: "Օրհնյալ է Աստված և Հայրը մեր Տեր Հիսուս Քրիստոսի, որ իր առատ ողորմությամբ մեզ վերստին ծնեց կենդանի հույսի համար՝ մեռելներից Հիսուս Քրիստոսի հարությամբ, այն անեղծ, անարատ ու անթառամ ժառանգության համար, որ երկնքում պահված է ձեզ համար, որ Աստծու զորությամբ հավատով պահպանվում եք փրկության համար, որ պատրաստ է հայտնվելու վերջին ժամին։",
            textRu: "Благословен Бог и Отец Господа нашего Иисуса Христа, по великой Своей милости возродивший нас воскресением Иисуса Христа из мертвых к упованию живому, к наследству нетленному, чистому, неувядаемому, хранящемуся на небесах для вас, силою Божиею через веру соблюдаемых ко спасению, готовому открыться в последнее время.",
            textEn: "Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead, To an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for you, Who are kept by the power of God through faith unto salvation ready to be revealed in the last time.",
            refHy: "Ա Պետրոս 1:3-5",
            refRu: "1 Петра 1:3-5",
            refEn: "1 Peter 1:3-5"
        ),
        BibleVerse(
            textHy: "Դուք ընտիր ազգ էք, թագաւորական քահանայութիւն, սուրբ ազգ, սեփհական ժողովուրդ, որ քարոզէք նորա առաքինութիւնները, որ ձեզ խաւարիցը կանչեց իր զարմանալի լոյսի մէջ. Որ դուք ժամանակով ժողովուրդ չ’էիք, բայց հիմա Աստուծոյ ժողովուրդ էք. Որ ողորմուած չ’էիք, բայց հիմա ողորմուածներ։",
            textHyArarat: "Դուք ընտիր ցեղ եք, թագավորական քահանայություն, սուրբ ազգ, սեփական ժողովուրդ, որպեսզի նրա՛ առաքինությունները քարոզեք, ով ձեզ խավարից դեպի իր սքանչելի լույսը կանչեց։ Որովհետև դուք ժամանակին ժողովուրդ չէիք, բայց հիմա Աստծու ժողովուրդ եք, որ ողորմություն չէիք գտել, բայց հիմա արժանացել եք ողորմության։",
            textRu: "Вы — род избранный, царственное священство, народ святой, люди, взятые в удел, дабы возвещать совершенства Призвавшего вас из тьмы в чудный Свой свет; некогда не народ, а ныне народ Божий; некогда непомилованные, а ныне помилованы.",
            textEn: "Ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light: Which in time past were not a people, but are now the people of God: which had not obtained mercy, but now have obtained mercy.",
            refHy: "Ա Պետրոս 2:9-10",
            refRu: "1 Петра 2:9-10",
            refEn: "1 Peter 2:9-10"
        ),
        BibleVerse(
            textHy: "Եւ վերջապէս ամենդ համամիտ, կարեկից, եղբայրասէր, բարեսիրտ, քաղցրաբարոյ եղէք։ Չարի փոխարէն չար չ’հատուցանէք, կամ բամբասանքի փոխարէն բամբասանք. Այլ ընդ հակառակն օրհնեցէք, գիտենալով որ իսկ սորա մէջ կանչուեցաք, որ օրհնութիւնը ժառանգէք։",
            textHyArarat: "Եվ վերջապես, բոլորդ եղե՛ք համախոհ, կարեկից, եղբայրասեր, բարեգութ, խոնարհ։ Չարի դիմաց չար մի՛ հատուցեք կամ բամբասանքի դիմաց՝ բամբասանք, այլ ընդհակառակը, օրհնե՛ք, որովհետև հենց նրա համար եք կանչվել, որ օրհնությունը ժառանգեք։",
            textRu: "Наконец будьте все единомысленны, сострадательны, братолюбивы, милосерды, дружелюбны, смиренномудры; не воздавайте злом за зло или ругательством за ругательство; напротив, благословляйте, зная, что вы к тому призваны, чтобы наследовать благословение.",
            textEn: "Finally, be ye all of one mind, having compassion one of another, love as brethren, be pitiful, be courteous: Not rendering evil for evil, or railing for railing: but contrariwise blessing; knowing that ye are thereunto called, that ye should inherit a blessing.",
            refHy: "Ա Պետրոս 3:8-9",
            refRu: "1 Петра 3:8-9",
            refEn: "1 Peter 3:8-9"
        ),
        BibleVerse(
            textHy: "Եւ ամեն շնորհքի Աստուածը, որ մեզ կանչեց իր յաւիտենական փառքի մէջ Քրիստոս Յիսուսով, ձեզ որ մի քիչ չարչարվում էք, կատարեալ անէ, հաստատէ, զօրացնէ, հիմնէ.",
            textHyArarat: "Եվ ամեն շնորհի Աստվածը, որ ձեզ Քրիստոս Հիսուսով դեպի իր հավիտենական փառքը կանչեց, ձեր՝ փոքր-ինչ չարչարվելուց հետո կվերականգնի, կամրացնի, կզորացնի, հաստատահիմն կդարձնի։",
            textRu: "Бог же всякой благодати, призвавший нас в вечную славу Свою во Христе Иисусе, Сам, по кратковременном страдании вашем, да совершит вас, да утвердит, да укрепит, да соделает непоколебимыми.",
            textEn: "The God of all grace, who hath called us unto his eternal glory by Christ Jesus, after that ye have suffered a while, make you perfect, stablish, strengthen, settle you.",
            refHy: "Ա Պետրոս 5:10",
            refRu: "1 Петра 5:10",
            refEn: "1 Peter 5:10"
        ),
        BibleVerse(
            textHy: "Այս մէկն էլ ձեզանից ծածուկ չ’լինի, սիրելիներ, որ Տիրոջ մօտ մէկ օրը հազար տարուայ պէս է, եւ հազար տարին ինչպէս մէկ օր։ Տէրը չի ուշացնիլ խոստումը, ինչպէս ոմանք ուշացնել են կարծում, բայց երկայնամիտ է լինում մեզ վերայ, որովհետեւ չէ կամենում որ կորչողներ լինեն, բայց որ ամենն ապաշխարութեան հասնեն։",
            textHyArarat: "Այս մեկը ևս ձեզանից ծածկված թող չլինի, սիրելինե՛ր, որ Տիրոջ համար մեկ օրը հազար տարվա պես է, իսկ հազար տարին՝ մեկ օրվա պես։ Տերը խոստումը չի ուշացնի, ինչպես ոմանք կարծում են, թե ուշացնում է, այլ մեր նկատմամբ համբերատար է, որովհետև չի ցանկանում, որ որևէ մեկը կորստյան մատնվի, այլ որ բոլորն էլ ապաշխարության գան։",
            textRu: "Одно то не должно быть сокрыто от вас, возлюбленные, что у Господа один день, как тысяча лет, и тысяча лет, как один день. Не медлит Господь исполнением обетования, как некоторые почитают то медлением; но долготерпит нас, не желая, чтобы кто погиб, но чтобы все пришли к покаянию.",
            textEn: "But, beloved, be not ignorant of this one thing, that one day is with the Lord as a thousand years, and a thousand years as one day. The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.",
            refHy: "Բ Պետրոս 3:8-9",
            refRu: "2 Петра 3:8-9",
            refEn: "2 Peter 3:8-9"
        ),
        BibleVerse(
            textHy: "Տեսէք թէ Հայրն ինչպիսի սէր շնորհեց մեզ, որ Աստուծոյ որդիք կոչուինք, սորա համար աշխարհքը չէ ճանաչում մեզ, որ նորան չ’ճանաչեց։",
            textHyArarat: "Տեսեք՝ ինչպիսի՜ սեր շնորհեց մեզ Հայրը, որպեսզի Աստծու որդիներ կոչվենք և իսկապես ենք. աշխարհը մեզ նրա համար չի ճանաչում, որ նրան չճանաչեց։",
            textRu: "Смотрите, какую любовь дал нам Отец, чтобы нам называться и быть детьми Божиими. Мир потому не знает нас, что не познал Его.",
            textEn: "Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.",
            refHy: "Ա Հովհաննես 3:1",
            refRu: "1 Иоанна 3:1",
            refEn: "1 John 3:1"
        ),
        BibleVerse(
            textHy: "Սորանով Աստուծոյ սէրն երեւեցաւ մեզանում, որ Աստուած իր միածին Որդուն ուղարկեց աշխարհք, որ նորանով կեանք ունենանք։ Սորանում է սէրը, որ ոչ թէ մենք սիրեցինք Աստուծուն, այլ որ նա սիրեց մեզ, եւ ուղարկեց իր Որդուն քաւութիւն մեր մեղքերի համար։ Սիրելիներ, եթէ Աստուած այսպէս սիրեց մեզ, ապա մենք էլ պէտք է իրար սիրենք։",
            textHyArarat: "Աստծու սերը մեր հանդեպ նրանով երևաց, որ Աստված իր միածին Որդուն աշխարհ ուղարկեց, որպեսզի նրանով ապրենք։ Սրա մեջ է սերը. ոչ թե մենք սիրեցինք Աստծուն, այլ նա մեզ սիրեց և իր Որդուն ուղարկեց մեր մեղքերի քավության համար։ Սիրելինե՛ր, եթե Աստված մեզ այսպես սիրեց, ապա մենք էլ պետք է միմյանց սիրենք։",
            textRu: "Любовь Божия к нам открылась в том, что Бог послал в мир Единородного Сына Своего, чтобы мы получили жизнь через Него. В том любовь, что не мы возлюбили Бога, но Он возлюбил нас и послал Сына Своего в умилостивление за грехи наши. Возлюбленные! если так возлюбил нас Бог, то и мы должны любить друг друга.",
            textEn: "In this was manifested the love of God toward us, because that God sent his only begotten Son into the world, that we might live through him. Herein is love, not that we loved God, but that he loved us, and sent his Son to be the propitiation for our sins. Beloved, if God so loved us, we ought also to love one another.",
            refHy: "Ա Հովհաննես 4:9-11",
            refRu: "1 Иоанна 4:9-11",
            refEn: "1 John 4:9-11"
        ),
        BibleVerse(
            textHy: "Ահա ես դռան առաջին կանգնած եմ եւ թակում եմ. եթէ մէկը լսէ իմ ձայնը եւ դուռը բանայ, կ’մտնեմ նորա մօտ եւ ընթրիք կ’անեմ նորա հետ, եւ նա ինձ հետ։",
            textHyArarat: "Ահա ես դռան առաջ կանգնած եմ ու բախում եմ. եթե մեկն իմ ձայնը լսի և դուռը բացի, նրա մոտ կմտնեմ ու նրա հետ կընթրեմ, նա էլ՝ ինձ հետ։",
            textRu: "Се, стою у двери и стучу: если кто услышит голос Мой и отворит дверь, войду к нему, и буду вечерять с ним, и он со Мною.",
            textEn: "Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me.",
            refHy: "Հայտնություն 3:20",
            refRu: "Откровение 3:20",
            refEn: "Revelation 3:20"
        ),
        BibleVerse(
            textHy: "Եւ աթոռի վերայ նստողն ասեց. Ահա ամեն բան նոր եմ անում. եւ ասեց ինձ. Գրիր. որ այս խօսքերը ճշմարիտ եւ հաւատարիմ են։ Եւ ինձ ասեց. Եղաւ, ես եմ Ալֆան եւ Օմեղան. սկիզբը եւ վերջը. ես ձրի կ’տամ ծարաւին կեանքի ջրի աղբիւրիցը։ Ով որ յաղթէ, ամենը կ’ժառանգէ. եւ ես կ’լինիմ նորան Աստուած, եւ նա կ’լինի ինձ որդի։",
            textHyArarat: "Եվ գահի վրա նստողն ասաց. «Ահա ամեն բան նոր եմ դարձնում»։ Եվ ասաց. «Գրի՛ր, որ այս խոսքերը ճշմարիտ ու հավաստի են»։ Եվ ինձ ասաց. «Եղա՛վ. ես եմ Ալֆան և Օմեգան, Սկիզբն ու Վերջը։ Ես եմ ծարավածին ձրի տալու կենաց ջրի աղբյուրից։ Հաղթողն է դա ժառանգելու. ես նրա Աստվածն եմ լինելու, իսկ նա իմ որդին է լինելու։",
            textRu: "И сказал Сидящий на престоле: се, творю все новое. И говорит мне: напиши; ибо слова сии истинны и верны. И сказал мне: совершилось! Я есмь Альфа и Омега, начало и конец; жаждущему дам даром от источника воды живой. Побеждающий наследует все, и буду ему Богом, и он будет Мне сыном.",
            textEn: "And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful. And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely. He that overcometh shall inherit all things; and I will be his God, and he shall be my son.",
            refHy: "Հայտնություն 21:5-7",
            refRu: "Откровение 21:5-7",
            refEn: "Revelation 21:5-7"
        ),
        BibleVerse(
            textHy: "Եւ Հոգին եւ հարսն ասում են. Եկ. եւ լսողն ասէ, Եկ. եւ նա որ ծարաւ է՝ թող գայ, եւ նա որ կամենում է՝ թող առնէ կեանքի ջուրը ձրի։",
            textHyArarat: "Հոգին ու հարսն ասում են. «Արի՛»։ Լսողը ևս ասում է. «Արի՛։ Թող գա, ով ծարավ է, և ով կամենում է, թող ձրի վերցնի կենաց ջուրը»։",
            textRu: "И Дух и невеста говорят: прииди! И слышавший да скажет: прииди! Жаждущий пусть приходит, и желающий пусть берет воду жизни даром.",
            textEn: "And the Spirit and the bride say, Come. And let him that heareth say, Come. And let him that is athirst come. And whosoever will, let him take the water of life freely.",
            refHy: "Հայտնություն 22:17",
            refRu: "Откровение 22:17",
            refEn: "Revelation 22:17"
        ),
        BibleVerse(
            textHy: "Եւ արդարների փրկութիւնը Տէրիցն է. նա նորանց զօրութիւնն է նեղութեան ժամանակում։ Եւ Տէրը կօգնէ նորանց եւ կազատէ նորանց. կազատէ նորանց ամբարիշտներիցը եւ կփրկէ նորանց, որովհետեւ նորան են յուսացած։",
            textHyArarat: "Արդարների փրկությունը Տիրոջից է. նեղության ժամանակ նա է նրանց ապաստանը։ Տերը կօգնի նրանց և կազատի նրանց. նրանց կազատի ամբարիշտներից և կփրկի նրանց, որովհետև իրենց հույսը դրել են նրա վրա։",
            textRu: "От Господа спасение праведникам, Он — защита их во время скорби; и поможет им Господь и избавит их; избавит их от нечестивых и спасет их, ибо они на Него уповают.",
            textEn: "The salvation of the righteous is of the LORD: he is their strength in the time of trouble. And the LORD shall help them, and deliver them: he shall deliver them from the wicked, and save them, because they trust in him.",
            refHy: "Սաղմոսներ 37:39-40",
            refRu: "Псалом 36:39-40",
            refEn: "Psalm 37:39-40"
        ),
        BibleVerse(
            textHy: "Ով իմ անձը, մինակ լուռ մտիկ տուր Աստուծուն. որովհետեւ նորանից է իմ յոյսը։ Իրաւի որ նա է իմ վէմը, իմ փրկութիւնը, իմ ապաւէնը. ես չեմ շարժուիլ։",
            textHyArarat: "Ո՛վ անձ իմ, միայն Աստծո՛ւն վստահիր, որովհետև նրանից է իմ հույսը։ Հիրավի, նա է իմ վեմը, իմ փրկությունը, իմ ապավենը. ես պիտի չսասանվեմ։",
            textRu: "Только в Боге успокаивайся, душа моя! ибо на Него надежда моя. Только Он — твердыня моя и спасение мое, убежище мое: не поколеблюсь.",
            textEn: "My soul, wait thou only upon God; for my expectation is from him. He only is my rock and my salvation: he is my defence; I shall not be moved.",
            refHy: "Սաղմոսներ 62:5-6",
            refRu: "Псалом 61:5-6",
            refEn: "Psalm 62:5-6"
        ),
        BibleVerse(
            textHy: "Ինչպէս որ հայրը կգթայ որդիներին, այնպէս գթած է Տէրը իրանից վախեցողներին։ Որովհետեւ նա գիտէ մեր կազմուածքը. յիշում է որ հող ենք մենք։",
            textHyArarat: "Ինչպես որ հայրն է գթում իր որդիներին, այնպես Տերն է գթած իրենից վախեցողների հանդեպ։ Որովհետև նա գիտի մեր կազմվածքը, հիշում է, որ հող ենք մենք։",
            textRu: "Как отец милует сынов, так милует Господь боящихся Его. Ибо Он знает состав наш, помнит, что мы — персть.",
            textEn: "Like as a father pitieth his children, so the LORD pitieth them that fear him. For he knoweth our frame; he remembereth that we are dust.",
            refHy: "Սաղմոսներ 103:13-14",
            refRu: "Псалом 102:13-14",
            refEn: "Psalm 103:13-14"
        ),
        BibleVerse(
            textHy: "Թող գոհանան Տէրիցը նորա ողորմութեան համար, եւ նորա հրաշքների համար որ արաւ մարդկանց որդիներին. Որ նա կշտացնում է կարօտած անձին, եւ լցնում է սոված անձը բարութիւնով։",
            textHyArarat: "Թող գոհանան Տիրոջից նրա ողորմության համար և նրա հրաշքների համար, որ արեց մարդկանց որդիներին. Որովհետև նա կշտացնում է կարոտած անձին և սոված անձին լցնում է բարությամբ։",
            textRu: "Да славят Господа за милость Его и за чудные дела Его для сынов человеческих: ибо Он насытил душу жаждущую и душу алчущую исполнил благами.",
            textEn: "Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men! For he satisfieth the longing soul, and filleth the hungry soul with goodness.",
            refHy: "Սաղմոսներ 107:8-9",
            refRu: "Псалом 106:8-9",
            refEn: "Psalm 107:8-9"
