        BibleVerse(
            textHy: "Ես ուրախ եմ, որ Տէրը լսեց իմ աղաչանքի ձայնին։ Որ նա իր ականջը խոնարհեցրեց դէպի ինձ. եւ ես իմ օրերումը կկանչեմ նորան։",
            textHyArarat: "Ես ուրախ եմ, որ Տերը լսեց իմ ձայնը և իմ աղաչանքը, Որ իր ականջը խոնարհեց դեպի ինձ, և ես իմ բոլոր օրերում պիտի կանչեմ նրան։",
            textRu: "Я радуюсь, что Господь услышал голос мой, моление мое; приклонил ко мне ухо Свое, и потому буду призывать Его во все дни мои.",
            textEn: "I love the LORD, because he hath heard my voice and my supplications. Because he hath inclined his ear unto me, therefore will I call upon him as long as I live.",
            refHy: "Սաղմոսներ 116:1-2",
            refRu: "Псалом 116:1-2",
            refEn: "Psalm 116:1-2"
