        BibleVerse(
            textHy: "Նեղութեան միջից Տիրոջը կանչեցի. Տէրը լսեց ինձ եւ լայնարձակ տեղ հանեց։ Տէրն ինձ հետ է. ես չեմ վախենալ. մարդն ինձ ի՞նչ կանէ։",
            textHyArarat: "Նեղության մեջ կանչեցի Տիրոջը. Տերն ինձ լսեց և ընդարձակ տեղ հանեց։ Տերն ինձ հետ է. ես չեմ վախենում. մարդն ինձ ի՞նչ է անելու։",
            textRu: "Из тесноты воззвал я к Господу, — и услышал меня, и на пространное место вывел меня Господь. Господь за меня — не устрашусь: что сделает мне человек?",
            textEn: "I called upon the LORD in distress: the LORD answered me, and set me in a large place. The LORD is on my side; I will not fear: what can man do unto me?",
            refHy: "Սաղմոսներ 118:5-6",
            refRu: "Псалом 117:5-6",
            refEn: "Psalm 118:5-6"
        ),
        BibleVerse(
            textHy: "Լաւ է Տիրոջը յուսալ՝ քան թէ մարդկանց ապաւինել։ Լաւ է Տիրոջը յուսալ՝ քան թէ իշխաններին ապաւինել։",
            textHyArarat: "Լավ է հույսը դնել Տիրոջ վրա, քան թե մարդկանց ապավինել։ Լավ է հույսը դնել Տիրոջ վրա, քան թե իշխաններին ապավինել։",
            textRu: "Лучше уповать на Господа, нежели надеяться на человека. Лучше уповать на Господа, нежели надеяться на князей.",
            textEn: "It is better to trust in the LORD than to put confidence in man. It is better to trust in the LORD than to put confidence in princes.",
            refHy: "Սաղմոսներ 118:8-9",
            refRu: "Псалом 117:8-9",
            refEn: "Psalm 118:8-9"
