        BibleVerse(
            textHy: "Իմ նեղութիւնումն այն է իմ մխիթարութիւնը՝ որ քո խօսքն ապրեցնում է ինձ։",
            textHyArarat: "Նեղությանս մեջ իմ մխիթարությունն այն է, որ քո խոսքն ապրեցնում է ինձ։",
            textRu: "Это — утешение в бедствии моем, что слово Твое оживляет меня.",
