        BibleVerse(
            textHy: "Շատ խաղաղութիւն կայ քո օրէնքը սիրողների համար. եւ գայթակղութիւն չկայ նորանց համար։",
            textHyArarat: "Մեծ խաղաղություն կա քո օրենքը սիրողների համար, և գայթակղություն չկա նրանց համար։",
            textRu: "Велик мир у любящих закон Твой, и нет им преткновения.",
            textEn: "Great peace have they which love thy law: and nothing shall offend them.",
            refHy: "Սաղմոսներ 119:165",
            refRu: "Псалом 118:165",
            refEn: "Psalm 119:165"
