        BibleVerse(
            textHy: "Ո՞ւր գնամ քո Հոգիիցը. եւ քո երեսիցն ո՞ւր փախչեմ։ Եթէ վերանամ երկինքը՝ դու այնտեղ ես. եւ եթէ դժոխքը փաթաթուիմ, ահա դու այնտեղ ես։ Եթէ արշալուսի թեւերն առնեմ եւ ծովի վերջի ծայրերումը բնակուեմ, Այնտեղ էլ քո ձեռքը կառաջնորդէ ինձ, եւ քո աջը կպահէ ինձ։",
            textHyArarat: "Ո՞ւր գնամ քո Հոգուց և քո ներկայությունից ո՞ւր փախչեմ։ Եթե վեր ելնեմ երկինք, դու այնտեղ ես, և եթե պառկեմ դժոխքի մեջ, ահա դու այնտեղ ես։ Եթե արշալույսի թևերն առնեմ և բնակվեմ ծովի վերջին ծայրերին, Այնտեղ էլ քո ձեռքն է առաջնորդելու ինձ, և քո աջն է բռնելու ինձ։",
            textRu: "Куда пойду от Духа Твоего, и от лица Твоего куда убегу? Взойду ли на небо — Ты там; сойду ли в преисподнюю — и там Ты. Возьму ли крылья зари и переселюсь на край моря, — и там рука Твоя поведет меня, и удержит меня десница Твоя.",
            textEn: "Whither shall I go from thy spirit? or whither shall I flee from thy presence? If I ascend up into heaven, thou art there: if I make my bed in hell, behold, thou art there. If I take the wings of the morning, and dwell in the uttermost parts of the sea; Even there shall thy hand lead me, and thy right hand shall hold me.",
            refHy: "Սաղմոսներ 139:7-10",
            refRu: "Псалом 138:7-10",
            refEn: "Psalm 139:7-10"
        ),
        BibleVerse(
            textHy: "Երանի նորան, որի օգնականը Յակոբի Աստուածն է. որ նորա յոյսն իր Եհովայ Աստուծուն վերայ է։ Որ ստեղծեց երկինքն ու երկիրը, ծովն ու նորանց մէջ ամեն եղածը. որ հաւատարմութիւն է պահում յաւիտեան. Որ իրաւունք է անում զրկուածներին. եւ հաց տալիս՝ սովածներին. Տէրը արձակում կապուածներին։ Տէրը բանում է կոյրերի աչքերը. Տէրը կանգնեցնում է ընկածներին. Տէրը սիրում է արդարներին։",
            textHyArarat: "Երանի՜ նրան, որի օգնականը Հակոբի Աստվածն է, և նրա հույսը իր Տեր Աստծու վրա է, Որ ստեղծեց երկինքն ու երկիրը, ծովը և նրանց մեջ եղած ամեն ինչ. որ հավատարմություն է պահում հավիտյան. Իրավունք է շնորհում զրկվածներին և հաց է տալիս սովածներին, Տերը արձակում է կապվածներին։ Տերը բացում է կույրերի աչքերը, Տերը կանգնեցնում է ընկածներին, Տերը սիրում է արդարներին։",
            textRu: "Блажен, кому помощник Бог Иаковлев, у кого надежда на Господа Бога его, сотворившего небо и землю, море и все, что в них, вечно хранящего верность, творящего суд обиженным, дающего хлеб алчущим. Господь разрешает узников, Господь отверзает очи слепым, Господь восставляет согбенных, Господь любит праведных.",
            textEn: "Happy is he that hath the God of Jacob for his help, whose hope is in the LORD his God: Which made heaven, and earth, the sea, and all that therein is: which keepeth truth for ever: Which executeth judgment for the oppressed: which giveth food to the hungry. The LORD looseth the prisoners: The LORD openeth the eyes of the blind: the LORD raiseth them that are bowed down: the LORD loveth the righteous.",
            refHy: "Սաղմոսներ 146:5-8",
            refRu: "Псалом 145:5-8",
            refEn: "Psalm 146:5-8"
        ),
        BibleVerse(
            textHy: "Տէրը հաւանում է իրանից վախեցողներին, որ իր ողորմութեանն են յուսացած։",
            textHyArarat: "Տերը հավանում է իրենից վախեցողներին, նրանց, որ իրենց հույսը դրել են իր ողորմության վրա։",
            textRu: "Благоволит Господь к боящимся Его, к уповающим на милость Его.",
            textEn: "The LORD taketh pleasure in them that fear him, in those that hope in his mercy.",
            refHy: "Սաղմոսներ 147:11",
            refRu: "Псалом 147:11",
            refEn: "Psalm 147:11"
        ),
        BibleVerse(
            textHy: "Դու քո աչքի առաջին իմաստուն մի լինիր, վախիր Տէրիցը եւ հեռացիր չարից։ Սա առողջութիւն կլինի քո մարմնի համար, եւ պարարտութիւն՝ քո ոսկորներին։",
            textHyArarat: "Դու քո աչքի առաջ իմաստուն մի՛ եղիր, վախեցի՛ր Տիրոջից և վանի՛ր չարը։ Սա քո մարմնին առողջություն և քո ոսկորներին պարարտություն պիտի լինի։",
            textRu: "Не будь мудрецом в глазах твоих; бойся Господа и удаляйся от зла: это будет здравием для тела твоего и питанием для костей твоих.",
            textEn: "Be not wise in thine own eyes: fear the LORD, and depart from evil. It shall be health to thy navel, and marrow to thy bones.",
