        BibleVerse(
            textHy: "Եւ դուք ուրախութեամբ ջուր կքաշէք փրկութեան աղբիւրներիցը։ Եւ այն օրը կասէք. Գովեցէք Տիրոջը, կանչեցէք նորա անունը, պատմեցէք ազգերի մէջ նորա գործերը. յիշեցէք որ բարձր է նորա անունը։ Օրհներգեցէք Տիրոջը, որ մեծամեծ բաներ է արել, սորանք իմացուած են բոլոր երկրումը։",
            textHyArarat: "Դուք ուրախությամբ ջուր պիտի հանեք փրկության աղբյուրներից և այն օրը կասեք. «Գովերգե՛ք Տիրոջը, կանչե՛ք նրա անունը, հռչակե՛ք նրա գործերը ժողովուրդների մեջ, հիշեցրե՛ք, որ բարձր է նրա անունը։ Օրհներգե՛ք Տիրոջը, որը մեծափառ գործեր է կատարել, դրանք թող իմացվեն համայն աշխարհում։",
            textRu: "И в радости будете почерпать воду из источников спасения, и скажете в тот день: славьте Господа, призывайте имя Его; возвещайте в народах дела Его; напоминайте, что велико имя Его; пойте Господу, ибо Он соделал великое, — да знают это по всей земле.",
            textEn: "With joy shall ye draw water out of the wells of salvation. And in that day shall ye say, Praise the LORD, call upon his name, declare his doings among the people, make mention that his name is exalted. Sing unto the LORD; for he hath done excellent things: this is known in all the earth.",
            refHy: "Եսայի 12:3-5",
            refRu: "Исаия 12:3-5",
            refEn: "Isaiah 12:3-5"
        ),
        BibleVerse(
            textHy: "Եւ արդարութեան գործը կլինի խաղաղութիւն, եւ արդարութեան արդիւնքը հանգիստ ու ապահովութիւն յաւիտեան։",
            textHyArarat: "Արդարության պտուղը խաղաղություն կլինի, և արդարության արդյունքը՝ հավիտենական անդորր ու վստահություն։",
            textRu: "И делом правды будет мир, и плодом правосудия — спокойствие и безопасность вовеки.",
            textEn: "And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever.",
            refHy: "Եսայի 32:17",
            refRu: "Исаия 32:17",
            refEn: "Isaiah 32:17"
        ),
        BibleVerse(
            textHy: "Ուժովացրէք թուլացած ձեռքերը, եւ դողդոջուն ծունկերը զօրացրէք։ Ասեցէք թուլասիրտներին, ուժովացէք, մի վախենաք, ահա ձեր Աստուածը գալիս է վրէժ առնելու, Աստուծոյ հատուցումով է գալիս նա եւ նա ձեզ փրկելու է։",
            textHyArarat: "Զորացրե՛ք թուլացած ձեռքերը, պնդացրե՛ք դողդոջուն ծնկները։ Ասացե՛ք թուլասիրտներին. «Ո՛ւժ առեք, մի՛ վախեցեք. ահա ձեր Աստվածը գալիս է վրեժխնդրությամբ, Աստծու հատուցումով. գալիս է և կազատի ձեզ»։",
            textRu: "Укрепите ослабевшие руки и утвердите колени дрожащие; скажите робким душею: будьте тверды, не бойтесь; вот Бог ваш, придет отмщение, воздаяние Божие; Он придет и спасет вас.",
            textEn: "Strengthen ye the weak hands, and confirm the feeble knees. Say to them that are of a fearful heart, Be strong, fear not: behold, your God will come with vengeance, even God with a recompence; he will come and save you.",
            refHy: "Եսայի 35:3-4",
            refRu: "Исаия 35:3-4",
            refEn: "Isaiah 35:3-4"
        ),
        BibleVerse(
            textHy: "Ջուր պիտի թափեմ ծարաւի վերայ, եւ հեղեղներ՝ չորութեան վերայ, ես պիտի թափեմ իմ հոգին քո սերունդի վերայ, եւ իմ օրհնութիւնը՝ քո զաւակների վերայ։",
            textHyArarat: "որովհետև ջուր պիտի թափեմ ծարաված հողի վրա և հեղեղներ՝ չորացած երկրի վրա. ես իմ հոգին պիտի թափեմ քո սերունդների վրա և իմ օրհնությունը՝ քո երանքից ծնվածների վրա։",
            textRu: "Я изолью воды на жаждущее и потоки на иссохшее; излию дух Мой на племя твое и благословение Мое на потомков твоих.",
            textEn: "I will pour water upon him that is thirsty, and floods upon the dry ground: I will pour my spirit upon thy seed, and my blessing upon thine offspring.",
            refHy: "Եսայի 44:3",
            refRu: "Исаия 44:3",
            refEn: "Isaiah 44:3"
        ),
        BibleVerse(
            textHy: "Եւ մինչեւ ծերանալն էլ ես եմ, եւ մինչեւ ալեւորութիւնը պիտի կրեմ ձեզ, ես ստեղծեցի եւ ես պիտի կրեմ, եւ ես պիտի վեր առնեմ եւ ազատեմ։",
            textHyArarat: "Մինչև ձեր ծերությունն էլ ես եմ նա, մինչև ալևորություն կկրեմ ձեզ. ե՛ս ստեղծեցի, ե՛ս կկրեմ և կազատագրեմ ձեզ ։",
            textRu: "И до старости вашей Я тот же буду, и до седины вашей Я же буду носить вас; Я создал и буду носить, поддерживать и охранять вас.",
            textEn: "And even to your old age I am he; and even to hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver you.",
            refHy: "Եսայի 46:4",
            refRu: "Исаия 46:4",
            refEn: "Isaiah 46:4"
        ),
        BibleVerse(
            textHy: "Ցնծացէք, ով երկինք, եւ բերկրացիր, ով երկիր, եւ ուրախութեան ձայնով աղաղակեցէք, ով սարեր, որովհետեւ Տէրը մխիթարել է իր ժողովրդին, եւ ողորմել է նորա տնանկներին։",
            textHyArarat: "Ցնծա՛, ո՛վ երկինք, ուրախացի՛ր, ո՛վ երկիր, և ցնծությամբ պոռթկացե՛ք, ո՛վ լեռներ, որովհետև Տերը մխիթարել է իր ժողովրդին և գթացել է նրա թշվառներին»։",
            textRu: "Радуйтесь, небеса, и веселись, земля, и восклицайте, горы, от радости; ибо утешил Господь народ Свой и помиловал страдальцев Своих.",
            textEn: "Sing, O heavens; and be joyful, O earth; and break forth into singing, O mountains: for the LORD hath comforted his people, and will have mercy upon his afflicted.",
            refHy: "Եսայի 49:13",
            refRu: "Исаия 49:13",
            refEn: "Isaiah 49:13"
        ),
        BibleVerse(
            textHy: "Եւ Տիրոջ փրկուածները ետ պիտի դառնան, եւ գան Սիօն ցնծալի երգերով, եւ յաւիտենական ուրախութիւն պիտի լինի նորանց գլխին, ցնծութեան եւ ուրախութեան պիտի հասնեն. պիտի փախչեն տրտմութիւնը եւ հեծութիւնը։",
            textHyArarat: "Տիրոջ կողմից փրկագնվածները կվերադառնան, ցնծալի երգերով կգան Սիոն, և հավիտենական ուրախություն կլինի նրանց գլխի վրա. նրանք ցնծություն և ուրախություն կստանան, և տրտմությունն ու հեծությունը կփախչեն։",
            textRu: "И возвратятся избавленные Господом и придут на Сион с пением, и радость вечная над головою их; они найдут радость и веселье: печаль и вздохи удалятся.",
            textEn: "The redeemed of the LORD shall return, and come with singing unto Zion; and everlasting joy shall be upon their head: they shall obtain gladness and joy; and sorrow and mourning shall flee away.",
            refHy: "Եսայի 51:11",
            refRu: "Исаия 51:11",
            refEn: "Isaiah 51:11"
        ),
        BibleVerse(
            textHy: "Ի՜նչ գեղեցիկ ես սարերի վերայ աւետարանչի ոտքերը, որ խաղաղութիւն է քարոզում, բարիք աւետում, փրկութիւն քարոզում, որ ասում է Սիօնին՝ քո Աստուածը թագաւոր է։",
            textHyArarat: "Ի՜նչ գեղեցիկ են լեռների վրա ավետաբերի ոտքերը, որ խաղաղություն է հռչակում, բարիք ավետում, փրկություն քարոզում, որ ասում է Սիոնին. «Քո Աստվածը թագավորում է»։",
            textRu: "Как прекрасны на горах ноги благовестника, возвещающего мир, благовествующего радость, проповедующего спасение, говорящего Сиону: «воцарился Бог твой!»",
            textEn: "How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace; that bringeth good tidings of good, that publisheth salvation; that saith unto Zion, Thy God reigneth!",
            refHy: "Եսայի 52:7",
            refRu: "Исаия 52:7",
            refEn: "Isaiah 52:7"
        ),
        BibleVerse(
            textHy: "Այսպէս է ասում բարձրը եւ Բարձրեալը, յաւիտենականութեան մէջ բնակողը, եւ որի անունը Սուրբ է. Ես բնակվում եմ բարձրումը եւ սուրբ տեղը, բայց լինում եմ կոտրած եւ խոնարհ հոգի ունեցողի հետ, որ խոնարհների հոգին կենդանացնեմ, եւ կենդանացնեմ սրտով կոտրուածներին։",
            textHyArarat: "Եվ արդ, այսպես է ասում Բարձրը, Բարձրյալը, հավիտենության մեջ բնակվողը, որի անունը Սուրբ է. «Ես բնակվում եմ բարձունքում և սուրբ տեղում, բայց բեկված և խոնարհ հոգի ունեցող մարդու հետ եմ լինում, որպեսզի վերակենդանացնեմ խոնարհների հոգին, վերակենդանացնեմ բեկվածների սիրտը։",
            textRu: "Так говорит Высокий и Превознесенный, вечно Живущий, — Святый имя Его: Я живу на высоте небес и во святилище, и также с сокрушенными и смиренными духом, чтобы оживлять дух смиренных и оживлять сердца сокрушенных.",
            textEn: "Thus saith the high and lofty One that inhabiteth eternity, whose name is Holy; I dwell in the high and holy place, with him also that is of a contrite and humble spirit, to revive the spirit of the humble, and to revive the heart of the contrite ones.",
            refHy: "Եսայի 57:15",
            refRu: "Исаия 57:15",
            refEn: "Isaiah 57:15"
        ),
        BibleVerse(
            textHy: "Ես ուրախութեամբ պիտի ուրախանամ Տէրովը, իմ անձը պիտի խնդայ իմ Աստուծովը. որովհետեւ նա ինձ փրկութեան հանդերձներ հագցրեց, արդարութեան պատմուճանը գցեց ինձ վերայ. ինչպէս մի փեսայ, որ դնում է իր խոյրը, եւ մի հարսի պէս՝ որ զարդարվում է իր զարդերովը։",
            textHyArarat: "Ես մեծապես պիտի ուրախանամ Տիրոջով, իմ անձը պիտի ցնծա իմ Աստծով, որովհետև նա փրկության զգեստներ հագցրեց ինձ, արդարության պատմուճանով ծածկեց ինձ. ինչպես փեսան է քահանայի նման խույրով զարդարվում, և ինչպես հարսը, որ պճնվում է իր զարդերով։",
            textRu: "Радостью буду радоваться о Господе, возвеселится душа моя о Боге моем; ибо Он облек меня в ризы спасения, одеждою правды одел меня, как на жениха возложил венец и, как невесту, украсил убранством.",
            textEn: "I will greatly rejoice in the LORD, my soul shall be joyful in my God; for he hath clothed me with the garments of salvation, he hath covered me with the robe of righteousness, as a bridegroom decketh himself with ornaments, and as a bride adorneth herself with her jewels.",
            refHy: "Եսայի 61:10",
            refRu: "Исаия 61:10",
            refEn: "Isaiah 61:10"
        ),
        BibleVerse(
            textHy: "Եւ պիտի լինի, որ նորանք դեռ չկանչած՝ ես կպատասխանեմ եւ նորանք դեռ խօսելիս՝ ես կլսեմ։",
            textHyArarat: "Այնպես պիտի լինի, որ նրանք դեռ չկանչած՝ պիտի պատասխանեմ, և նրանք խոսելուց դեռ չդադարած՝ պիտի լսեմ։",
            textRu: "И будет, прежде нежели они воззовут, Я отвечу; они еще будут говорить, и Я уже услышу.",
            textEn: "And it shall come to pass, that before they call, I will answer; and while they are yet speaking, I will hear.",
            refHy: "Եսայի 65:24",
            refRu: "Исаия 65:24",
            refEn: "Isaiah 65:24"
        ),
        BibleVerse(
            textHy: "Ես պիտի զովացնեմ վաստակած հոգին, եւ ամեն նուաղած հոգին պիտի կշտացնեմ։",
            textHyArarat: "Ես պիտի հագեցնեմ հոգնաբեկ հոգին և պիտի գոհացնեմ յուրաքանչյուր նվաղած հոգին»։",
            textRu: "Я напою душу утомленную и насыщу всякую душу скорбящую.",
            textEn: "I have satiated the weary soul, and I have replenished every sorrowful soul.",
            refHy: "Երեմիա 31:25",
            refRu: "Иеремия 31:25",
            refEn: "Jeremiah 31:25"
        ),
        BibleVerse(
            textHy: "Եւ ես ձեզ նոր սիրտ պիտի տամ, եւ նոր հոգի պիտի դնեմ ձեր միջումը, եւ վեր պիտի առնեմ ձեր մարմնիցը քարեղէն սիրտը եւ ձեզ մարմնեղէն սիրտ պիտի տամ։",
            textHyArarat: "Ապա ձեզ նոր սիրտ պիտի տամ և նոր հոգի պիտի դնեմ ձեր մեջ, ձեր մարմնից պիտի վերցնեմ քարե սիրտը ու ձեզ մարմնեղեն սիրտ տամ։",
            textRu: "И дам вам сердце новое, и дух новый дам вам; и возьму из плоти вашей сердце каменное, и дам вам сердце плотяное.",
            textEn: "A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.",
            refHy: "Եզեկիել 36:26",
