        BibleVerse(
            textHy: "Եւ պատառեցէք ձեր սրտերը, ու չէ թէ ձեր հանդերձները, եւ ետ դարձէք դէպի ձեր Տէր Աստուածը, ըստ որում ողորմած եւ գթած է, երկայնամիտ եւ բազումողորմ եւ զղջացող չարիքի համար։",
            textHyArarat: "Եվ պատռե՛ք ձեր սրտերը և ոչ թե ձեր հանդերձները»։ Եվ ե՛տ դարձեք դեպի Տերը՝ ձեր Աստվածը, քանզի ողորմած ու գթառատ է, երկայնամիտ է ու բազումողորմ և պատրաստակամ ներելու։",
            textRu: "Раздирайте сердца ваши, а не одежды ваши, и обратитесь к Господу Богу вашему; ибо Он благ и милосерд, долготерпелив и многомилостив и сожалеет о бедствии.",
            textEn: "And rend your heart, and not your garments, and turn unto the LORD your God: for he is gracious and merciful, slow to anger, and of great kindness, and repenteth him of the evil.",
            refHy: "Հովել 2:13",
            refRu: "Иоиль 2:13",
            refEn: "Joel 2:13"
