        BibleVerse(
            textHy: "Տեսիլքը տակաւին որոշուած ժամանակի համար է, եւ շտապում է վախճանին, եւ չի ստիլ. եթէ ուշանայ էլ, սպասիր նորան, որովհետեւ անպատճառ պիտի գայ եւ ետ չի մնալ։",
            textHyArarat: "Տեսիլքը դեռևս որոշված ժամանակի համար է և հևում է դեպի վախճանը. չի ստում, եթե նույնիսկ հապաղի. սպասի՛ր նրան, որովհետև անպատճառ պիտի գա և չի ուշանա։",
            textRu: "Видение относится еще к определенному времени и говорит о конце и не обманет; и хотя бы и замедлило, жди его, ибо непременно сбудется, не отменится.",
            textEn: "The vision is yet for an appointed time, but at the end it shall speak, and not lie: though it tarry, wait for it; because it will surely come, it will not tarry.",
            refHy: "Ամբակում 2:3",
            refRu: "Аввакум 2:3",
            refEn: "Habakkuk 2:3"
        ),
        BibleVerse(
            textHy: "Երկիրը պիտի լցուի Տիրոջ փառքի գիտութեամբը, ինչպէս որ ջրերը ծածկում են ծովը։",
            textHyArarat: "Երկիրը պիտի լցվի Տիրոջ փառքի գիտությամբ, ինչպես որ ջրերն են ծածկում ծովը։",
            textRu: "Земля наполнится познанием славы Господа, как воды наполняют море.",
            textEn: "The earth shall be filled with the knowledge of the glory of the LORD, as the waters cover the sea.",
            refHy: "Ամբակում 2:14",
            refRu: "Аввакум 2:14",
            refEn: "Habakkuk 2:14"
        ),
        BibleVerse(
            textHy: "Եթէ դուք մարդկանց իրանց յանցանքները թողէք, ձեր երկնաւոր Հայրն էլ ձեզ կթողէ։ Իսկ եթէ դուք մարդկանց չէք թողիլ նորանց յանցանքները, ձեր Հայրն էլ չի թողիլ ձեր յանցանքները։",
            textHyArarat: "Եթե դուք մարդկանց ներեք իրենց հանցանքները, ձեր երկնավոր Հայրն էլ ձեզ կների։ Իսկ եթե դուք մարդկանց չներեք իրենց հանցանքները, ձեր Հայրն էլ ձեզ չի ների ձեր հանցանքները։",
            textRu: "Если вы будете прощать людям согрешения их, то простит и вам Отец ваш Небесный, а если не будете прощать людям согрешения их, то и Отец ваш не простит вам согрешений ваших.",
            textEn: "If ye forgive men their trespasses, your heavenly Father will also forgive you: But if ye forgive not men their trespasses, neither will your Father forgive your trespasses.",
            refHy: "Մատթեոս 6:14-15",
            refRu: "Матфея 6:14-15",
            refEn: "Matthew 6:14-15"
        ),
        BibleVerse(
            textHy: "Հոգս մի անէք ասելով, թէ՝ Ի՛նչ պիտի ուտենք, կամ ի՛նչ պիտի խմենք, կամ ի՛նչ պիտի հագնենք։ Որովհետեւ այդ ամենքը հեթանոսներն են խնդրում. որովհետեւ ձեր երկնաւոր Հայրը գիտէ որ այդ ամենը պէտք է ձեզ։",
            textHyArarat: "Մի՛ մտահոգվեք ասելով՝ ի՛նչ ենք ուտելու կամ ի՛նչ ենք խմելու կամ ի՛նչ ենք հագնելու, որովհետև այդ ամենը հեթանոսներն են փնտրում. որովհետև ձեր երկնավոր Հայրը գիտի, որ դուք այդ ամենի կարիքն ունեք։",
            textRu: "Не заботьтесь и не говорите: что нам есть? или что пить? или во что одеться? потому что всего этого ищут язычники, и потому что Отец ваш Небесный знает, что вы имеете нужду во всем этом.",
            textEn: "Take no thought, saying, What shall we eat? or, What shall we drink? or, Wherewithal shall we be clothed? (For after all these things do the Gentiles seek:) for your heavenly Father knoweth that ye have need of all these things.",
            refHy: "Մատթեոս 6:31-32",
            refRu: "Матфея 6:31-32",
            refEn: "Matthew 6:31-32"
