        BibleVerse(
            textHy: "Էգուցուայ համար հոգս մի՛ անէք, որովհետեւ էգուցուայ օրն իր համար հոգս կանէ. օրուայ համար բաւական է իր նեղութիւնը։",
            textHyArarat: "Արդ, վաղվա մասին մի՛ հոգացեք, որովհետև վաղվա օրն ունի իր հոգսերը. յուրաքանչյուր օրվա հոգսերն ինքնին բավական են»։",
            textRu: "Не заботьтесь о завтрашнем дне, ибо завтрашний сам будет заботиться о своем: довольно для каждого дня своей заботы.",
            textEn: "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.",
            refHy: "Մատթեոս 6:34",
            refRu: "Матфея 6:34",
            refEn: "Matthew 6:34"
        ),
        BibleVerse(
            textHy: "Մի դատէք, որ չդատուիք։ Որովհետեւ ինչ դատաստանով որ դատում էք, նորանով պիտի դատուիք. եւ ինչ չափով որ չափում էք, նորանով կչափուի ձեզ։",
            textHyArarat: "«Մի՛ դատեք, որ չդատվեք. որովհետև ինչ դատաստանով որ դատեք, նրանով պիտի դատվեք, և ինչ չափով որ չափեք, նրանով էլ ձեզ կչափվի։",
            textRu: "Не судите, да не судимы будете, ибо каким судом судите, таким будете судимы; и какою мерою мерите, такою и вам будут мерить.",
            textEn: "Judge not, that ye be not judged. For with what judgment ye judge, ye shall be judged: and with what measure ye mete, it shall be measured to you again.",
            refHy: "Մատթեոս 7:1-2",
            refRu: "Матфея 7:1-2",
            refEn: "Matthew 7:1-2"
        ),
        BibleVerse(
            textHy: "Նեղ դռնովը ներս մտէք. որովհետեւ լայն է դուռը եւ ընդարձակ ճանապարհը՝ որ կորուստն է տանում. եւ շատեր են նորանով գնացողները։ Քանի՜ նեղ է դուռը՝ եւ նեղուածք է ճանապարհը, որ տանում է կեանքը. եւ քիչ են նորան գտնողները։",
            textHyArarat: "Նեղ դռնո՛վ ներս մտեք, որովհետև լայն է այն դուռը, և ընդարձակ՝ այն ճանապարհը, որ դեպի կործանում է տանում, և դրանով մտնողները շատ են։ Որքա՜ն նեղ է այն դուռը, և դժվարանցանելի՝ ճանապարհը, որ դեպի կյանք է տանում. քիչ են այն գտնողները։",
            textRu: "Входите тесными вратами, потому что широки врата и пространен путь, ведущие в погибель, и многие идут ими; потому что тесны врата и узок путь, ведущие в жизнь, и немногие находят их.",
            textEn: "Enter ye in at the strait gate: for wide is the gate, and broad is the way, that leadeth to destruction, and many there be which go in thereat: Because strait is the gate, and narrow is the way, which leadeth unto life, and few there be that find it.",
            refHy: "Մատթեոս 7:13-14",
