        BibleVerse(
            textHy: "Չէ՞ որ երկու ճնճղուկ մէկ դանգի են ծախվում, եւ նորանցից մէկը չի ընկնիլ գետինն առանց ձեր Հօր։ Իսկ ձեր գլխի ամեն մազերն էլ համարուած են։ Ուրեմն մի վախենաք. դուք շատ ճնճղուկներից աւելի լաւ էք։",
            textHyArarat: "Երկու ճնճղուկը մեկ լումայով չե՞ն վաճառվում, բայց նրանցից ոչ մեկն առանց ձեր Հոր գիտության գետնին չի ընկնում։ Ձեր գլխի ամեն մի մազն էլ հաշվված է։ Արդ, մի՛ վախեցեք. դուք բազում ճնճղուկներից ավելին եք։",
            textRu: "Не две ли малые птицы продаются за ассарий? И ни одна из них не упадет на землю без воли Отца вашего; у вас же и волосы на голове все сочтены; не бойтесь же: вы лучше многих малых птиц.",
            textEn: "Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.",
            refHy: "Մատթեոս 10:29-31",
            refRu: "Матфея 10:29-31",
            refEn: "Matthew 10:29-31"
        ),
        BibleVerse(
            textHy: "Այնպէս չլինի ձեր մէջ, այլ ձեզանից ով որ կամենայ մեծ լինել, թող ձեզ ծառայ լինի։ Եւ ձեզանից ով որ կամենայ առաջին լինել, թող ձեզ ծառայ լինի։ Ինչպես մարդի Որդին չեկաւ որ իրան ծառայեն, այլ որ ինքը ծառայէ, եւ շատերի փոխանակ իր անձը փրկանք տայ։",
            textHyArarat: "Ձեր մեջ այդպես չպետք է լինի, այլ ձեզանից ով ցանկանա մեծ լինել, ձեր ծառան պետք է լինի, և ձեզանից ով ցանկանա առաջինը լինել, ձեր ծառան պետք է լինի, ինչպես որ Մարդու Որդին չեկավ, որ իրեն ծառայեն, այլ որպեսզի ինքը ծառայի և շատերի փոխարեն իր կյանքը որպես փրկագին տա»։",
            textRu: "Между вами да не будет так: а кто хочет между вами быть большим, да будет вам слугою; и кто хочет между вами быть первым, да будет вам рабом; так как Сын Человеческий не для того пришел, чтобы Ему служили, но чтобы послужить и отдать душу Свою для искупления многих.",
            textEn: "It shall not be so among you: but whosoever will be great among you, let him be your minister; And whosoever will be chief among you, let him be your servant: Even as the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.",
            refHy: "Մատթեոս 20:26-28",
            refRu: "Матфея 20:26-28",
            refEn: "Matthew 20:26-28"
        ),
        BibleVerse(
            textHy: "Եւ ամեն ինչ որ աղօթքի մէջ խնդրէք հաւատալով, կառնէք։",
            textHyArarat: "Եվ այն ամենը, ինչ աղոթքի մեջ հավատքով խնդրեք, կստանաք»։",
            textRu: "И всё, чего ни попросите в молитве с верою, получите.",
            textEn: "And all things, whatsoever ye shall ask in prayer, believing, ye shall receive.",
            refHy: "Մատթեոս 21:22",
            refRu: "Матфея 21:22",
            refEn: "Matthew 21:22"
        ),
        BibleVerse(
            textHy: "Մարդի Որդին էլ չ’եկաւ, որ իրան ծառայեն, այլ նա ծառայէ, եւ իր անձը փրկանք տայ շատերի տեղ;",
            textHyArarat: "Մարդու Որդին նույնպես չեկավ, որ իրեն ծառայեն, այլ որ ինքը ծառայի ու շատերի համար իր կյանքը որպես փրկագին տա»։",
            textRu: "И Сын Человеческий не для того пришел, чтобы Ему служили, но чтобы послужить и отдать душу Свою для искупления многих.",
            textEn: "Even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.",
            refHy: "Մարկոս 10:45",
            refRu: "Марка 10:45",
            refEn: "Mark 10:45"
        ),
        BibleVerse(
            textHy: "Եւ նորանց ասեց. Գնացէք բոլոր աշխարհք, աւետարանը քարոզեցէք ամեն արարածի։",
            textHyArarat: "Ապա նրանց ասաց. «Գնացե՛ք ամբողջ աշխարհով մեկ և բոլոր արարածներին Ավետարա՛նը քարոզեք։",
            textRu: "И сказал им: идите по всему миру и проповедуйте Евангелие всей твари.",
            textEn: "And he said unto them, Go ye into all the world, and preach the gospel to every creature.",
            refHy: "Մարկոս 16:15",
            refRu: "Марка 16:15",
            refEn: "Mark 16:15"
        ),
        BibleVerse(
            textHy: "Եւ հրեշտակն ասեց նորանց. Մի վախենաք, որովհետեւ ահա մեծ ուրախութիւն եմ աւետում ձեզ, որ բոլոր ժողովրդին պիտի լինի. Թէ այսօր ձեզ Փրկիչ ծնուեցաւ Դաւիթի քաղաքումը. որ է Քրիստոս Տէրը։ Եւ այս լինի ձեզ նշան. մի երեխայ կ’գտնէք խանձարուրներով պատած, եւ մսուրի մէջ դրած։",
            textHyArarat: "Եվ հրեշտակը նրանց ասաց. «Մի՛ վախեցեք, որովհետև ահա ձեզ մեծ ուրախություն եմ ավետում, որ ամբողջ ժողովրդինն է լինելու. այսօր Դավթի քաղաքում ձեզ համար Փրկիչ ծնվեց, որ է Օծյալ Տերը։ Սա ձեզ համար նշան կլինի. մի երեխա կգտնեք խանձարուրով փաթաթված ու մսուրի մեջ դրված»։",
            textRu: "И сказал им Ангел: не бойтесь; я возвещаю вам великую радость, которая будет всем людям: ибо ныне родился вам в городе Давидовом Спаситель, Который есть Христос Господь; и вот вам знак: вы найдете Младенца в пеленах, лежащего в яслях.",
            textEn: "And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. For unto you is born this day in the city of David a Saviour, which is Christ the Lord. And this shall be a sign unto you; Ye shall find the babe wrapped in swaddling clothes, lying in a manger.",
            refHy: "Ղուկաս 2:10-12",
            refRu: "Луки 2:10-12",
            refEn: "Luke 2:10-12"
        ),
        BibleVerse(
            textHy: "Փառք Աստուծոյ բարձունքումը, եւ երկրի վերայ՝ խաղաղութիւն, եւ մարդկանց մէջ հաճութիւն։",
            textHyArarat: "«Փա՜ռք Բարձրյալ Աստծուն, երկրի վրա՝ խաղաղություն, ու մարդկանց մեջ՝ հաճություն»։",
            textRu: "Слава в вышних Богу, и на земле мир, в человеках благоволение!",
