        BibleVerse(
            textHy: "Սիրեցէք ձեր թշնամիներին, եւ բարի արէք եւ փոխ տուէք ոչինչ ակնկալելով. եւ ձեր վարձքը շատ կ’լինի, եւ Բարձրեալի որդիք կ’լինիք. որովհետեւ նա քաղցր է երախտամոռների եւ չարերի վերայ։",
            textHyArarat: "Դուք սիրե՛ք ձեր թշնամիներին, բարի՛ք գործեք և ոչինչ չակնկալելո՛վ փոխ տվեք, ու ձեր վարձը շատ կլինի, և դուք Բարձրյալի որդիները կլինեք, որովհետև նա գթառատ է ապերախտների ու չարերի հանդեպ։",
            textRu: "Вы любите врагов ваших, и благотворите, и взаймы давайте, не ожидая ничего; и будет вам награда великая, и будете сынами Всевышнего; ибо Он благ и к неблагодарным и злым.",
