        BibleVerse(
            textHy: "Եւ մի դատէք, եւ չէք դատուիլ. մի դատապարտէք, եւ չէք դատապարտուիլ. արձակեցէք՝ եւ կ’արձակուիք։ Տուէք եւ կ’տրուի ձեզ. լաւ չափով՝ թափ տրուած շարժուած լիփ լիքը կ’տան ձեր գոգը. որովհետեւ այն չափովը որ չափէք, նորանով կ’չափուի ձեզ։",
            textHyArarat: "Եվ մի՛ դատեք ու չեք դատվի, մի՛ պատժեք ու չեք պատժվի, ներե՛ք և ներված կլինեք։ Տվե՛ք, և կտրվի ձեզ. ձեր գոգը կլցվի լա՛վ չափով՝ լեփ-լեցուն, առատ, որովհետև ինչ չափով որ չափեք, նույնով էլ ձեզ կչափվի»։",
            textRu: "Не судите, и не будете судимы; не осуждайте, и не будете осуждены; прощайте, и прощены будете; давайте, и дастся вам: мерою доброю, утрясенною, нагнетенною и переполненною отсыплют вам в лоно ваше; ибо, какою мерою мерите, такою же отмерится и вам.",
            textEn: "Judge not, and ye shall not be judged: condemn not, and ye shall not be condemned: forgive, and ye shall be forgiven: Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again.",
            refHy: "Ղուկաս 6:37-38",
            refRu: "Луки 6:37-38",
            refEn: "Luke 6:37-38"
