        BibleVerse(
            textHy: "Մի վախենար, փոքր հօտ. որովհետեւ ձեր Հայրը հաճեցաւ, որ արքայութիւնը տայ ձեզ։",
            textHyArarat: "Մի՛ վախեցիր, փոքրի՛կ հոտ, որովհետև ձեր Հայրը հաճեց տալ ձեզ արքայությունը։",
            textRu: "Не бойся, малое стадо! ибо Отец ваш благоволил дать вам Царство.",
