        BibleVerse(
            textHy: "Ամեն ով որ իր անձը բարձրացնում է՝ կ’խոնարհուի. եւ ով որ իր անձը խոնարհեցնում է, կ’բարձրանայ։",
            textHyArarat: "Ամեն ոք, ով իր անձը բարձրացնում է, կխոնարհեցվի, իսկ ով իր անձը խոնարհեցնում է, կբարձրացվի»։",
            textRu: "Всякий возвышающий сам себя унижен будет, а унижающий себя возвысится.",
