        BibleVerse(
            textHy: "Ասում եմ ձեզ, այսպէս էլ Աստուծոյ հրեշտակների առաջին ուրախութիւն կ’լինի մէկ մեղաւորի համար որ կ’ապաշխարէ։",
            textHyArarat: "Ասում եմ ձեզ. այդպես էլ Աստծու հրեշտակների մոտ ուրախություն կլինի մեկ ապաշխարած մեղավորի համար»։",
            textRu: "Так, говорю вам, бывает радость у Ангелов Божиих и об одном грешнике кающемся.",
