        BibleVerse(
            textHy: "Քիչ բանի մէջ հաւատարիմը, շատ բանի մէջ էլ հաւատարիմ է. եւ քիչ բանի մէջ անիրաւը, շատ բանի մէջ էլ անիրաւ է։",
            textHyArarat: "Քիչ բանի մեջ հավատարիմը շատի մեջ էլ է հավատարիմ, և քիչ բանի մեջ անիրավը շատի մեջ էլ է անիրավ։",
            textRu: "Верный в малом и во многом верен, а неверный в малом неверен и во многом.",
