        BibleVerse(
            textHy: "Երկինքը եւ երկիրս կ’անցնեն, բայց իմ խօսքերը չեն անցնիլ։",
            textHyArarat: "Երկինքն ու երկիրը կանցնեն, բայց իմ խոսքերը չեն անցնի։",
