        BibleVerse(
            textHy: "Որոնք որ նորան ընդունեցին, իշխանութիւն տուաւ նորանց Աստուծոյ որդիներ լինելու՝ նորանց, որ նորա անունին հաւատում են։ Որոնք ոչ արիւնից եւ ոչ մարմնի կամքից, եւ ոչ մարդի կամքից, այլ Աստուածանից ծնուեցան։",
            textHyArarat: "Սակայն նրանց, ովքեր ընդունեցին նրան և հավատացին նրա անվանը, իշխանություն տվեց Աստծու որդիները լինելու։ Նրանք չծնվեցին արյունից, ո՛չ էլ մարմնի ու մարդու կամքից, այլ ծնվեցին Աստծուց։",
            textRu: "Тем, которые приняли Его, верующим во имя Его, дал власть быть чадами Божиими, которые ни от крови, ни от хотения плоти, ни от хотения мужа, но от Бога родились.",
