        BibleVerse(
            textHy: "Եւ նորա լիութիւնիցը մենք ամենքս առանք շնորհք շնորհքի տեղ։ Որովհետեւ օրէնքը Մովսէսի ձեռովը տրուեցաւ. շնորհքը եւ ճշմարտութիւնը Յիսուս Քրիստոսի ձեռովն եղաւ։",
            textHyArarat: "Եվ նրա լիությունից մենք բոլորս շնորհի վրա շնորհը ստացանք. որովհետև օրենքը Մովսեսի միջոցով տրվեց, իսկ շնորհն ու ճշմարտությունը Հիսուս Քրիստոսի միջոցով եղան։",
            textRu: "И от полноты Его все мы приняли и благодать на благодать, ибо закон дан чрез Моисея; благодать же и истина произошли чрез Иисуса Христа.",
            textEn: "And of his fulness have all we received, and grace for grace. For the law was given by Moses, but grace and truth came by Jesus Christ.",
