        BibleVerse(
            textHy: "Այլ այն ջուրը, որ ես կտամ նորան, ջրի աղբիւր կլինի նորանում, որ յաւիտենական կեանքի համար կբղխէ։",
            textHyArarat: "Այն ջուրը, որ ես նրան տալու եմ, նրա մեջ ջրի աղբյուր կդառնա, որ հավիտենական կյանքի համար կբխի»։",
            textRu: "Кто будет пить воду, которую Я дам ему, тот не будет жаждать вовек; но вода, которую Я дам ему, сделается в нем источником воды, текущей в жизнь вечную.",
            textEn: "Whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life.",
