        BibleVerse(
            textHy: "Ճշմարիտ ճշմարիտ ասում եմ ձեզ. թէ իմ խօսքը լսողը, եւ ինձ ուղարկողին հաւատացողը, յաւիտենական կեանք ունի. եւ դատաստան չի մտնիլ, այլ մահիցը փոխուեցաւ դէպի կեանք։",
            textHyArarat: "Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ով լսում է իմ խոսքը և հավատում է ինձ ուղարկողին, հավիտենական կյանք ունի և չի դատապարտվի, այլ մահից դեպի կյանք է անցել։",
            textRu: "Истинно, истинно говорю вам: слушающий слово Мое и верующий в Пославшего Меня имеет жизнь вечную, и на суд не приходит, но перешел от смерти в жизнь.",
