            textHyArarat: "Քանի դեռ ցերեկ է, ես պետք է կատարեմ ինձ ուղարկողի գործերը։ Գիշերը գալիս է, և այն ժամանակ ոչ ոք չի կարող գործել։ Քանի դեռ աշխարհում եմ, լույսն եմ աշխարհի»։",
            textRu: "Мне должно делать дела Пославшего Меня, доколе есть день; приходит ночь, когда никто не может делать. Доколе Я в мире, Я свет миру.",
