            textHyArarat: "Ես եմ բարի հովիվը, և ես ճանաչում եմ իմ ոչխարներին, ու նրանք էլ ճանաչում են ինձ։ Ինչպես Հայրն է ինձ ճանաչում, ես էլ ճանաչում եմ Հորը և իմ կյանքը տալիս եմ ոչխարների համար։",
            textRu: "Я есмь пастырь добрый; и знаю Моих, и Мои знают Меня. Как Отец знает Меня, так и Я знаю Отца; и жизнь Мою полагаю за овец.",
