            textHyArarat: "Եթե ես՝ Տերս ու Վարդապետս, լվացի ձեր ոտքերը, դուք նույնպես պարտավոր եք միմյանց ոտքերը լվանալ։ Քանի որ ես ձեզ օրինակ ծառայեցի, որպեսզի ինչպես ես ձեզ արեցի, դուք էլ նույն կերպ անեք։",
