            textHyArarat: "Եթե ինձ հետ միավորված մնաք, իմ խոսքերն էլ ձեր մեջ մնան, ինչ որ կամենաք, խնդրեք, այն ձեզ կտրվի։ Իմ Հայրն այն դեպքում կփառավորվի, երբ դուք շատ պտուղ տաք և իմ աշակերտները լինեք։",
