            textHy: "Սորանք գրուեցան՝ որ հաւատաք, թէ Յիսուսն է Քրիստոսը՝ Աստուծոյ Որդին. եւ որ հաւատալով կեանք ունենաք նորա անունովը։",
            textHyArarat: "Սրանք գրվեցին, որպեսզի հավատաք, որ Հիսուսն է Քրիստոսը՝ Աստծու Որդին, և որպեսզի հավատաք ու նրա անունով հավիտենական կյանք ունենաք։",
