        BibleVerse(
            textHy: "Դուք ծառայութեան հոգին չ’առաք որ դարձեալ վախենաք. այլ որդեգրութեան հոգին առաք, որով աղաղակում ենք՝ Աբբա, Հայր։ Նոյն ինքն Հոգին վկայութիւն է տալիս մեր հոգուն հետ, որ մենք Աստուծոյ որդիք ենք։",
            textHyArarat: "Դուք ծառայությա՛ն հոգին չստացաք, որ դարձյալ վախենաք, այլ որդեգրությա՛ն հոգին ստացաք, որով աղաղակում ենք. «Աբբա՛, Հա՛յր»։ Նույն ինքը Հոգին վկայում է մեր հոգուն, որ մենք Աստծու որդիներ ենք։",
            textRu: "Вы не приняли духа рабства, чтобы опять жить в страхе, но приняли Духа усыновления, Которым взываем: «Авва, Отче!» Сей самый Дух свидетельствует духу нашему, что мы — дети Божии.",
