        BibleVerse(
            textHy: "Ո՜վ Աստուծոյ մեծութեան եւ իմաստութեան եւ գիտութեան խորութիւնը. ինչպէ՜ս անքննելի են նորա դատաստանները, եւ անհասկանալի են նորա ճանապարհները։",
            textHyArarat: "«Ո՜վ Աստծու մեծության, իմաստության և գիտության խորություն, ինչքա՜ն անքննելի են նրա դատաստանները, և անզննելի են նրա ճանապարհները։",
            textRu: "О, бездна богатства и премудрости и ведения Божия! Как непостижимы судьбы Его и неисследимы пути Его!",
