        BibleVerse(
            textHy: "Մէկին չարի տեղ չար մի հատուցանէք. ամեն մարդկանց առաջին բարի խորհուրդ ունեցէք։ Եթէ կարելի է՝ որքան ձեզանից է կախուած՝ ամեն մարդկանց հետ խաղաղութիւն ունեցէք։",
            textHyArarat: "Որևէ մեկին չարի դիմաց չար մի՛ հատուցեք. բոլոր մարդկանց առաջ բարիք անե՛լ խորհեք։ Եթե հնարավոր է, որքան ձեզանից է կախված, բոլոր մարդկանց հետ խաղաղությա՛մբ մնացեք։",
