        BibleVerse(
            textHy: "Եթէ ապրենք՝ Տիրոջ ենք ապրում, եւ եթէ մեռնենք՝ Տիրոջ ենք մեռնում. ուրեմն թէ ապրենք եւ թէ մեռնենք՝ Տիրոջն ենք։",
            textHyArarat: "Եթե ապրում ենք, Տիրոջ համար ենք ապրում, իսկ թե մեռնում ենք, Տիրոջ համար ենք մեռնում։ Ուրեմն թե ապրենք և թե մեռնենք, Տիրոջն ենք։",
