        BibleVerse(
            textHy: "Եւ համբերութեան եւ մխիթարութեան Աստուածը տայ ձեզ միեւնոյն բանը խորհել իրար հետ Քրիստոս Յիսուսի կամքի համեմատ։ Որ միաբան մէկ բերանով փառաւորէք Աստուծուն, եւ մեր Տէր Յիսուս Քրիստոսի Հօրը։",
            textHyArarat: "Եվ համբերության ու մխիթարության Աստվածը թող շնորհի ձեզ միմյանց հետ համախոհ լինել ըստ Քրիստոս Հիսուսի, որպեսզի միաբան ու միաբերան փառավորեք Աստծուն և մեր Տեր Հիսուս Քրիստոսի Հորը։",
            textRu: "Бог же терпения и утешения да дарует вам быть в единомыслии между собою, по учению Христа Иисуса, дабы вы единодушно, едиными устами славили Бога и Отца Господа нашего Иисуса Христа.",
