        BibleVerse(
            textHy: "Վասնորոյ իրար ընդունեցէք, ինչպէս Քրիստոս էլ մեզ ընդունեց Աստուծոյ փառքի համար։",
            textHyArarat: "Դրա համար միմյանց ընդունե՛ք, ինչպես որ Քրիստոսը ձեզ ընդունեց Աստծու փառքի համար։",
