        BibleVerse(
            textHy: "Չգիտէ՞ք որ դուք Աստուծոյ տաճար էք եւ Աստուծոյ Հոգին բնակուած է ձեզանում։",
            textHyArarat: "Չգիտե՞ք, որ դուք Աստծու տաճար եք, և Աստծու Հոգին բնակվում է ձեր մեջ։",
