        BibleVerse(
            textHy: "Կամ թէ չգիտէ՞ք, որ ձեր մարմինները Սուրբ Հոգու տաճար են՝ որ ձեզանում է, որ նորան Աստուածանից ունիք. եւ ձերինը չէք։ Որովհետեւ մեծ գնով գնուեցաք. ուստի փառաւորեցէք Աստուծուն ձեր մարմնումը եւ ձեր հոգումն՝ որ Աստուծունն են։",
            textHyArarat: "Կամ չգիտե՞ք, որ ձեր մարմինները տաճար են Սուրբ Հոգու, որ ձեր մեջ է, և որն Աստծուց ունեք, և դուք ձերը չեք։ Քանզի մեծ գնով եք գնվել, ուստի փառավորե՛ք Աստծուն ձեր մարմնի մեջ։",
            textRu: "Не знаете ли, что тела ваши суть храм живущего в вас Святаго Духа, Которого имеете вы от Бога, и вы не свои? Ибо вы куплены дорогою ценою. Посему прославляйте Бога и в телах ваших и в душах ваших, которые суть Божии.",
            textEn: "What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own? For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God's.",
