        BibleVerse(
            textHy: "Ուրեմն՝ թէ ուտէք թէ խմէք, թէ ինչ գործ էլ որ անէք, ամեն բան Աստուծոյ փառքի համար արէք։",
            textHyArarat: "Ուտեք թե խմեք, ինչ գործ էլ որ անեք, ամեն բան Աստծու փառքի համա՛ր արեք։",
            textRu: "Едите ли, пьете ли, или иное что делаете, все делайте в славу Божию.",
            textEn: "Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.",
            refHy: "Ա Կորնթացիս 10:31",
            refRu: "1 Коринфянам 10:31",
            refEn: "1 Corinthians 10:31"
        ),
        BibleVerse(
            textHy: "Աստուծոյ շնորհքովն եմ ինչ որ եմ. եւ նորա շնորհքն որ ինձանում է ունայն չ’եղաւ. այլ նորանց ամենիցն աւելի աշխատեցի. սակայն ոչ թէ ես, այլ Աստուծոյ շնորհքը որ ինձ հետ է։",
            textHyArarat: "Ինչ որ եմ, Աստծու շնորհով եմ, և նրա շնորհը, որ իմ մեջ է, ունայն չեղավ, ընդհակառակը, նրանցից ավելի շատ աշխատեցի. սակայն ոչ թե ես, այլ Աստծու շնորհը, որ ինձ հետ է։",
            textRu: "Благодатию Божиею есмь то, что есмь; и благодать Его во мне не была тщетна, но я более всех их потрудился: не я, впрочем, а благодать Божия, которая со мною.",
            textEn: "By the grace of God I am what I am: and his grace which was bestowed upon me was not in vain; but I laboured more abundantly than they all: yet not I, but the grace of God which was with me.",
            refHy: "Ա Կորնթացիս 15:10",
