        BibleVerse(
            textHy: "Հիմա Քրիստոսը յարութիւն է առել մեռելներից, ինքը ննջածների առաջինեկ եղաւ։",
            textHyArarat: "Ոչ. Քրիստոսը ննջեցյալներից առաջինը եղավ, որ մեռելներից հարություն է առել։",
            textRu: "Христос воскрес из мертвых, первенец из умерших.",
