        BibleVerse(
            textHy: "Շնորհակալութիւն Աստուծուն, որ տուաւ մեզ յաղթութիւնը մեր Տէր Յիսուս Քրիստոսի ձեռովը։",
            textHyArarat: "Շնորհակալություն Աստծուն, որ մեզ հաղթություն տվեց մեր Տեր Հիսուս Քրիստոսի միջոցով։",
            textRu: "Благодарение Богу, даровавшему нам победу Господом нашим Иисусом Христом!",
