        BibleVerse(
            textHy: "Ուրեմն, սիրելի եղբարքս, հաստատ եղէք, անշարժ կացէք, ամեն ժամանակ աւելի առաջացէք Տիրոջ գործումը, գիտացէք, որ ձեր աշխատանքը զուր չէ Տէրումը։",
            textHyArarat: "Ուրեմն, իմ սիրելի՛ եղբայրներ, եղե՛ք հաստատուն և անսասան, Տիրոջ գործի մեջ ամեն ժամ ավելի՛ առաջ գնացեք, իմացե՛ք, որ Տիրոջով ձեր աշխատանքը զուր չէ։",
            textRu: "Братия мои возлюбленные, будьте тверды, непоколебимы, всегда преуспевайте в деле Господнем, зная, что труд ваш не тщетен пред Господом.",
