        BibleVerse(
            textHy: "Տէրն է Հոգին. Որտեղ որ Տիրոջ Հոգին է՝ այնտեղ է ազատութիւն։ Բայց մենք ամենս՝ բաց երեսով Տիրոջ փառքն ինչպէս հայելու մէջ տեսնելով՝ նոյն պատկերի նման կերպարանափոխվում ենք փառքից դէպի փառք, ինչպէս թէ Տիրոջ Հոգուցը։",
            textHyArarat: "Տերը Հոգին է, ու որտեղ Տիրոջ Հոգին է, այնտեղ է ազատությունը։ Սակայն մենք բոլորս, բաց երեսով Տիրոջ փառքը ինչպես հայելու մեջ տեսնելով, նույն պատկերով կերպարանափոխվում ենք փառքի մի աստիճանից դեպի մյուսը՝ առաջնորդվելով Տիրոջ կողմից, որ է Հոգին։",
            textRu: "Господь есть Дух; а где Дух Господень, там свобода. Мы же все открытым лицем, как в зеркале, взирая на славу Господню, преображаемся в тот же образ от славы в славу, как от Господня Духа.",
            textEn: "The Lord is that Spirit: and where the Spirit of the Lord is, there is liberty. But we all, with open face beholding as in a glass the glory of the Lord, are changed into the same image from glory to glory, even as by the Spirit of the Lord.",
