        BibleVerse(
            textHy: "Այս գանձն ունինք հողի անօթներում. որ զօրութեան գերազանցութիւնը Աստուծունը լինի, եւ ոչ թէ մեզանից։ Ամեն բանի մէջ նեղուած ենք, բայց չենք ճնշուած. Կարօտ ենք, բայց չենք տարակուսել. Հալածուած, բայց երեսից չ’ընկած. վայր ընկած, բայց չ’կորած։",
            textHyArarat: "Այս գանձն ունենք կավե անոթներում, որպեսզի ցույց տրվի, որ այս գերազանց զորությունը Աստծուց է, ոչ թե մեզանից։ Ամեն բանում նեղված ենք, բայց ճնշված չենք, կարոտյալ ենք, բայց հուսահատ չենք, հալածված ենք, բայց լքված չենք, անկյալ ենք, բայց կորսված չենք։",
            textRu: "Сокровище сие мы носим в глиняных сосудах, чтобы преизбыточная сила была приписываема Богу, а не нам. Мы отовсюду притесняемы, но не стеснены; мы в отчаянных обстоятельствах, но не отчаиваемся; мы гонимы, но не оставлены; низлагаемы, но не погибаем.",
            textEn: "We have this treasure in earthen vessels, that the excellency of the power may be of God, and not of us. We are troubled on every side, yet not distressed; we are perplexed, but not in despair; Persecuted, but not forsaken; cast down, but not destroyed.",
            refHy: "Բ Կորնթացիս 4:7-9",
