        BibleVerse(
            textHy: "Գիտենք որ եթէ մեր վրանի երկրաւոր շինուածքը քանդուի, Աստուածանից մի շինուածք ունինք՝ անձեռագործ մի տուն, որ յաւիտենական է երկնքումը։",
            textHyArarat: "Գիտենք, որ եթե մեր երկրային տունը վրանի պես ավերվի, Աստծուց ստեղծված մի բնակավայր ունենք՝ անձեռագործ հավիտենական մի տուն երկնքում։",
            textRu: "Знаем, что, когда земной наш дом, эта хижина, разрушится, мы имеем от Бога жилище на небесах, дом нерукотворенный, вечный.",
            textEn: "We know that if our earthly house of this tabernacle were dissolved, we have a building of God, an house not made with hands, eternal in the heavens.",
