        BibleVerse(
            textHy: "Վասնզի Քրիստոսի սէրը ստիպում է մեզ՝ որ սա ենք միտք անում, թէ եթէ մէկն ամենի տեղ մեռաւ, ուրեմն ամենը մեռած են. Եւ ամենի համար մեռաւ, որ կենդանի լինողները այլ եւս ոչ թէ իրանց անձերի համար կենդանի լինեն, այլ նորա համար՝ որ իրանց համար մեռաւ, եւ յարութիւն առաւ։",
            textHyArarat: "Քրիստոսի սերը մեզ ստիպում է այս խորհելու. եթե մեկը բոլորի համար մեռավ, ուրեմն բոլորը մեռած են։ Եվ բոլորի համար մեռավ, որպեսզի կենդանի եղողներն այլևս ոչ թե իրենք իրենց համար կենդանի լինեն, այլ նրա՛ համար, որ իրենց համար մեռավ ու հարություն առավ։",
            textRu: "Любовь Христова объемлет нас, рассуждающих так: если один умер за всех, то все умерли. А Христос за всех умер, чтобы живущие уже не для себя жили, но для умершего за них и воскресшего.",
            textEn: "The love of Christ constraineth us; because we thus judge, that if one died for all, then were all dead: And that he died for all, that they which live should not henceforth live unto themselves, but unto him which died for them, and rose again.",
