        BibleVerse(
            textHy: "Այն ամենն Աստուածանից է. որ մեզ իրան հետ հաշտեցրեց Յիսուս Քրիստոսի ձեռովը. Եւ մեզ հաշտութեան պաշտօնը տուաւ։ Որովհետեւ Աստուած էր Քրիստոսումը որ աշխարհքը հաշտեցրեց իրան հետ, եւ նորանց յանցանքները չ’համարեց նորանց եւ հաշտութեան խօսքը մեր միջումը դրաւ։",
            textHyArarat: "Ամեն ինչ Աստծուց է, որը մեզ Հիսուս Քրիստոսի միջոցով իր հետ հաշտեցրեց ու մեզ հաշտության ծառայությունը տվեց։ Որովհետև Աստված էր, որ Քրիստոսով աշխարհն իր հետ հաշտեցրեց և նրանց հանցանքներն իրենց ներեց և հաշտության խոսքը մեր մեջ դրեց։",
            textRu: "Все же от Бога, Иисусом Христом примирившего нас с Собою и давшего нам служение примирения, потому что Бог во Христе примирил с Собою мир, не вменяя людям преступлений их, и дал нам слово примирения.",
            textEn: "And all things are of God, who hath reconciled us to himself by Jesus Christ, and hath given to us the ministry of reconciliation; To wit, that God was in Christ, reconciling the world unto himself, not imputing their trespasses unto them; and hath committed unto us the word of reconciliation.",
            refHy: "Բ Կորնթացիս 5:18-19",
