        BibleVerse(
            textHy: "Ասում է. Ընդունելի ժամանակում լսեցի քեզ, եւ փրկութեան օրումն օգնեցի քեզ. Ահա հիմա է ընդունելի ժամանակ. Ահա հիմա է փրկութեան օր։",
            textHyArarat: "որովհետև ասում է. «Ընդունելի ժամանակ քեզ լսեցի և փրկության օրը քեզ օգնեցի» ։ Ահա հիմա է ընդունելի ժամանակը, ահա հիմա է փրկության օրը։",
            textRu: "Сказано: во время благоприятное Я услышал тебя и в день спасения помог тебе. Вот, теперь время благоприятное, вот, теперь день спасения.",
            textEn: "(For he saith, I have heard thee in a time accepted, and in the day of salvation have I succoured thee: behold, now is the accepted time; behold, now is the day of salvation.)",
            refHy: "Բ Կորնթացիս 6:2",
            refRu: "2 Коринфянам 6:2",
            refEn: "2 Corinthians 6:2"
        ),
        BibleVerse(
            textHy: "Գիտէք մեր Տէր Յիսուս Քրիստոսի շնորհքը, որ ձեզ համար աղքատացաւ նա՝ որ հարուստ էր, որ դուք նորա աղքատութիւնովը հարստանաք։",
            textHyArarat: "Գիտեք մեր Տեր Հիսուս Քրիստոսի շնորհը. նա, որ հարուստ էր, ձեզ համար աղքատացավ, որպեսզի դուք նրա աղքատանալով հարստանաք։",
            textRu: "Вы знаете благодать Господа нашего Иисуса Христа, что Он, будучи богат, обнищал ради вас, дабы вы обогатились Его нищетою.",
            textEn: "Ye know the grace of our Lord Jesus Christ, that, though he was rich, yet for your sakes he became poor, that ye through his poverty might be rich.",
            refHy: "Բ Կորնթացիս 8:9",
            refRu: "2 Коринфянам 8:9",
            refEn: "2 Corinthians 8:9"
