        BibleVerse(
            textHy: "Սա եմ ասում, թէ խնայելով սերմողը, խնայելով էլ կ’հնձէ. Եւ առատութեամբ սերմողը, առատութեամբ էլ կ’հնձէ։",
            textHyArarat: "Ով խնայողաբար է սերմանում, խնայողաբար էլ կհնձի, իսկ ով առատությամբ է սերմանում, առատությամբ էլ կհնձի։",
            textRu: "При сем скажу: кто сеет скупо, тот скупо и пожнет; а кто сеет щедро, тот щедро и пожнет.",
            textEn: "This I say, He which soweth sparingly shall reap also sparingly; and he which soweth bountifully shall reap also bountifully.",
            refHy: "Բ Կորնթացիս 9:6",
            refRu: "2 Коринфянам 9:6",
            refEn: "2 Corinthians 9:6"
        ),
        BibleVerse(
            textHy: "Եւ շնորհակալութիւն Աստուծուն նորա անպատմելի պարգեւի համար։",
            textHyArarat: "Եվ շնորհակալությո՜ւն Աստծուն նրա անպատմելի պարգևի համար։",
            textRu: "Благодарение Богу за неизреченный дар Его!",
            textEn: "Thanks be unto God for his unspeakable gift.",
            refHy: "Բ Կորնթացիս 9:15",
            refRu: "2 Коринфянам 9:15",
            refEn: "2 Corinthians 9:15"
        ),
        BibleVerse(
            textHy: "Վերջապէս, եղբարք, ուրախ եղէք, կատարեալ եղէք, մխիթարուեցէք, միաբան եղէք, եւ խաղաղութիւն արէք. եւ սէրի եւ խաղաղութեան Աստուածը ձեզ հետ լինի։",
            textHyArarat: "Արդ, եղբայրնե՛ր, ուրա՛խ եղեք, կատարյա՛լ եղեք, մխիթարվե՛ք, միաբա՛ն եղեք, խաղաղությո՛ւն արեք, և սիրո ու խաղաղության Աստվածը ձեզ հետ կլինի։",
            textRu: "Впрочем, братия, радуйтесь, усовершайтесь, утешайтесь, будьте единомысленны, мирны, — и Бог любви и мира будет с вами.",
            textEn: "Finally, brethren, farewell. Be perfect, be of good comfort, be of one mind, live in peace; and the God of love and peace shall be with you.",
            refHy: "Բ Կորնթացիս 13:11",
            refRu: "2 Коринфянам 13:11",
            refEn: "2 Corinthians 13:11"
        ),
        BibleVerse(
            textHy: "Ամենքդ Աստուծոյ որդիք էք Քրիստոս Յիսուսի հաւատքովը։ Վասնզի ամենքդ՝ որ Քրիստոսումը մկրտուեցաք, Քրիստոսին հագած էք։ Այլ եւս ոչ Հրէայ կայ եւ ոչ Յոյն, ոչ ծառայ կայ եւ ոչ ազատ, ոչ արու կայ եւ ոչ էգ. որովհետեւ դուք ամենքդ մէկ էք Քրիստոս Յիսուսումը։",
            textHyArarat: "Ամենքդ Աստծու որդիներ եք Քրիստոս Հիսուսին հավատալով։ Ձեզանից ովքեր Քրիստոսով մկրտվեցին, Քրիստոսով զգեստավորվեցին։ Այլևս ո՛չ հրեա կա, ո՛չ էլ հույն, ո՛չ ծառա կա, ո՛չ էլ ազատ, ո՛չ արու կա, ո՛չ էլ էգ, որովհետև ամենքդ մեկ եք Հիսուս Քրիստոսով։",
            textRu: "Все вы сыны Божии по вере во Христа Иисуса; все вы, во Христа крестившиеся, во Христа облеклись. Нет уже Иудея, ни язычника; нет раба, ни свободного; нет мужеского пола, ни женского: ибо все вы одно во Христе Иисусе.",
            textEn: "Ye are all the children of God by faith in Christ Jesus. For as many of you as have been baptized into Christ have put on Christ. There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus.",
            refHy: "Գաղատացիներին 3:26-28",
            refRu: "Галатам 3:26-28",
            refEn: "Galatians 3:26-28"
        ),
        BibleVerse(
            textHy: "Եւ որովհետեւ դուք որդիք էք, Աստուած իր Որդու Հոգին ուղարկեց ձեր սրտերի մէջ, որ աղաղակում է Աբբա Հայր։ Ուրեմն այլ եւս ծառայ չես՝ այլ որդի. եւ եթէ որդի՝ Աստուծոյ ժառանգ էլ Քրիստոսով։",
            textHyArarat: "Եվ քանի որ դուք որդիներ եք, Աստված մեր սրտերի մեջ իր Որդու Հոգին ուղարկեց, որ աղաղակում է. «Աբբա՛, Հա՛յր»։ Ուրեմն այլևս ծառա չես, այլ որդի, և եթե որդի, ապա նաև ժառանգ Աստծու միջոցով։",
            textRu: "Как вы — сыны, то Бог послал в сердца ваши Духа Сына Своего, вопиющего: «Авва, Отче!» Посему ты уже не раб, но сын; а если сын, то и наследник Божий через Иисуса Христа.",
            textEn: "And because ye are sons, God hath sent forth the Spirit of his Son into your hearts, crying, Abba, Father. Wherefore thou art no more a servant, but a son; and if a son, then an heir of God through Christ.",
            refHy: "Գաղատացիներին 4:6-7",
            refRu: "Галатам 4:6-7",
            refEn: "Galatians 4:6-7"
        ),
        BibleVerse(
            textHy: "Վասնզի Քրիստոս Յիսուսումը ոչ թլփատութինն է մի բան կարող, եւ ոչ անթլփատութիւնը. այլ հաւատքը որ սիրով գործում է։",
            textHyArarat: "Քանի որ Քրիստոս Հիսուսով ո՛չ թլփատությունը զորություն ունի, ո՛չ էլ անթլփատությունը, այլ հավատը, որ սիրով է գործում։",
            textRu: "Во Христе Иисусе не имеет силы ни обрезание, ни необрезание, но вера, действующая любовью.",
            textEn: "In Jesus Christ neither circumcision availeth any thing, nor uncircumcision; but faith which worketh by love.",
            refHy: "Գաղատացիներին 5:6",
            refRu: "Галатам 5:6",
            refEn: "Galatians 5:6"
        ),
        BibleVerse(
            textHy: "Դուք ազատութեան համար էք կանչուել, եղբարք. միայն թէ ձեր ազատութիւնը պատճառ չտայ մարմնին. այլ սիրով ծառայեցէք իրար։ Որովհետեւ բոլոր օրէնքն այս մէկ խօսքումն է կատարվում. Քո ընկերին քո անձի պէս սիրիր։",
            textHyArarat: "Դուք ազատության համար եք կանչված, եղբայրնե՛ր։ Միայն թե ձեր ազատությունը մարմինը հաճեցնելու պատճառ չլինի, այլ սիրո՛վ ծառայեք իրար։ Որովհետև ամբողջ օրենքն այս մեկ խոսքի մեջ է կատարվում. «Քո ընկերոջը պիտի սիրես, ինչպես ինքդ քեզ» ։",
            textRu: "К свободе призваны вы, братия, только бы свобода ваша не была поводом к угождению плоти, но любовью служите друг другу. Ибо весь закон в одном слове заключается: люби ближнего твоего, как самого себя.",
            textEn: "For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another. For all the law is fulfilled in one word, even in this; Thou shalt love thy neighbour as thyself.",
            refHy: "Գաղատացիներին 5:13-14",
            refRu: "Галатам 5:13-14",
            refEn: "Galatians 5:13-14"
        ),
        BibleVerse(
            textHy: "Եթէ Հոգով ենք ապրում, Հոգով վարուինք։",
            textHyArarat: "Եթե Հոգով ենք ապրում, Հոգով էլ վարվենք։",
            textRu: "Если мы живем духом, то по духу и поступать должны.",
            textEn: "If we live in the Spirit, let us also walk in the Spirit.",
            refHy: "Գաղատացիներին 5:25",
            refRu: "Галатам 5:25",
            refEn: "Galatians 5:25"
        ),
        BibleVerse(
            textHy: "Մի խաբուիք. Աստուած չի ծաղրուիլ։ Որովհետեւ ինչ որ մարդ սերմէ, այն էլ կհնձէ. իր մարմնի մէջ սերմողը մարմնիցն ապականութիւն կ’հնձէ. եւ Հոգու մէջ սերմողը Հոգուցն յաւիտենական կեանք կհնձէ։",
            textHyArarat: "Մի՛ խաբվեք. Աստված չի ծաղրվի։ Որովհետև մարդ ինչ որ սերմանի, այն էլ կհնձի։ Իր մարմնի համար սերմանողը մարմնից ապականություն կհնձի, իսկ Հոգու համար սերմանողը Հոգուց հավիտենական կյանք կհնձի։",
            textRu: "Не обманывайтесь: Бог поругаем не бывает. Что посеет человек, то и пожнет: сеющий в плоть свою от плоти пожнет тление, а сеющий в дух от духа пожнет жизнь вечную.",
            textEn: "Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap. For he that soweth to his flesh shall of the flesh reap corruption; but he that soweth to the Spirit shall of the Spirit reap life everlasting.",
            refHy: "Գաղատացիներին 6:7-8",
            refRu: "Галатам 6:7-8",
            refEn: "Galatians 6:7-8"
        ),
        BibleVerse(
            textHy: "Վասնզի նորա ստեղծուածն ենք՝ Քրիստոս Յիսուսով հաստատուած բարի գործերի համար. որոնց համար Աստուած առաջուց պատրաստեց մեզ, որ նորանցում վարուինք։",
            textHyArarat: "Քանզի նրա ստեղծագործությունն ենք՝ Քրիստոս Հիսուսով հաստատված բարի գործերի համար, որոնք Աստված նախապես պատրաստեց մեզ համար, որպեսզի դրանցով ընթանանք։",
            textRu: "Мы — Его творение, созданы во Христе Иисусе на добрые дела, которые Бог предназначил нам исполнять.",
            textEn: "We are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.",
            refHy: "Եփեսացիս 2:10",
            refRu: "Ефесянам 2:10",
            refEn: "Ephesians 2:10"
        ),
        BibleVerse(
            textHy: "Որ իր փառքի հարստութեան պէս տայ ձեզ, որ զօրութեամբ հաստատուիք իր Հոգու ձեռովը ներսի մարդումը։ Որ Քրիստոսը հաւատքով բնակուի ձեր սրտերումը. Եւ դուք սիրով արմատ գցած եւ հաստատուած լինիք։ Որ ամեն սուրբերի հետ իմանաք, թէ ի՞նչ է լայնութիւնը եւ երկայնութիւնը եւ բարձրութիւնը եւ խորութիւնը. Որ ճանաչէք Քրիստոսի սէրը որ ամեն գիտութիւնից գերազանց է. որ Աստուծոյ ամեն լիութիւնովը լցուիք։",
            textHyArarat: "որպեսզի ըստ իր հարուստ փառքի զորություն տա ձեզ՝ իր Հոգու միջոցով ներքնապես ամրանալու, որպեսզի Քրիստոսը ձեր սրտերում հավատի միջոցով բնակվի, և դուք սիրո մեջ արմատացած ու հաստատված լինեք, որպեսզի բոլոր սրբերի հետ կարողանաք հասկանալ, թե ի՛նչ են լայնությունը և երկարությունը, բարձրությունը և խորությունը, ճանաչեք Քրիստոսի սերը, որ գերազանցում է ամեն գիտություն, որպեսզի Աստծու ամբողջական լիությամբ լցվեք։",
            textRu: "Да даст вам, по богатству славы Своей, крепко утвердиться Духом Его во внутреннем человеке, верою вселиться Христу в сердца ваши, чтобы вы, укорененные и утвержденные в любви, могли постигнуть со всеми святыми, что широта и долгота, и глубина и высота, и уразуметь превосходящую разумение любовь Христову, дабы вам исполниться всею полнотою Божиею.",
            textEn: "That he would grant you, according to the riches of his glory, to be strengthened with might by his Spirit in the inner man; That Christ may dwell in your hearts by faith; that ye, being rooted and grounded in love, May be able to comprehend with all saints what is the breadth, and length, and depth, and height; And to know the love of Christ, which passeth knowledge, that ye might be filled with all the fulness of God.",
            refHy: "Եփեսացիս 3:16-19",
            refRu: "Ефесянам 3:16-19",
            refEn: "Ephesians 3:16-19"
        ),
        BibleVerse(
            textHy: "Ոչ մի գէշ խօսք չդուրս գայ ձեր բերանիցը. բայց այն՝ որ բարի է՝ շինութեան համար հարկաւոր, որ շնորհք տայ լսողներին։",
            textHyArarat: "Ձեր բերանից թող ոչ մի վատ խոսք դուրս չգա, միայն այն, որ բարի է, հավատի շինության համար պիտանի, որպեսզի շնորհ տա լսողներին։",
            textRu: "Никакое гнилое слово да не исходит из уст ваших, а только доброе для назидания в вере, дабы оно доставляло благодать слушающим.",
            textEn: "Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers.",
            refHy: "Եփեսացիս 4:29",
            refRu: "Ефесянам 4:29",
            refEn: "Ephesians 4:29"
        ),
        BibleVerse(
            textHy: "Խօսելով ձեր մէջ սաղմոսներով եւ օրհնութիւններով եւ հոգեւոր երգերով, երգեցէք եւ սաղմոսեցէք ձեր սրտերումը Տիրոջը։ Ամեն ժամանակ ամեն բանի համար գոհացէք Աստուածանից եւ Հօրիցը՝ մեր Տէր Յիսուս Քրիստոսի անունովը։ Իրար հնազանդ եղէք Աստուծոյ վախովը։",
            textHyArarat: "Միմյանց հետ սաղմոսներով, օրհնություններով ու հոգևոր երգերո՛վ խոսեք, ձեր սրտերում Տիրո՛ջը երգեք ու սաղմո՛ս ասեք։ Ամեն ժամ ու ամեն բանում մեր Տեր Հիսուս Քրիստոսի անունով գոհությո՛ւն հայտնեք Աստծուն և Հորը։ Քրիստոսի երկյուղով միմյանց հնազա՛նդ եղեք։",
            textRu: "Назидая самих себя псалмами и славословиями и песнопениями духовными, поя и воспевая в сердцах ваших Господу, благодаря всегда за все Бога и Отца, во имя Господа нашего Иисуса Христа, повинуясь друг другу в страхе Божием.",
            textEn: "Speaking to yourselves in psalms and hymns and spiritual songs, singing and making melody in your heart to the Lord; Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ; Submitting yourselves one to another in the fear of God.",
            refHy: "Եփեսացիս 5:19-21",
            refRu: "Ефесянам 5:19-21",
            refEn: "Ephesians 5:19-21"
        ),
        BibleVerse(
            textHy: "Ոչ մի բան չլինի գրգռումով, եւ ոչ էլ սնապարծութինով. այլ խոնարհութիւնով թող մէկը միւսին իր անձիցն աւելի լաւ համարէ։ Մինակ ձեր անձերի բաներին մտիկ չտաք, այլ ամեն մէկն իր ընկերի բաներին էլ։",
            textHyArarat: "Ոչինչ մի՛ արեք հակառակությամբ և ոչ էլ սնապարծությամբ, այլ խոնարհությամբ մեկը մյուսին թող իր անձից ավելի լավ համարի։ Միայն ինքներդ ձեր շահերը մի՛ փնտրեք, այլ ամեն մեկն իր ընկերոջինը ևս։",
            textRu: "Ничего не делайте по любопрению или по тщеславию, но по смиренномудрию почитайте один другого высшим себя. Не о себе только каждый заботься, но каждый и о других.",
            textEn: "Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves. Look not every man on his own things, but every man also on the things of others.",
            refHy: "Փիլիպպեցիներին 2:3-4",
            refRu: "Филиппийцам 2:3-4",
            refEn: "Philippians 2:3-4"
        ),
        BibleVerse(
            textHy: "Վասնզի Աստուած է՝ որ ներգործում է ձեզանում կամենալն էլ՝ անելն էլ իր հաճութեան պէս։",
            textHyArarat: "Աստված է, որ ձեր մեջ ներգործում է կամենալն ու կատարելն ըստ իր բարեհաճ ծրագրի։",
            textRu: "Бог производит в вас и хотение и действие по Своему благоволению.",
            textEn: "It is God which worketh in you both to will and to do of his good pleasure.",
            refHy: "Փիլիպպեցիներին 2:13",
            refRu: "Филиппийцам 2:13",
            refEn: "Philippians 2:13"
        ),
        BibleVerse(
            textHy: "Մեր քաղաքականութիւնը երկնքումն է, որ այնտեղից սպասում ենք Փրկչին՝ Տէր Յիսուս Քրիստոսին. Որ կնորոգէ մեր խոնարհ մարմինը որ իր փառաւոր մարմնին կերպարանակից լինի այն զօրութիւնովը, որ կարող է ամեն բան հնազանդեցնել իրան։",
            textHyArarat: "Մեր բնակությունը երկնքում է, այնտեղից էլ սպասում ենք Փրկչին՝ Տեր Հիսուս Քրիստոսին, որը մեր խոնարհ մարմինը պիտի նորոգի և իր փառավոր մարմնին կերպարանակից դարձնի այն զորությամբ, որ ամեն ինչ հնազանդեցնում է իրեն։",
            textRu: "Наше же жительство — на небесах, откуда мы ожидаем и Спасителя, Господа нашего Иисуса Христа, Который уничиженное тело наше преобразит так, что оно будет сообразно славному телу Его, силою, которою Он действует и покоряет Себе всё.",
            textEn: "Our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ: Who shall change our vile body, that it may be fashioned like unto his glorious body, according to the working whereby he is able even to subdue all things unto himself.",
            refHy: "Փիլիպպեցիներին 3:20-21",
            refRu: "Филиппийцам 3:20-21",
