        BibleVerse(
            textHy: "Հէնց այն որ սովորեցիք, եւ ընդունեցիք, եւ լսեցիք, եւ ինձանում տեսաք, այն արէք. եւ խաղաղութեան Աստուածը ձեզ հետ կլինի։",
            textHyArarat: "Հենց այն, ինչ սովորեցիք, ընդունեցիք, լսեցիք ու իմ մեջ տեսաք, ա՛յն արեք, և խաղաղության Աստվածը ձեզ հետ կլինի։",
            textRu: "Чему вы научились, что приняли и слышали и видели во мне, то исполняйте, — и Бог мира будет с вами.",
            textEn: "Those things, which ye have both learned, and received, and heard, and seen in me, do: and the God of peace shall be with you.",
            refHy: "Փիլիպպեցիներին 4:9",
            refRu: "Филиппийцам 4:9",
            refEn: "Philippians 4:9"
