        BibleVerse(
            textHy: "Ինչպէս Քրիստոս Յիսուս Տէրն ընդունեցիք՝ նորանում գնացէք. Արմատացած եւ նորանում շինուած, եւ հաւատքումը հաստատուած՝ ինչպէս որ սովորեցիք՝ աճելով նորանում գոհութիւնով։",
            textHyArarat: "Ինչպես ընդունեցիք Քրիստոս Հիսուսին՝ Տիրոջը, նրանով էլ ընթացե՛ք՝ արմատավորված և նրանով շինված, հավատի մեջ հաստատված, ինչպես որ սովորեցիք, և դրա մեջ աճե՛ք գոհություն հայտնելով։",
            textRu: "Посему, как вы приняли Христа Иисуса Господа, так и ходите в Нем, будучи укоренены и утверждены в Нем и укреплены в вере, как вы научены, преуспевая в ней с благодарением.",
            textEn: "As ye have therefore received Christ Jesus the Lord, so walk ye in him: Rooted and built up in him, and stablished in the faith, as ye have been taught, abounding therein with thanksgiving.",
