        BibleVerse(
            textHy: "Քրիստոսի խօսքը բնակուի ձեր միջումն առատապէս ամեն իմաստութիւնով. իրար սովորեցրէք եւ խրատեցէք, սաղմոսներով եւ օրհնութիւններով եւ հոգեւոր երգերով եւ շնորհքով օրհներգեցէք Տիրոջը ձեր սրտերումը։",
            textHyArarat: "Քրիստոսի խոսքը թող առատապես բնակվի ձեր մեջ, ամենայն իմաստությամբ միմյանց ուսուցանե՛ք ու խրատե՛ք, ձեր սրտերում երախտագիտությամբ օրհնե՛ք Տիրոջը սաղմոսներով, օրհնություններով ու հոգևոր երգերով։",
            textRu: "Слово Христово да вселяется в вас обильно, со всякою премудростью; научайте и вразумляйте друг друга псалмами, славословием и духовными песнями, во благодати воспевая в сердцах ваших Господу.",
            textEn: "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.",
            refHy: "Կողոսացիս 3:16",
            refRu: "Колоссянам 3:16",
            refEn: "Colossians 3:16"
