        BibleVerse(
            textHy: "Եւ ամեն ինչ որ էլ անէք խօսքով կամ գործով, ամենը Տէր Յիսուսի անունովն արէք, գոհութիւն տալով Աստուծուն եւ Հօրը նորա ձեռովը։",
            textHyArarat: "Եվ ամենը, ինչ էլ որ անեք՝ խոսքով կամ գործով, ամեն բան Տեր Հիսուսի անունո՛վ արեք՝ նրա միջոցով գոհություն հայտնելով Աստծուն և Հորը։",
            textRu: "И всё, что вы делаете, словом или делом, всё делайте во имя Господа Иисуса Христа, благодаря через Него Бога и Отца.",
            textEn: "And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him.",
            refHy: "Կողոսացիս 3:17",
