        BibleVerse(
            textHy: "Աղօթքին միշտ հետեւեցէք. եւ արթուն կացէք նորանում գոհութիւնով։",
            textHyArarat: "Մշտապես աղոթե՛ք ու գոհունակությամբ արթո՛ւն կացեք նրա մեջ։",
            textRu: "Будьте постоянны в молитве, бодрствуя в ней с благодарением.",
