        BibleVerse(
            textHy: "Ձեր խօսքը ամեն ժամանակ շնորհքով՝ աղով համեմած լինի, որ գիտենաք թէ ինչպէս արժան է ձեզ ամեն մէկին պատասխան տալ։",
            textHyArarat: "Ձեր խոսքը միշտ թող շնորհով՝ ինչպես աղով համեմված լինի, որպեսզի գիտենաք, թե ինչպե՛ս է արժան ձեզնից յուրաքանչյուրին պատասխանել։",
            textRu: "Слово ваше да будет всегда с благодатию, приправлено солью, дабы вы знали, как отвечать каждому.",
            textEn: "Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man.",
            refHy: "Կողոսացիս 4:6",
            refRu: "Колоссянам 4:6",
            refEn: "Colossians 4:6"
        ),
        BibleVerse(
            textHy: "Եթէ հաւատում ենք, որ Յիսուսը մեռաւ եւ յարութիւն առաւ, այնպէս էլ Աստուած ննջեցեալներին Յիսուսի ձեռով կ’բերէ նորա հետ։ Որովհետեւ սա ենք ասում ձեզ Տիրոջ խօսքովը, թէ մենք որ կենդանի մնացած ենք մինչեւ Տիրոջ գալը, ննջեցեալներիցը չենք առաջանալ։",
            textHyArarat: "Չենք կամենում, եղբայրնե՛ր, որ ննջեցյալների մասին անտեղյակ լինեք ու տրտմեք, ինչպես ուրիշները, որ հույս չունեն։ Որովհետև եթե հավատում ենք, որ Հիսուսը մեռավ ու հարություն առավ, այդպես էլ Աստված Հիսուսով ննջեցյալներին կյանքի կբերի նրա հետ։",
            textRu: "Не хочу же оставить вас, братия, в неведении об умерших, дабы вы не скорбели, как прочие, не имеющие надежды. Ибо, если мы веруем, что Иисус умер и воскрес, то и умерших в Иисусе Бог приведет с Ним.",
            textEn: "I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope. For if we believe that Jesus died and rose again, even so them also which sleep in Jesus will God bring with him.",
            refHy: "Ա Թեսաղոնիկեցիս 4:13-14",
            refRu: "1 Фессалоникийцам 4:13-14",
            refEn: "1 Thessalonians 4:13-14"
        ),
        BibleVerse(
            textHy: "Զգոյշ կացէք՝ մի գուցէ մէկը չարի տեղ չար հատուցանէ, այլ ամեն ժամանակ բարիին հետեւեցէք իրար հետ եւ ամենի հետ։",
            textHyArarat: "Զգո՛ւյշ եղեք. միգուցե մեկը չարի փոխարեն չարը հատուցի. այլ իրար հետ ու բոլորի հանդեպ ամեն ժամ բարի՛ն գործեք։",
            textRu: "Смотрите, чтобы кто кому не воздавал злом за зло; но всегда ищите добра и друг другу и всем.",
            textEn: "See that none render evil for evil unto any man; but ever follow that which is good, both among yourselves, and to all men.",
            refHy: "Ա Թեսաղոնիկեցիս 5:15",
            refRu: "1 Фессалоникийцам 5:15",
            refEn: "1 Thessalonians 5:15"
        ),
        BibleVerse(
            textHy: "Եւ ինքը խաղաղութեան Աստուածը ձեզ սուրբ անէ բոլորովին. եւ ձեր բոլոր հոգին եւ շունչը եւ մարմինը անարատ պահուի մինչեւ մեր Տէր Յիսուս Քրիստոսի գալը։ Հաւատարիմ է նա որ կանչեց ձեզ, որ կ’անէ էլ։",
            textHyArarat: "Եվ ինքը՝ խաղաղության Աստվածը, ձեզ ամբողջովին թող մաքրի, ու ձեր ամբողջ հոգին, շունչը և մարմինը անարատ պահվեն մինչև մեր Տեր Հիսուս Քրիստոսի գալուստը։ Հավատարիմ է նա, ով կանչեց ձեզ, և որը դեռ կանի։",
            textRu: "Сам же Бог мира да освятит вас во всей полноте, и ваш дух и душа и тело во всей целости да сохранится без порока в пришествие Господа нашего Иисуса Христа. Верен Призывающий вас, Который и сотворит сие.",
            textEn: "And the very God of peace sanctify you wholly; and I pray God your whole spirit and soul and body be preserved blameless unto the coming of our Lord Jesus Christ. Faithful is he that calleth you, who also will do it.",
            refHy: "Ա Թեսաղոնիկեցիս 5:23-24",
            refRu: "1 Фессалоникийцам 5:23-24",
            refEn: "1 Thessalonians 5:23-24"
        ),
        BibleVerse(
            textHy: "Նա մխիթարէ ձեր սրտերը եւ հաստատէ ձեզ ամեն բարի խօսքի եւ գործերի մէջ։ да утешит ваши сердца и да утвердит вас во всяком слове и деле благом.",
            textHyArarat: "Եվ ինքը՝ մեր Տեր Հիսուս Քրիստոսը, և մեր Աստվածն ու Հայրը, որ մեզ սիրեց ու հավիտենական մխիթարություն ու բարի հույս տվեց մեզ շնորհով, թող նա մխիթարի ձեր սրտերը և հաստատի ձեզ ամեն բարի գործի ու խոսքի մեջ։",
            textRu: "Сам же Господь наш Иисус Христос и Бог и Отец наш, возлюбивший нас и давший утешение вечное и надежду благую во благодати, да утешит ваши сердца и да утвердит вас во всяком слове и деле благом.",
            textEn: "Our Lord Jesus Christ himself, and God, even our Father, which hath loved us, and hath given us everlasting consolation and good hope through grace, Comfort your hearts, and stablish you in every good word and work.",
            refHy: "Բ Թեսաղոնիկեցիներ 2:16-17",
            refRu: "2 Фессалоникийцам 2:16-17",
            refEn: "2 Thessalonians 2:16-17"
        ),
        BibleVerse(
            textHy: "Ինքը խաղաղութեան Տէրը տայ ձեզ խաղաղութիւնը ամեն ժամանակ, եւ ամեն կերպով. Տէրը ձեր ամենի հետ լինի։",
            textHyArarat: "Ինքը՝ խաղաղության Տերը, թող ամեն ժամ ու ամեն կերպ ձեզ խաղաղություն տա։ Տերը ձեզ բոլորիդ հետ։",
            textRu: "Сам же Господь мира да даст вам мир всегда во всем. Господь со всеми вами!",
            textEn: "The Lord of peace himself give you peace always by all means. The Lord be with you all.",
            refHy: "Բ Թեսաղոնիկեցիներ 3:16",
            refRu: "2 Фессалоникийцам 3:16",
            refEn: "2 Thessalonians 3:16"
        ),
        BibleVerse(
            textHy: "Ճշմարիտ է այս խօսքը եւ ամեն ընդունելութեան արժանի, որ Քրիստոս Յիսուսն աշխարհք եկաւ մեղաւորները փրկելու, որոնց առաջինը ես եմ։",
            textHyArarat: "Վստահության և ամենայն ընդունելության է արժանի այն խոսքը, որ Քրիստոս Հիսուսն աշխարհ եկավ փրկելու մեղավորներին, որոնցից առաջինը ես եմ։",
            textRu: "Верно и всякого принятия достойно слово, что Христос Иисус пришел в мир спасти грешников, из которых я первый.",
            textEn: "This is a faithful saying, and worthy of all acceptation, that Christ Jesus came into the world to save sinners; of whom I am chief.",
            refHy: "Ա Տիմոթեոս 1:15",
            refRu: "1 Тимофею 1:15",
            refEn: "1 Timothy 1:15"
        ),
        BibleVerse(
            textHy: "Մարմնի վարժութիւնը քիչ բանի համար է օգտակար. բայց աստուածպաշտութիւնն ամեն բանի համար օգտակար է, ունենալով այժմեան եւ գալու կենաց խոստմունքը։",
            textHyArarat: "որովհետև մարմնամարզությունը քիչ բանի համար է օգտակար, իսկ աստվածապաշտությունն ամեն ինչի համար օգտակար է։ Այն ունի այժմյան ու գալիք կյանքի ավետիսը։",
            textRu: "Телесное упражнение мало полезно, а благочестие на все полезно, имея обетование жизни настоящей и будущей.",
            textEn: "Bodily exercise profiteth little: but godliness is profitable unto all things, having promise of the life that now is, and of that which is to come.",
            refHy: "Ա Տիմոթեոս 4:8",
            refRu: "1 Тимофею 4:8",
            refEn: "1 Timothy 4:8"
        ),
        BibleVerse(
            textHy: "Դու, ով Աստուծոյ մարդ, փախիր սորանցից, եւ հետեւիր արդարութեան, աստուածպաշտութեան, հաւատքի, սէրի, համբերութեան, հեզութեան։ Պատերազմիր հաւատքի բարի պատերազմը, եւ բռնիր յաւիտենական կեանքը որի մէջ կանչուեցար, եւ դաւանեցիր բարի դաւանութիւնը շատ վկաների առաջին։",
            textHyArarat: "Դու, ո՛վ մարդ Աստծու, փախի՛ր դրանցից և հետևի՛ր արդարությանը, աստվածապաշտությանը, հավատին, սիրուն, համբերությանը, հեզությանը։ Հավատի բարի պատերա՛զմ մղիր, նվաճի՛ր հավիտենական կյանքը, որի մեջ կանչվեցիր և բազում վկաների առաջ բարի դավանանքը դավանեցիր։",
            textRu: "Ты же, человек Божий, убегай сего, а преуспевай в правде, благочестии, вере, любви, терпении, кротости. Подвизайся добрым подвигом веры, держись вечной жизни, к которой ты и призван, и исповедал доброе исповедание перед многими свидетелями.",
            textEn: "Thou, O man of God, flee these things; and follow after righteousness, godliness, faith, love, patience, meekness. Fight the good fight of faith, lay hold on eternal life, whereunto thou art also called, and hast professed a good profession before many witnesses.",
            refHy: "Ա Տիմոթեոս 6:11-12",
            refRu: "1 Тимофею 6:11-12",
            refEn: "1 Timothy 6:11-12"
        ),
        BibleVerse(
            textHy: "Ներկայ աշխարհիս հարուստներին պատուիրիր որ չ’գոռոզանան, եւ ոչ էլ ունայն մեծութեան վերայ յոյս դնեն, այլ կենդանի Աստուծոյ վերայ որ ամեն բան տալիս է մեզ առատապէս վայելելու համար։ Բարի գործեն, բարի գործերով հարստանան, առատաձեռն եւ կարօտներին հաղորդող լինեն։ Իրանց անձերի համար բարի հիմ գանձեն հանդերձեալի համար, որ յաւիտենական կեանք ձեռք բերեն։",
            textHyArarat: "Այս աշխարհի հարուստներին պատվիրի՛ր, որ չմեծամտանան և ոչ էլ հույսը դնեն ունայն հարստության վրա, այլ Աստծու վրա, որ վայելելու համար ամեն բան առատապես տալիս է մեզ։ Թող բարիք գործեն, բարի գործերով հարստանան, առատաձեռն լինեն և ուրիշին բաժին հանեն իրենց ունեցածից։ Իրենք իրենց համար գանձ հավաքելով՝ լավ հիմք կունենան հանդերձյալի համար, որպեսզի ճշմարիտ կյանք ձեռք բերեն։",
            textRu: "Богатых в настоящем веке увещевай, чтобы они не высоко думали о себе и уповали не на богатство неверное, но на Бога живаго, дающего нам всё обильно для наслаждения; чтобы они благодетельствовали, богатели добрыми делами, были щедры и общительны, собирая себе сокровище, доброе основание для будущего, чтобы достигнуть вечной жизни.",
            textEn: "Charge them that are rich in this world, that they be not highminded, nor trust in uncertain riches, but in the living God, who giveth us richly all things to enjoy; That they do good, that they be rich in good works, ready to distribute, willing to communicate; Laying up in store for themselves a good foundation against the time to come, that they may lay hold on eternal life.",
            refHy: "Ա Տիմոթեոս 6:17-19",
            refRu: "1 Тимофею 6:17-19",
            refEn: "1 Timothy 6:17-19"
        ),
        BibleVerse(
            textHy: "Որ այդ պատճառով էլ չարչարանքները կրում եմ. բայց ամօթ չեմ համարում. որովհետեւ գիտեմ թէ ո՞ւմ եմ հաւատացել. եւ համոզուած եմ թէ նա կարող է իմ աւանդը պահել մինչեւ այն օրը։",
            textHyArarat: "Այդ պատճառով էլ կրում եմ այս չարչարանքները, բայց ամոթ չեմ համարում, որովհետև գիտեմ, թե ո՛ւմ եմ հավատացել, և համոզված եմ, որ նա կարող է իմ ավանդը պահել մինչև այն օրը։",
            textRu: "По сей причине я и страдаю так; но не стыжусь. Ибо я знаю, в Кого уверовал, и уверен, что Он силен сохранить залог мой на оный день.",
            textEn: "The which cause I also suffer these things: nevertheless I am not ashamed: for I know whom I have believed, and am persuaded that he is able to keep that which I have committed unto him against that day.",
            refHy: "Բ Տիմոթեոս 1:12",
            refRu: "2 Тимофею 1:12",
            refEn: "2 Timothy 1:12"
        ),
        BibleVerse(
            textHy: "Դու, իմ որդեակ, զօրացիր այն շնորհքովը որ Քրիստոս Յիսուսումն է։ Եւ այն բաները որ ինձանից լսեցիր շատ վկաներով, յանձնիր հաւատարիմ մարդկանց որ կարող լինեն ուրիշներին սովորեցնել։",
            textHyArarat: "Դու, որդյա՛կ իմ, զորացի՛ր շնորհով, որ Քրիստոս Հիսուսի մեջ է։ Եվ այն, ինչ ինձանից լսեցիր բազում վկաների ներկայությամբ, հավատարիմ մարդկա՛նց ավանդիր, որոնք ընդունակ են ուրիշներին ևս ուսուցանել։",
            textRu: "Укрепляйся, сын мой, в благодати Христом Иисусом, и что слышал от меня при многих свидетелях, то передай верным людям, которые были бы способны и других научить.",
            textEn: "Thou therefore, my son, be strong in the grace that is in Christ Jesus. And the things that thou hast heard of me among many witnesses, the same commit thou to faithful men, who shall be able to teach others also.",
            refHy: "Բ Տիմոթեոս 2:1-2",
            refRu: "2 Тимофею 2:1-2",
            refEn: "2 Timothy 2:1-2"
        ),
        BibleVerse(
            textHy: "Ամեն Գիրք աստուածաշունչ են եւ օգտակար՝՝, վարդապետութեան, եւ յանդիմանութեան, եւ ուղղելու, եւ արդարութեան խրատելու համար. Որ Աստուծոյ մարդը կատարեալ լինի ամեն բարի գործերի համար պատրաստուած։",
            textHyArarat: "Ամբողջ Գիրքն աստվածաշունչ է և օգտակար ուսուցանելու, հանդիմանելու, ուղղելու և արդարության մեջ խրատելու համար, որպեսզի Աստծու մարդը լինի կատարյալ, պատրաստ ամեն բարի գործի։",
            textRu: "Все Писание богодухновенно и полезно для научения, для обличения, для исправления, для наставления в праведности, да будет совершен Божий человек, ко всякому доброму делу приготовлен.",
            textEn: "All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness: That the man of God may be perfect, throughly furnished unto all good works.",
            refHy: "Բ Տիմոթեոս 3:16-17",
            refRu: "2 Тимофею 3:16-17",
            refEn: "2 Timothy 3:16-17"
        ),
        BibleVerse(
            textHy: "Տէրն ինձ մօտ կանգնեց, եւ զօրացրեց ինձ որ ինձանով քարոզութիւնը հաստատուի, եւ բոլոր հեթանոսները լսեն. եւ ես ազատուեցայ առիւծի բերանիցը։ Եւ կ’փրկէ ինձ Տէրն ամեն չար բանից եւ կ’ազատէ կ’հասցնէ իր երկնային արքայութեանը. որին լինի փառք յաւիտեանս յաւիտենից. Ամէն։",
            textHyArarat: "Տերն ինձ նեցուկ եղավ ու զորացրեց, որպեսզի իմ միջոցով քարոզչությունը հաստատվի, ու բոլոր հեթանոսները լսեն. և ես առյուծի բերանից ազատվեցի։ Եվ Տերն ինձ ամեն չարից կփրկի, կազատի և կհասցնի իր երկնային արքայությանը։ Նրան փա՜ռք հավիտյանս հավիտենից։ Ամեն։",
            textRu: "Господь же предстал мне и укрепил меня, дабы через меня утвердилось благовестие и услышали все язычники; и я избавился из львиных челюстей. И избавит меня Господь от всякого злого дела и сохранит для Своего Небесного Царства, Ему слава во веки веков. Аминь.",
            textEn: "Notwithstanding the Lord stood with me, and strengthened me; that by me the preaching might be fully known, and that all the Gentiles might hear: and I was delivered out of the mouth of the lion. And the Lord shall deliver me from every evil work, and will preserve me unto his heavenly kingdom: to whom be glory for ever and ever. Amen.",
            refHy: "Բ Տիմոթեոս 4:17-18",
            refRu: "2 Тимофею 4:17-18",
            refEn: "2 Timothy 4:17-18"
        ),
        BibleVerse(
            textHy: "Ինքը որ չարչարուեցաւ եւ փորձուեցաւ, կարող է օգնութիւն տալ փորձուողներին։",
            textHyArarat: "Ինչպես որ ինքը չարչարվեց ու փորձվեց, այնպես էլ կարող է օգնել փորձության ենթարկվածներին։",
            textRu: "Как Сам Он претерпел, быв искушен, то может и искушаемым помочь.",
            textEn: "In that he himself hath suffered being tempted, he is able to succour them that are tempted.",
            refHy: "Եբրայեցիս 2:18",
            refRu: "Евреям 2:18",
            refEn: "Hebrews 2:18"
        ),
        BibleVerse(
            textHy: "Այլ իրար յորդորեցէք ամեն մէկ օր. քանի որ այսօր է ասվում. որ ձեզանից մէկը չխստանայ մեղքի խաբէութիւնովը։",
            textHyArarat: "Այլ ամեն օր միմյանց հորդորե՛ք, քանի որ այսօրը դեռ կա, որպեսզի ձեզանից ոչ ոք մեղքի խաբեությամբ չկարծրանա։",
            textRu: "Наставляйте друг друга каждый день, доколе можно говорить: «ныне», чтобы кто из вас не ожесточился, обольстившись грехом.",
            textEn: "Exhort one another daily, while it is called To day; lest any of you be hardened through the deceitfulness of sin.",
            refHy: "Եբրայեցիս 3:13",
            refRu: "Евреям 3:13",
            refEn: "Hebrews 3:13"
        ),
        BibleVerse(
            textHy: "Եւ բոլորովին կարող է փրկել նորանց որ նորանով մօտենում են Աստուծուն, որովհետեւ միշտ կենդանի է որ նորանց համար բարեխօսութիւն անէ։",
            textHyArarat: "ԵՒ կարող է փրկել նրանց, ովքեր իր միջոցով մոտենում են Աստծուն, որովհետև միշտ կենդանի է, որպեսզի նրանց համար բարեխոս լինի։",
            textRu: "И может всегда спасать приходящих чрез Него к Богу, будучи всегда жив, чтобы ходатайствовать за них.",
            textEn: "He is able also to save them to the uttermost that come unto God by him, seeing he ever liveth to make intercession for them.",
            refHy: "Եբրայեցիս 7:25",
            refRu: "Евреям 7:25",
            refEn: "Hebrews 7:25"
        ),
        BibleVerse(
            textHy: "Եւ զգուշանանք իրար համար՝ դէպի սէր եւ բարի գործեր գրգռելով. Եւ չթողենք մեր իրար հետ ժողովուիլը, ինչպէս ոմանց սովորութիւն է. բայց իրար յորդորենք, եւ այնքան աւելի՝ որքան տեսնում էք որ օրը մօտեցած է։",
            textHyArarat: "Եվ միմյանց նկատմամբ հոգատար լինենք՝ սիրո ու բարի գործերի մղելով։ Եվ մեր մեկտեղ հավաքվելը զանց չառնենք, ինչպես ոմանց սովորությունն է, այլ միմյանց քաջալերենք, և այնքան ավելի, որքան տեսնում եք, որ օրը մոտեցել է։",
            textRu: "Будем внимательны друг ко другу, поощряя к любви и добрым делам. Не будем оставлять собрания своего, как есть у некоторых обычай; но будем увещевать друг друга, и тем более, чем более усматриваете приближение дня оного.",
            textEn: "And let us consider one another to provoke unto love and to good works: Not forsaking the assembling of ourselves together, as the manner of some is; but exhorting one another: and so much the more, as ye see the day approaching.",
