        BibleVerse(
            textHy: "Դէն մի գցէք ձեր վստահութիւնը, որ մեծ վարձքի հատուցումն ունի։ Որովհետեւ համբերութիւն է պէտք ձեզ, որ Աստուծոյ կամքն անելով խոստմունքն ստանաք։ Որովհետեւ միայն մի քիչ ժամանակ էլ, եւ նա որ գալու է՝ կգայ եւ չի ուշանալ։",
            textHyArarat: "Մի՛ կորցրեք ձեր վստահությունը, որ մեծ վարձատրություն ունի։ Ձեզ համբերություն է պետք, որպեսզի Աստծու կամքը կատարելով՝ խոստումն ստանաք։ Քանի որ «Մի փոքր միայն, մի փոքր ժամանակ ևս, և նա, ով գալու է, կգա ու չի ուշանա։",
            textRu: "Не оставляйте упования вашего, которому предстоит великое воздаяние. Терпение нужно вам, чтобы, исполнив волю Божию, получить обещанное; ибо еще немного, очень немного, и Грядущий придет и не умедлит.",
            textEn: "Cast not away therefore your confidence, which hath great recompence of reward. For ye have need of patience, that, after ye have done the will of God, ye might receive the promise. For yet a little while, and he that shall come will come, and will not tarry.",
