        BibleVerse(
            textHy: "Մտիկ տանք հաւատքի զօրագլուխին եւ կատարողին՝ Յիսուսին, որ իր առաջին դրուած ուրախութեան փոխանակ խաչը յանձն առաւ, եւ ամօթն արհամարհելով՝ Աստուծոյ աթոռի աջ կողմը նստեց։",
            textHyArarat: "նայենք հավատի զորագլխին ու այն կատարողին՝ Հիսուսին, որն իր առջև դրված ուրախության փոխարեն խաչը հանձն առավ և ամոթն արհամարհելով՝ Աստծու աթոռի աջ կողմում նստեց։",
            textRu: "Взирая на начальника и совершителя веры Иисуса, Который, вместо предлежавшей Ему радости, претерпел крест, пренебрегши посрамление, и воссел одесную престола Божия.",
            textEn: "Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.",
