        BibleVerse(
            textHy: "Եւ ամեն խրատ հէնց նոյն ժամանակին ուրախութիւն չէ երեւում, այլ տրտմութիւն. բայց յետոյ նորանով վարժուածներին արդար խաղաղութեան պտուղ է վճարում։",
            textHyArarat: "Եվ ամեն խրատ տվյալ պահին ուրախություն չի թվում, այլ տրտմություն, սակայն հետո դրանով դաստիարակվածներին արդար խաղաղության պտուղ է տալիս։",
            textRu: "Всякое наказание в настоящее время кажется не радостью, а печалью; но после наученным через него доставляет мирный плод праведности.",
            textEn: "No chastening for the present seemeth to be joyous, but grievous: nevertheless afterward it yieldeth the peaceable fruit of righteousness unto them which are exercised thereby.",
