        BibleVerse(
            textHy: "Հետեւեցէք խաղաղութեան ամենի հետ եւ սրբութեան, որ առանց նորան ոչ ով Տիրոջը չի տեսնիլ.",
            textHyArarat: "Բոլորի հետ հետամո՛ւտ եղեք խաղաղության և սրբության, առանց որի ոչ ոք Տիրոջը չի տեսնի։",
            textRu: "Старайтесь иметь мир со всеми и святость, без которой никто не увидит Господа.",
