        BibleVerse(
            textHy: "Հիւրասիրութիւնը մի մոռանաք. որ նորանով ոմանք առանց գիտենալու հրեշտակներ ընդունեցին։",
            textHyArarat: "Օտարասիրությունը մի՛ մոռացեք. դրա շնորհիվ ոմանք առանց գիտենալու հրեշտակներ հյուրընկալեցին։",
            textRu: "Страннолюбия не забывайте, ибо через него некоторые, не зная, оказали гостеприимство Ангелам.",
