        BibleVerse(
            textHy: "Բարերարութիւնը եւ հաղորդակցիլը մի մոռանաք. որ այնպիսի պատարագներին հաւանում է Աստուած։",
            textHyArarat: "Մի՛ մոռացեք բարեգործություն անել և կարոտյալներին ձեր ունեցածից բաժին հանել. այդպիսի զոհերը հաճելի են Աստծուն։",
            textRu: "Не забывайте также благотворения и общительности, ибо таковые жертвы благоугодны Богу.",
