        BibleVerse(
            textHy: "Եւ խաղաղութեան Աստուածը որ մեռելներից վեր հանեց ոչխարների մեծ Հովիւն յաւիտենական ուխտի արիւնովը՝ մեր Տէր Յիսուսին, Հաստատէ ձեզ ամեն բարի գործի մէջ նորա կամքն անելու, եւ գործէ ձեզանում ինչ որ հաճոյ է նորա առաջին Յիսուս Քրիստոսի ձեռովը. որին լինի փառք յաւիտեանս յաւիտենից։ Ամէն։",
            textHyArarat: "Եվ խաղաղության Աստվածը, որ հավիտենական ուխտի արյունով մեռելներից հարություն տվեց ոչխարների մեծ Հովվին՝ մեր Տեր Հիսուսին, թող ձեզ ամեն բարի գործի մեջ հաստատ պահի՝ իր կամքը կատարելու, և ձեր մեջ թող կատարի, ինչ որ հաճելի է իր առաջ, Հիսուս Քրիստոսի միջոցով, որին փա՜ռք հավիտյանս հավիտենից։ Ամեն։",
            textRu: "Бог же мира, воздвигший из мертвых Пастыря овец великого Кровию завета вечного, Господа нашего Иисуса, да усовершит вас во всяком добром деле, к исполнению воли Его, производя в вас благоугодное Ему через Иисуса Христа. Ему слава во веки веков! Аминь.",
            textEn: "The God of peace, that brought again from the dead our Lord Jesus, that great shepherd of the sheep, through the blood of the everlasting covenant, Make you perfect in every good work to do his will, working in you that which is wellpleasing in his sight, through Jesus Christ; to whom be glory for ever and ever. Amen.",
