        BibleVerse(
            textHy: "Սորա համար ամեն աղտեղութիւն եւ չարութեան առաւելութիւնը դէն գցեցէք, եւ խոնարհութիւնով ընդունեցէք ձեր մէջ սերմուած խօսքը, որ կարող է ձեր հոգիները ապրեցնել։",
            textHyArarat: "Դրա համար ամեն աղտեղություն, չարության կուտակում դե՛ն գցեք և հեզությա՛մբ ընդունեք ձեր մեջ սերմանված խոսքը, որ կարող է ձեր հոգիները փրկել։",
            textRu: "Посему, отложив всякую нечистоту и остаток злобы, в кротости примите насаждаемое слово, могущее спасти ваши души.",
