        BibleVerse(
            textHy: "Անողորմ դատաստան պիտի լինի ողորմութիւն չ’անողի վերայ. Եւ ողորմութիւնը պարծենում է դատաստանի դէմ։",
            textHyArarat: "որովհետև անողորմի նկատմամբ անողորմ դատաստան է լինելու. ողորմածությունը արհամարհում է դատաստանը։",
            textRu: "Суд без милости не оказавшему милости; милость превозносится над судом.",
