        BibleVerse(
            textHy: "Վերին իմաստութիւնը նախ եւ առաջ սուրբ է, եւ յետոյ խաղաղարար, հեզ, հլու, ողորմութիւնով եւ բարի պտուղներով լիքը, անկողմնասէր, անկեղծ։ Եւ արդարութեան պտուղը խաղաղութիւնով է սերմվում նորանց համար որ խաղաղութիւն են անում։",
            textHyArarat: "Ի վերուստ տրված իմաստությունը նախ սուրբ է, ապա խաղաղարար, հեզ, հաշտվող, ողորմությամբ ու բարի պտուղներով լի, անկողմնակալ, անկեղծ։ Արդարության պտուղը խաղաղությամբ սերմանվում է նրանց համար, ովքեր խաղաղություն են անում։",
            textRu: "Мудрость, сходящая свыше, во-первых, чиста, потом мирна, скромна, послушлива, полна милосердия и добрых плодов, беспристрастна и нелицемерна. Плод же правды в мире сеется у тех, которые хранят мир.",
            textEn: "The wisdom that is from above is first pure, then peaceable, gentle, and easy to be intreated, full of mercy and good fruits, without partiality, and without hypocrisy. And the fruit of righteousness is sown in peace of them that make peace.",
