            textHy: "Աւելի շնորհք է տալիս. Նորա համար ասում է. Աստուած ամբարտաւաններին հակառակ է կենում, բայց խոնարհներին շնորհք է տալիս։",
            textHyArarat: "Ավելի մեծ շնորհ է տալիս. դրա համար ասում է. «Աստված ամբարտավաններին հակառակ է, բայց խոնարհներին շնորհ է տալիս» ։",
            textRu: "Тем большую дает благодать; посему и сказано: Бог гордым противится, а смиренным дает благодать.",
