        ),
        BibleVerse(
            textHy: "Արդ, եղբարքս, երկայնամիտ եղէք մինչեւ Տիրոջ գալուստը, ահա մշակը երկայնամիտ եղած սպասում է երկրի պատուական պտղին, մինչեւ որ առաջի եւ վերջի անձրեւն առնէ։ Երկայնամիտ եղէք դուք էլ, հաստատեցէք ձեր սրտերը. Որ Տիրոջ գալուստը մօտացել է։",
            textHyArarat: "Արդ, եղբայրնե՛ր, մինչև Տիրոջ գալուստը համբերո՛ղ եղեք։ Ահա մշակը համբերությամբ սպասում է հողի պատվական պտղին, մինչև առաջին ու վերջին անձրևը ստանա։ Դո՛ւք էլ համբերատար եղեք, ձեր սրտերը ամրացրե՛ք, որովհետև Տիրոջ գալուստը մոտեցել է։",
            textRu: "Братия, будьте долготерпеливы до пришествия Господня. Вот, земледелец ждет драгоценного плода от земли и для него терпит долго, пока получит дождь ранний и поздний. Долготерпите и вы, укрепите сердца ваши, потому что пришествие Господне приближается.",
            textEn: "Be patient therefore, brethren, unto the coming of the Lord. Behold, the husbandman waiteth for the precious fruit of the earth, and hath long patience for it, until he receive the early and latter rain. Be ye also patient; stablish your hearts: for the coming of the Lord draweth nigh.",
            refHy: "Հակոբոս 5:7-8",
            refRu: "Иакова 5:7-8",
            refEn: "James 5:7-8"
        ),
        BibleVerse(
            textHy: "Սուրբ Հոգուն միջոցով ձեր անձերը սրբելով ճշմարտութեան հնազանդութեամբ, անկեղծ եղբայրսիրութեան համար, մաքուր սրտով իրար սերտ սիրեցէք. Վերստին ծնուած լինելով ոչ թէ ապականութեան սերմից այլ անապական սերմից. Աստուծոյ կենդանի եւ յաւիտենական խօսքովը։",
            textHyArarat: "Մաքրելով ձեր հոգիները ճշմարտությանը հնազանդությամբ՝ անկեղծ եղբայրասիրությամբ, մաքուր սրտով միմյանց ջերմորեն սիրե՛ք՝ վերածնվելով ոչ թե ապականության սերմից, այլ անապականից՝ Աստծու կենդանի ու մնայուն խոսքով։",
            textRu: "Послушанием истине чрез Духа, очистив души ваши к нелицемерному братолюбию, постоянно любите друг друга от чистого сердца, как возрожденные не от тленного семени, но от нетленного, от слова Божия, живаго и пребывающего вовек.",
            textEn: "Seeing ye have purified your souls in obeying the truth through the Spirit unto unfeigned love of the brethren, see that ye love one another with a pure heart fervently: Being born again, not of corruptible seed, but of incorruptible, by the word of God, which liveth and abideth for ever.",
            refHy: "Ա Պետրոս 1:22-23",
            refRu: "1 Петра 1:22-23",
            refEn: "1 Peter 1:22-23"
