        BibleVerse(
            textHy: "Դուք հէնց այդ բանի մէջ կանչուեցաք որ Քրիստոս էլ չարչարուեցաւ եւ ձեզ էլ օրինակ թողեց որ նորա հետքերին հետեւիք.",
            textHyArarat: "Դուք հենց այդ բանի համար կոչվեցիք, քանի որ Քրիստոսն էլ ձեզ համար չարչարվեց և ձեզ օրինակ թողեց, որ իր հետքերով ընթանանք։",
            textRu: "Вы к тому призваны, потому что и Христос пострадал за нас, оставив нам пример, дабы мы шли по следам Его.",
            textEn: "Even hereunto were ye called: because Christ also suffered for us, leaving us an example, that ye should follow his steps.",
            refHy: "Ա Պետրոս 2:21",
            refRu: "1 Петра 2:21",
            refEn: "1 Peter 2:21"
        ),
        BibleVerse(
            textHy: "Որ ինքն մեր մեղքերն իր մարմնումը խաչափայտի վերայ բարձրացրեց. որ մեղքերիցը հեռանալով արդարութեան համար ապրենք, որ նորա խոցերովը բժշկուեցաք։",
            textHyArarat: "Նա մեր մեղքերն իր մարմնով խաչափայտի վրա բարձրացրեց, որպեսզի մեղքերից հեռանալով՝ արդարության համար ապրենք. դուք նրա վերքերով բժշկվեցիք։",
            textRu: "Он грехи наши Сам вознес телом Своим на древо, дабы мы, избавившись от грехов, жили для правды: ранами Его вы исцелились.",
            textEn: "Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.",
            refHy: "Ա Պետրոս 2:24",
            refRu: "1 Петра 2:24",
            refEn: "1 Peter 2:24"
        ),
        BibleVerse(
            textHy: "Այլ Տէր Աստուծուն ձեր սրտի մէջ սուրբ պահեցէք. Եւ միշտ պատրաստ եղէք հեզութեամբ եւ երկիւղածութեամբ պատասխան տալու ամենին, որ ձեր մէջ եղած յոյսի համար պատճառ հարցնէ։",
            textHyArarat: "այլ Տիրոջը՝ Քրիստոսին, ձեր սրտերում սո՛ւրբ պահեք ու միշտ պատրա՛ստ եղեք պատասխան տալու ամեն մեկին, ով ձեր մեջ եղած հույսի մասին հարցնի։",
            textRu: "Господа Бога святите в сердцах ваших; будьте всегда готовы всякому, требующему у вас отчета в вашем уповании, дать ответ с кротостью и благоговением.",
            textEn: "Sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear.",
            refHy: "Ա Պետրոս 3:15",
            refRu: "1 Петра 3:15",
            refEn: "1 Peter 3:15"
        ),
        BibleVerse(
            textHy: "Ամեն մէկդ ինչպէս որ շնորհք է ընդունել՝ այն իրար մատակարարեցէք. Ինչպէս Աստուծոյ կերպ կերպ շնորհաց լաւ տնտեսներ։",
            textHyArarat: "Յուրաքանչյուր ոք ինչ շնորհ ընդունել է, այն իրա՛ր մատակարարեք որպես Աստծու զանազան շնորհների բարի տնտեսներ։",
            textRu: "Служите друг другу, каждый тем даром, какой получил, как добрые домостроители многоразличной благодати Божией.",
            textEn: "As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of God.",
            refHy: "Ա Պետրոս 4:10",
            refRu: "1 Петра 4:10",
            refEn: "1 Peter 4:10"
        ),
        BibleVerse(
            textHy: "Սիրելիներ, օտար բան մի համարէք այն բորբոքուած նեղութիւնը որ ձեզ փորձելու համար լինում է, իբր թէ մի օտար բան է պատահում ձեզ։ Այլ ուրախ եղէք իբրեւ թէ Քրիստոսի չարչարանքին մասնակից եղածներ, որ նորա փառքի յայտնութեան ժամանակումն էլ ցնծալով ուրախանաք։",
            textHyArarat: "Սիրելինե՛ր, տարօրինակ մի՛ համարեք այն այրող նեղությունը, որ ձեզ փորձելու համար է, իբրև թե մի տարօրինակ բան է ձեզ պատահել։ Այլ ուրա՛խ եղեք որպես Քրիստոսի չարչարանքին մասնակիցներ, որպեսզի նրա փառքի հայտնության ժամանակ էլ ցնծալով ուրախանաք։",
            textRu: "Возлюбленные! огненного искушения, для испытания вам посылаемого, не чуждайтесь, как приключения для вас странного, но как вы участвуете в Христовых страданиях, радуйтесь, да и в явление славы Его возрадуетесь и восторжествуете.",
            textEn: "Beloved, think it not strange concerning the fiery trial which is to try you, as though some strange thing happened unto you: But rejoice, inasmuch as ye are partakers of Christ's sufferings; that, when his glory shall be revealed, ye may be glad also with exceeding joy.",
            refHy: "Ա Պետրոս 4:12-13",
            refRu: "1 Петра 4:12-13",
            refEn: "1 Peter 4:12-13"
        ),
        BibleVerse(
            textHy: "Այսպէս էլ դուք, երիտասարդներ, հնազանդեցէք ծերերին, ամենդ իրար հնազանդելով խոնարհութիւնը հագէք. որ Աստուած ամբարտաւաններին հակառակ է կենում, բայց խոնարհներին շնորհք է տալիս։ Խոնարհեցէք Աստուծոյ հզօր ձեռի տակ, որ ձեզ բարձրացնէ ժամանակով։",
            textHyArarat: "Նույնպես և դուք, երիտասարդնե՛ր, հնազանդվե՛ք ծերերին, բոլորդ միմյանց նկատմամբ խոնարհությո՛ւն ունեցեք, որովհետև «Աստված ամբարտավաններին հակառակ է, իսկ խոնարհներին շնորհ է տալիս»։ Աստծու հզոր ձեռքի տակ խոնարհվե՛ք, որպեսզի ձեզ ժամանակին բարձրացնի։",
            textRu: "Также и младшие, повинуйтесь пастырям; все же, подчиняясь друг другу, облекитесь смиренномудрием, потому что Бог гордым противится, а смиренным дает благодать. Итак смиритесь под крепкую руку Божию, да вознесет вас в свое время.",
            textEn: "Likewise, ye younger, submit yourselves unto the elder. Yea, all of you be subject one to another, and be clothed with humility: for God resisteth the proud, and giveth grace to the humble. Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time.",
            refHy: "Ա Պետրոս 5:5-6",
            refRu: "1 Петра 5:5-6",
            refEn: "1 Peter 5:5-6"
        ),
        BibleVerse(
            textHy: "Եւ աճեցէք մեր Տէր եւ Փրկիչ Յիսուս Քրիստոսի շնորհքովը եւ գիտութիւնովը. նորան լինի փառք եւ հիմա եւ մինչեւ յաւիտենական օրն։ Ամէն։",
            textHyArarat: "Աճե՛ք մեր Տեր ու Փրկիչ Հիսուս Քրիստոսի շնորհով և գիտությամբ։ Նրան փա՜ռք այժմ և մինչև հավիտենական օրը։ Ամեն։",
            textRu: "Возрастайте в благодати и познании Господа нашего и Спасителя Иисуса Христа. Ему слава и ныне и в день вечный. Аминь.",
            textEn: "Grow in grace, and in the knowledge of our Lord and Saviour Jesus Christ. To him be glory both now and for ever. Amen.",
            refHy: "Բ Պետրոս 3:18",
            refRu: "2 Петра 3:18",
            refEn: "2 Peter 3:18"
        ),
        BibleVerse(
            textHy: "Եւ սա է այն աւետիքը, որ նորանից լսեցինք եւ պատմում ենք ձեզ, թէ Աստուած լոյս է, եւ ոչ մի խաւար չ’կայ նորանում։",
            textHyArarat: "Եվ սա է այն ավետիսը, որ նրանից լսեցինք ու ձեզ պատմում ենք. Աստված լույս է, և նրա մեջ խավար չկա։",
            textRu: "И вот благовестие, которое мы слышали от Него и возвещаем вам: Бог есть свет, и нет в Нем никакой тьмы.",
            textEn: "This then is the message which we have heard of him, and declare unto you, that God is light, and in him is no darkness at all.",
            refHy: "Ա Հովհաննես 1:5",
            refRu: "1 Иоанна 1:5",
            refEn: "1 John 1:5"
        ),
        BibleVerse(
            textHy: "Եթէ լոյսի մէջ ման գանք ինչպէս նա է լոյսի մէջ, հաղորդութիւն ունինք իրար հետ, եւ նորա Որդի Յիսուս Քրիստոսի արիւնը մեզ սրբում է ամեն մեղքից։",
            textHyArarat: "Եթե լույսի մեջ ենք քայլում, ինչպես որ նա է լույսի մեջ, հաղորդության մեջ ենք միմյանց հետ, և նրա Որդի Հիսուս Քրիստոսի արյունը մեզ մաքրում է ամեն մեղքից։",
            textRu: "Если же ходим во свете, подобно как Он во свете, то имеем общение друг с другом, и Кровь Иисуса Христа, Сына Его, очищает нас от всякого греха.",
            textEn: "If we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.",
            refHy: "Ա Հովհաննես 1:7",
            refRu: "1 Иоанна 1:7",
            refEn: "1 John 1:7"
        ),
        BibleVerse(
            textHy: "Իմ որդեակներս, սա գրում եմ ձեզ որ չ’մեղանչէք, եւ եթէ մէկը մեղանչէ, բարեխօս ունինք Հօր մօտ Յիսուս Քրիստոս արդարին։ Եւ նա քաւութիւն է մեր մեղքերի համար. եւ ոչ միայն մերինների բայց բոլոր աշխարհքի էլ։",
            textHyArarat: "Որդյակնե՛ր իմ, սա գրում եմ ձեզ, որպեսզի չմեղանչեք. իսկ եթե մեկը մեղանչի, բարեխոս ունենք Հոր առաջ Հիսուս Քրիստոսին՝ արդարին։ Եվ նա է քավությունը մեր մեղքերի համար, և ոչ միայն մեր, այլ նաև ամբողջ աշխարհի։",
            textRu: "Дети мои! сие пишу вам, чтобы вы не согрешали; а если бы кто согрешил, то мы имеем ходатая пред Отцем, Иисуса Христа, праведника; Он есть умилостивление за грехи наши, и не только за наши, но и за грехи всего мира.",
            textEn: "My little children, these things write I unto you, that ye sin not. And if any man sin, we have an advocate with the Father, Jesus Christ the righteous: And he is the propitiation for our sins: and not for ours only, but also for the sins of the whole world.",
