            textHyArarat: "Սա է այն վստահությունը, որ նրա նկատմամբ ունենք, թե ինչ որ ըստ նրա կամքի խնդրում ենք, լսում է մեզ։ Եվ եթե գիտենք, որ լսում է մեզ, ինչ որ խնդրում ենք, գիտենք նաև, որ նրանից ստանում ենք մեր խնդրածները։",
