            textHyArarat: "Դուք, սիրելինե՛ր, ձեր անձերը ձեր սուրբ հավատի վրա՛ կառուցեք՝ Սուրբ Հոգով աղոթելով։ Ձեզ Աստծու սիրո մե՛ջ պահեք՝ հավիտենական կյանքի համար մեր Տեր Հիսուս Քրիստոսի ողորմությանն սպասելով։",
