            textHyArarat: "Եվ նրան, որ կարող է անարատ պահել ձեզ և անեղծ կանգնեցնել իր փառքի առջև անխառն ցնծությամբ, այն միակ իմաստուն Աստծուն և մեր Փրկչին՝ մեր Հիսուս Քրիստոսին՝ Տիրոջը, փա՜ռք և մեծություն, զորություն և իշխանություն բոլոր ժամանակներից առաջ և այժմ ու բոլոր ժամանակներում։ Ամեն։",
            textRu: "Могущему же соблюсти вас от падения и поставить пред славою Своею непорочными в радости, Единому Премудрому Богу, Спасителю нашему чрез Иисуса Христа Господа нашего, слава и величие, сила и власть прежде всех веков, ныне и во все веки. Аминь.",
