            textHy: "Ես եմ Ալֆան եւ Օմեգան ասում է Տէրը, նա որ է եւ որ էր եւ որ գալու է, Ամենակալը։",
            textHyArarat: "«Ես եմ Ալֆան ու Օմեգան (սկիզբն ու վերջը)»,- ասում է Տերը՝ Աստված, նա, որ Է, որ էր և որ գալու է՝ Ամենակալը։",
            textRu: "Я есмь Альфа и Омега, начало и конец, говорит Господь, Который есть и был и грядет, Вседержитель.",
            textEn: "I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty.",
            refHy: "Հայտնություն 1:8",
            refRu: "Откровение 1:8",
            refEn: "Revelation 1:8"
        ),
        BibleVerse(
            textHy: "Այլ եւս ոչ կ’սովեն եւ ոչ կ’ծարաւին, եւ չի ընկնիլ նորանց վերայ ոչ արեւը եւ ոչ մի տաքութիւն։ Որովհետեւ Գառը՝ որ աթոռի մէջ է, կ’հովուէ նորանց եւ կ’առաջնորդէ նորանց դէպի կենդանի ջրերի աղբիւրներ. Եւ Աստուած կ’սրբէ ամեն արտասուքը նորանց աչքերիցը։",
            textHyArarat: "Այլևս ո՛չ քաղցելու են, ո՛չ էլ ծարավելու, և ո՛չ արևը նրանց վրա կընկնի, ո՛չ էլ տապը, որովհետև Գառը, որ գահի մեջտեղում է, կհովվի նրանց ու կառաջնորդի դեպի կենաց ջրի աղբյուրները, և Աստված կսրբի ամեն արտասուք նրանց աչքերից»։",
            textRu: "Они не будут уже ни алкать, ни жаждать, и не будет палить их солнце и никакой зной: ибо Агнец, Который среди престола, будет пасти их и водить их на живые источники вод; и отрет Бог всякую слезу с очей их.",
            textEn: "They shall hunger no more, neither thirst any more; neither shall the sun light on them, nor any heat. For the Lamb which is in the midst of the throne shall feed them, and shall lead them unto living fountains of waters: and God shall wipe away all tears from their eyes.",
            refHy: "Հայտնություն 7:16-17",
            refRu: "Откровение 7:16-17",
            refEn: "Revelation 7:16-17"
        ),
        BibleVerse(
            textHy: "Եւ մի մեծ ձայն լսեցի երկնքիցը, որ ասում էր. Ահա Աստուծոյ խորանը մարդկանց հետ, եւ նա կ’բնակուէ նորանց հետ, եւ նորանք կ’լինին նորան ժողովուրդ, եւ ինքն Աստուած նորանց հետ կ’լինի նորանց Աստուած։ Եւ կ’ջնջէ Աստուած բոլոր արտասուքը նորանց աչքերիցը. եւ մահն այլեւս չի լինիլ, ոչ սուգ, եւ ոչ աղաղակ. եւ ոչ ցաւ այլեւս չի լինիլ, որովհետեւ առաջիններն անցան։",
            textHyArarat: "Եվ գահից մի ուժեղ ձայն լսեցի, որ ասում էր. «Ահա Աստծու խորանը, որ նա բնակվելու է մարդկանց հետ։ Նրանք կլինեն նրա ժողովուրդները, իսկ ինքը կլինի նրանց Աստվածը, որ նրանց հետ է։ Եվ նրանց աչքերից պիտի սրբի ամեն արտասուք. այլևս մահ չի լինելու, չի լինելու նաև ո՛չ սուգ, ո՛չ աղաղակ, ո՛չ ցավ, որովհետև նախկիններն անցան»։",
            textRu: "И услышал я громкий голос с неба, говорящий: се, скиния Бога с человеками, и Он будет обитать с ними; они будут Его народом, и Сам Бог с ними будет Богом их. И отрет Бог всякую слезу с очей их, и смерти не будет уже; ни плача, ни вопля, ни болезни уже не будет, ибо прежнее прошло.",
            textEn: "And I heard a great voice out of heaven saying, Behold, the tabernacle of God is with men, and he will dwell with them, and they shall be his people, and God himself shall be with them, and be their God. And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.",
            refHy: "Հայտնություն 21:3-4",
            refRu: "Откровение 21:3-4",
            refEn: "Revelation 21:3-4"
        ),
        BibleVerse(
            textHy: "Եւ ինձ ասեց. Եղաւ, ես եմ Ալֆան եւ Օմեղան. սկիզբը եւ վերջը. ես ձրի կ’տամ ծարաւին կեանքի ջրի աղբիւրիցը։",
            textHyArarat: "Եվ ինձ ասաց. «Եղա՛վ. ես եմ Ալֆան և Օմեգան, Սկիզբն ու Վերջը։ Ես եմ ծարավածին ձրի տալու կենաց ջրի աղբյուրից։",
            textRu: "И сказал мне: совершилось! Я есмь Альфа и Омега, начало и конец; жаждущему дам даром от источника воды живой.",
            textEn: "And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely.",
            refHy: "Հայտնություն 21:6",
            refRu: "Откровение 21:6",
            refEn: "Revelation 21:6"
        ),
        BibleVerse(
            textHy: "Եւ ցոյց տուաւ ինձ մի մաքուր գետ, կենդանի ջրի ակնվանու նման փայլուն, որ դուրս էր գալիս Աստուծոյ եւ Գառի աթոռից։ Եւ նորա հրապարակի միջումը եւ գետի այս կողմին եւ այն կողմին կեանքի ծառ կար, որ տասնեւերկու կերպ պտուղ էր բերում. ամեն մէկ ամիս տալիս էր իր պտուղը. եւ այն ծառի տերեւը բժշկում էր հեթանոսներին։",
            textHyArarat: "Հրեշտակն ինձ ցույց տվեց կենաց ջրի գետը՝ փայլուն, ինչպես բյուրեղը, որ բխում էր Աստծու ու Գառան գահից։ Եվ նրա հրապարակի մեջտեղում՝ գետի այս ու այն կողմերում, կենաց ծառն էր, որ տասներկու պտուղ էր տալիս. ամեն ամիս իր պտուղն էր տալիս, իսկ ծառի տերևները ազգերին բժշկելու համար էին։",
            textRu: "И показал мне чистую реку воды жизни, светлую, как кристалл, исходящую от престола Бога и Агнца. Среди улицы его, и по ту и по другую сторону реки, древо жизни, двенадцать раз приносящее плоды, дающее на каждый месяц плод свой; и листья дерева — для исцеления народов.",
            textEn: "And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb. In the midst of the street of it, and on either side of the river, was there the tree of life, which bare twelve manner of fruits, and yielded her fruit every month: and the leaves of the tree were for the healing of the nations.",
            refHy: "Հայտնություն 22:1-2",
            refRu: "Откровение 22:1-2",
            refEn: "Revelation 22:1-2"
        ),
        BibleVerse(
            textHy: "Այս բաներին վկայողը ասում է. Այո. ես շուտով գալիս եմ։ Ամէն։ Եկ, Տէր Յիսուս։ Մեր Տէր Յիսուս Քրիստոսի շնորհքը լինի ձեր ամենի հետ։ Ամէն։",
            textHyArarat: "Այս բաները վկայողն ասում է. «Այո՛, ես շուտով պիտի գամ»։ Ամե՛ն։ Արի՛, Տե՛ր Հիսուս։ Մեր Տեր Հիսուս Քրիստոսի շնորհը ձեզ բոլորիդ հետ լինի։ Ամե՛ն։",
            textRu: "Свидетельствующий сие говорит: ей, гряду скоро! Аминь. Ей, гряди, Господи Иисусе! Благодать Господа нашего Иисуса Христа со всеми вами. Аминь.",
            textEn: "He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus. The grace of our Lord Jesus Christ be with you all. Amen.",
            refHy: "Հայտնություն 22:20-21",
            refRu: "Откровение 22:20-21",
            refEn: "Revelation 22:20-21"
        ),
    ]
}
